async function excluirPlanejamentoAtual(catId){
 const estado=planejamentoSemanalEstado[catId];const reg=estado&&estado.registro;
 if(!reg)return alert('Nenhum planejamento atual para excluir.');
 if(!confirm('Excluir o planejamento atual de '+(reg.categoria_label||catId)+'?'))return;
 const btn=document.querySelector(`.td-cat-panel[data-cat="${catId}"] .excluir-trabalho`);if(btn){btn.disabled=true;btn.textContent='Excluindo...';}
 try{
  await removerArquivoAntigoPlanejamento(catId);
  const {error}=await _supabase.from('planejamentos_semanais').delete().eq('categoria_id',catId);
  if(error)throw error;
  estado.registro=null;estado.file=null;
  alert('Planejamento atual excluído com sucesso.');
  openPlanejamentoSemanalModal();
 }catch(e){console.error(e);alert('Erro ao excluir planejamento atual.');}
 finally{if(btn){btn.disabled=false;btn.innerHTML='<i class="fa-solid fa-trash"></i> Excluir planejamento atual';}}
}
async function enviarPlanejamentoSemanal(catId){
 if(!await aeExigir())return;
 inicializarEstadoPlanejamentoSemanal();
 const cat=categoriasTrabalhoDiarioConfig()[catId];const estado=planejamentoSemanalEstado[catId];
 if(!estado.file)return alert('Selecione um PDF para enviar.');
 if(estado.file.type && estado.file.type!=='application/pdf' && !estado.file.name.toLowerCase().endsWith('.pdf'))return alert('Envie apenas arquivo PDF.');
 const atletas=destinatariosPlanejamento(catId);
 if(!aeAtletasCat(catId,'planejamento').length)return alert('Nenhum atleta selecionado para este planejamento.');
 const btn=document.querySelector(`#planejamento-semanal-modal .td-cat-panel[data-cat="${catId}"] .enviar`);if(btn){btn.disabled=true;btn.textContent='Enviando...';}
 try{
  await removerArquivoAntigoPlanejamento(catId);
  const safeName=estado.file.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_.-]+/gi,'_');
  const path=`${catId}/${Date.now()}_${safeName}`;
  const up=await _supabase.storage.from(PLANEJAMENTOS_SEMANAIS_BUCKET).upload(path,estado.file,{upsert:true,contentType:'application/pdf'});
  if(up.error)throw up.error;
  const {data:pub}= _supabase.storage.from(PLANEJAMENTOS_SEMANAIS_BUCKET).getPublicUrl(path);
  const agora=new Date();
  const dataReferencia=calcularDataReferenciaPlanejamentoSemanal(agora);
  const payload={categoria_id:catId,categoria_label:cat.label,anos_padrao:cat.anos,arquivo_nome:estado.file.name,storage_path:path,public_url:pub&&pub.publicUrl?pub.publicUrl:'',atletas,data_referencia:dataReferencia,atualizado_em:agora.toISOString()};
  const res=await _supabase.from('planejamentos_semanais').upsert(payload,{onConflict:'categoria_id'});
  if(res.error)throw res.error;
  estado.registro=payload;estado.file=null;
  const nPush=await notificarPortalDocumentoPush({tipo:'planejamento',categoriaId:catId,categoriaLabel:cat.label,anosPadrao:cat.anos,extras:atletas});
  alert('Planejamento enviado para '+cat.label+' com sucesso.'+(nPush?(' Notificação enviada para '+nPush+' aparelho(s).'):' (nenhum app registrado nesta categoria ainda)'));
  openPlanejamentoSemanalModal();
 }catch(e){console.error(e);alert('Erro ao enviar planejamento. Verifique tabela/bucket no Supabase.');}
 finally{if(btn){btn.disabled=false;btn.innerHTML='<i class="fa-solid fa-upload"></i> Enviar/Substituir';}}
}



/* === RELATÓRIO DE VISUALIZAÇÃO - TRABALHOS/PLANEJAMENTOS === */
let relatorioVisualizacaoState={tipo:'trabalho_diario',catId:'sub13',modo:'dia',registro:null};
function rvConfigTipo(tipo){
 if(tipo==='planejamento_semanal')return {tabela:'planejamentos_semanais',estado:planejamentoSemanalEstado,titulo:'Planejamento Semanal'};
 return {tabela:'trabalhos_diarios',estado:trabalhoDiarioEstado,titulo:'Trabalho Diário'};
}
function rvParseDate(v){const s=String(v||'');let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return new Date(+m[1],+m[2]-1,+m[3]);m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);if(m)return new Date(+m[3],+m[2]-1,+m[1]);const d=new Date(s);return isNaN(d)?new Date():d;}
function rvISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function rvBR(d){return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}`;}
function rvDataDocumento(reg){return rvISO(rvParseDate(reg?.data_referencia||reg?.atualizado_em||reg?.criado_em||new Date()));}
function rvInicioSemana(d){const x=new Date(d);const day=x.getDay();if(day===6)x.setDate(x.getDate()+2);else if(day===0)x.setDate(x.getDate()+1);else x.setDate(x.getDate()-(day-1));x.setHours(0,0,0,0);return x;}
function rvDiasUteisSemana(base){const ini=rvInicioSemana(base);return [0,1,2,3,4].map(i=>{const d=new Date(ini);d.setDate(ini.getDate()+i);return d;});}
function rvDiasUteisMes(base){const d=new Date(base.getFullYear(),base.getMonth(),1);const out=[];while(d.getMonth()===base.getMonth()){const day=d.getDay();if(day>=1&&day<=5)out.push(new Date(d));d.setDate(d.getDate()+1);}return out;}
function rvSemanasMes(base){const semanas=[];let d=new Date(base.getFullYear(),base.getMonth(),1);while(d.getMonth()===base.getMonth()){const ini=rvInicioSemana(d);const iso=rvISO(ini);if(!semanas.some(s=>s.iso===iso))semanas.push({iso,date:new Date(ini)});d.setDate(d.getDate()+7);}return semanas;}
function rvChaveDocumento(reg){return String(reg?.storage_path||reg?.public_url||reg?.arquivo_nome||'');}
function rvAccessDate(tipo,a){const dataBase=a?.data_documento||a?.data_referencia||a?.primeiro_acesso_em||a?.ultimo_acesso_em;return tipo==='planejamento_semanal'?rvISO(rvInicioSemana(rvParseDate(dataBase))):String(dataBase||'').slice(0,10);}
function rvDestinatarios(reg,tipo){const mod=tipo==='planejamento_semanal'?'planejamento':'trabalho';return aeAtletasCat(reg?.categoria_id,mod).sort((a,b)=>a.id.apelido.localeCompare(b.id.apelido,'pt-BR'));}
function rvGerarDocumentos(tipo,modo,reg){
 const base=rvParseDate(rvDataDocumento(reg));
 if(tipo==='planejamento_semanal'){
  if(modo==='mes')return rvSemanasMes(base).map(s=>({label:`Semana ${rvBR(s.date)}`,date:s.iso,week:s.iso,current:false}));
  const ini=rvInicioSemana(base);return [{label:`Semana ${rvBR(ini)}`,date:rvISO(ini),week:rvISO(ini),current:true}];
 }
 if(modo==='mes')return rvDiasUteisMes(base).map(d=>({label:rvBR(d),date:rvISO(d),current:false}));
 if(modo==='semana')return rvDiasUteisSemana(base).map(d=>({label:rvBR(d),date:rvISO(d),current:false}));
 const data=rvDataDocumento(reg);return [{label:rvBR(rvParseDate(data)),date:data,current:true}];
}
function rvAtletaViuDocumento(tipo,atleta,doc,acessosRows){
 const nome=atleta.id.nomeCompleto, nasc=atleta.id.nascimento;
 const rows=(acessosRows||[]).filter(r=>normalizarTextoTrabalho(r.nome_completo)===nome && (!nasc || normalizarTextoTrabalho(r.nascimento)===nasc));
 for(const r of rows){
  const arr=Array.isArray(r.acessos)?r.acessos:[];
  for(const a of arr){
   const chave=String(a?.chave_documento||a?.storage_path||'');
   const data=rvAccessDate(tipo,a);
   if(chave && chave===rvChaveDocumento(relatorioVisualizacaoState.registro)){
    const regData=rvDataDocumento(relatorioVisualizacaoState.registro);
    if(tipo==='planejamento_semanal'){
     const regWeek=rvISO(rvInicioSemana(rvParseDate(regData)));
     if(doc.week===regWeek || doc.current)return true;
    }else if(doc.date===regData || doc.current)return true;
   }
   if(tipo==='planejamento_semanal'){
    const week=rvISO(rvInicioSemana(rvParseDate(data)));
    if(week===doc.week)return true;
   }else if(data===doc.date)return true;
  }
  if(!arr.length){const data=String(r.data||'').slice(0,10);if(tipo==='trabalho_diario'&&data===doc.date)return true;}
 }
 return false;
}

function rvBRCompleto(valor){const d=rvParseDate(valor);return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;}
function rvDiaSemanaTexto(valor){return rvParseDate(valor).toLocaleDateString('pt-BR',{weekday:'long'}).replace(/^./,c=>c.toUpperCase());}
function rvNomeAnoAtleta(atleta){return `${atleta?.id?.apelido||atleta?.id?.nomeCompleto||''}${atleta?.id?.ano?` - ${atleta.id.ano}`:''}`;}
function rvRenderListaVisualizacao(tipo,doc,atletas,acessosRows){
 const tituloData=tipo==='planejamento_semanal'
  ? `Semana ${rvBRCompleto(doc.week||doc.date)}`
  : `${rvBRCompleto(doc.date)} — ${rvDiaSemanaTexto(doc.date)}`;
 const ordenados=[...(atletas||[])].sort((a,b)=>String(a.id.apelido||a.id.nomeCompleto||'').localeCompare(String(b.id.apelido||b.id.nomeCompleto||''),'pt-BR'));
 const vistos=[];const ausentes=[];
 ordenados.forEach(a=>{(rvAtletaViuDocumento(tipo,a,doc,acessosRows)?vistos:ausentes).push(a);});
 const lista=(arr,ok)=>arr.length?arr.map(a=>`<li class="${ok?'ok':'no'}"><span>${ok?'✓':'×'}</span>${escapeHtmlJogos(rvNomeAnoAtleta(a))}</li>`).join(''):`<li class="empty">Nenhum atleta.</li>`;
 const rotuloOk=tipo==='planejamento_semanal'?'Visualizaram':'Visualizaram';
 return `<div class="rv-list-report"><div class="rv-list-date">📅 ${escapeHtmlJogos(tituloData)}</div><div class="rv-list-obs"><strong>Observações:</strong> -</div><div class="rv-list-cols"><section class="rv-list-col ok"><h3>${rotuloOk} (${vistos.length})</h3><ul>${lista(vistos,true)}</ul></section><section class="rv-list-col no"><h3>Ausentes (${ausentes.length})</h3><ul>${lista(ausentes,false)}</ul></section></div></div>`;
}
async function abrirRelatorioVisualizacaoDocumento(tipo,catId){
 const cfg=rvConfigTipo(tipo);let reg=cfg.estado?.[catId]?.registro;
 if(!reg){const {data}=await _supabase.from(cfg.tabela).select('*').eq('categoria_id',catId).maybeSingle();reg=data;}
 if(!reg)return alert('Nenhum documento atual encontrado para esta categoria.');
 relatorioVisualizacaoState={tipo,catId,modo:tipo==='planejamento_semanal'?'semana':'dia',registro:reg};
 await renderRelatorioVisualizacaoDocumento();
}
async function renderRelatorioVisualizacaoDocumento(){
 if(!await aeExigir())return;
 const {tipo,catId,modo,registro}=relatorioVisualizacaoState;
 const cfg=rvConfigTipo(tipo);const cat=categoriasTrabalhoDiarioConfig()[catId]||{label:registro?.categoria_label||catId};
 const {data:acessos,error}=await _supabase.from('portal_documentos_acessos').select('*').eq('tipo',tipo).eq('categoria_id',catId);
 if(error){console.error(error);alert('Erro ao carregar relatório de visualização.');return;}
 const atletas=rvDestinatarios(registro,tipo);const docs=rvGerarDocumentos(tipo,modo,registro);
 const listaUnica=(tipo==='trabalho_diario'&&modo==='dia')||(tipo==='planejamento_semanal'&&modo==='semana');
 let conteudo='';
 if(listaUnica){
  conteudo=rvRenderListaVisualizacao(tipo,docs[0],atletas,acessos||[]);
 }else{
  const headDocs=docs.map(d=>`<th>${escapeHtmlJogos(d.label)}</th>`).join('');
  const rows=atletas.map(a=>`<tr><td>${escapeHtmlJogos(a.id.apelido||a.id.nomeCompleto)} <small>${escapeHtmlJogos(a.id.ano||'')}</small></td>${docs.map(d=>`<td class="rv-check">${rvAtletaViuDocumento(tipo,a,d,acessos||[])?'<span>V</span>':''}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="2">Nenhum atleta encontrado.</td></tr>';
  conteudo=`<div class="rv-table-wrap"><table class="rv-table"><thead><tr><th>Atleta</th>${headDocs}</tr></thead><tbody>${rows}</tbody></table></div>`;
 }
 let modal=document.getElementById('relatorio-visualizacao-modal');if(!modal){modal=document.createElement('div');modal.id='relatorio-visualizacao-modal';modal.className='relatorio-visualizacao-overlay';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeRelatorioVisualizacao();});}
 const filtros=tipo==='planejamento_semanal'
  ? `<button class="${modo==='semana'?'active':''}" onclick="setRelatorioVisualizacaoModo('semana')">Semana</button><button class="${modo==='mes'?'active':''}" onclick="setRelatorioVisualizacaoModo('mes')">Mês</button>`
  : `<button class="${modo==='dia'?'active':''}" onclick="setRelatorioVisualizacaoModo('dia')">Dia</button><button class="${modo==='semana'?'active':''}" onclick="setRelatorioVisualizacaoModo('semana')">Semana</button><button class="${modo==='mes'?'active':''}" onclick="setRelatorioVisualizacaoModo('mes')">Mês</button>`;
 modal.innerHTML=`<div class="relatorio-visualizacao-card"><button class="relatorios-menu-close" onclick="closeRelatorioVisualizacao()">×</button><div class="rv-header"><img src="logo.png"><div><h2>Relatório de visualização</h2><strong>${escapeHtmlJogos(cfg.titulo)} - ${escapeHtmlJogos(cat.label)}</strong></div><img src="logo.png"></div><div class="rv-filtros">${filtros}<button onclick="imprimirRelatorioVisualizacao()">PDF/Imprimir</button></div>${conteudo}</div>`;
 modal.style.display='flex';
}
function setRelatorioVisualizacaoModo(modo){if(relatorioVisualizacaoState.tipo==='planejamento_semanal'&&modo==='dia')modo='semana';relatorioVisualizacaoState.modo=modo;renderRelatorioVisualizacaoDocumento();}
function closeRelatorioVisualizacao(){const m=document.getElementById('relatorio-visualizacao-modal');if(m)m.style.display='none';}
function imprimirRelatorioVisualizacao(){const card=document.querySelector('#relatorio-visualizacao-modal .relatorio-visualizacao-card');if(!card)return;const w=window.open('','_blank','width=1000,height=800');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Relatório de visualização</title><style>body{font-family:Arial,sans-serif;margin:12px}.relatorios-menu-close,.rv-filtros{display:none}.rv-header{display:flex;align-items:center;justify-content:center;gap:20px}.rv-header img{width:60px}.rv-header h2{text-align:center;margin:0}.rv-header strong{display:block;text-align:center}.rv-table{width:100%;border-collapse:collapse;font-size:12px}.rv-table th{background:#58111a;color:#f9c614}.rv-table th,.rv-table td{border:1px solid #999;padding:5px;text-align:center}.rv-table td:first-child{text-align:left}.rv-check span{color:green;font-weight:bold;font-size:16px}.rv-list-report{border:1px solid #d8e8c4;background:#fbfff7;padding:10px}.rv-list-date{font-size:17px;color:#5c8a2a;font-weight:bold;border-bottom:1px solid #e5eadf;padding:6px}.rv-list-obs{font-size:13px;margin:8px 0}.rv-list-cols{display:grid;grid-template-columns:1fr 1fr;gap:24px}.rv-list-col h3{font-size:14px;margin:6px 0}.rv-list-col.ok h3,.rv-list-col.ok li{color:#078c49}.rv-list-col.no h3,.rv-list-col.no li{color:#c00000}.rv-list-col ul{list-style:none;padding:0;margin:0}.rv-list-col li{font-size:12px;line-height:1.35;margin:2px 0}.rv-list-col li.empty{color:#777}@media(max-width:700px){.rv-list-cols{grid-template-columns:1fr}}</style></head><body>${card.outerHTML}<script>window.onload=()=>setTimeout(()=>window.print(),400)<\/script></body></html>`);w.document.close();}



/* === GOLEIROS - INFORMAÇÕES TÉCNICAS === */
const GOLEIROS_INFO_TABELA = 'goleiros_informacoes_tecnicas';
const GOLEIROS_JOGOS_TABELA = 'goleiros_informacoes_jogos';
let goleirosTecnicoState = { selecionadoIndex: null, registro: null, carregando: false, jogos: [], jogoId: null, jogoModo: 'idle' };

function goleiroEscape(valor){return typeof escapeHtmlJogos==='function'?escapeHtmlJogos(valor):String(valor??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[s]));}
function goleiroNormalizar(valor){return String(valor||'').trim().replace(/\s+/g,' ');}
function goleiroValorFlex(row, termos){const chave=Object.keys(row||{}).find(k=>termos.some(t=>String(k).toLowerCase().includes(String(t).toLowerCase())));return chave?row[chave]:'';}
function goleiroAno(row){return goleiroNormalizar(valorColunaExata(row,'Ano')||goleiroValorFlex(row,['ano']));}
function goleiroNomeCompleto(row){return goleiroNormalizar(goleiroValorFlex(row,['nome completo'])||valorColunaExata(row,'NOME COMPLETO')||goleiroValorFlex(row,['nome']));}
function goleiroApelido(row){return goleiroNormalizar(goleiroValorFlex(row,['apelido'])||valorColunaExata(row,'APELIDO')||goleiroNomeCompleto(row));}
function goleiroNascimento(row){return goleiroNormalizar(convertExcelDate(goleiroValorFlex(row,['data de nascimento','nascimento']))||goleiroValorFlex(row,['data de nascimento','nascimento']));}
function goleiroPosicao(row){return goleiroNormalizar(`${goleiroValorFlex(row,['posição 1','posicao 1','posição','posicao'])} ${goleiroValorFlex(row,['posição 2','posicao 2'])}`);}
function goleiroFoto(row){return goleiroNormalizar(goleiroValorFlex(row,['foto','imagem']))||'logo.png';}
function goleiroIdentidade(index){const row=excelData[index]||{};return {index,nomeCompleto:goleiroNomeCompleto(row),apelido:goleiroApelido(row),nascimento:goleiroNascimento(row),ano:goleiroAno(row),posicao:goleiroPosicao(row),foto:goleiroFoto(row)};}
function goleirosListaTecnica(){
 return (excelData||[]).map((row,index)=>goleiroIdentidade(index))
  .filter(g=>g.nomeCompleto&&g.nascimento&&String(g.posicao||'').toLowerCase().includes('goleiro'))
  .sort((a,b)=>String(a.ano).localeCompare(String(b.ano),'pt-BR',{numeric:true})||String(a.apelido).localeCompare(String(b.apelido),'pt-BR'));
}
function goleiroBRData(data){
 if(!data)return '';
 const d=new Date(data);
 if(isNaN(d))return '';
 return d.toLocaleString('pt-BR');
}
function goleiroJogoDataBR(v){
 const s=String(v||'').slice(0,10);
 const m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
 return m?`${m[3]}/${m[2]}/${m[1]}`:s;
}
function goleiroSelecionadoAtual(){
 const idx=parseInt(goleirosTecnicoState.selecionadoIndex,10);
 return Number.isInteger(idx)&&idx>=0?goleiroIdentidade(idx):null;
}
function goleiroMontarCard(g){
 if(!g)return '<div class="goleiro-info-empty">Selecione um goleiro para visualizar e editar as informações técnicas.</div>';
 return `<div class="goleiro-player-card"><img src="${goleiroEscape(g.foto)}" onerror="this.src='logo.png'" alt="${goleiroEscape(g.apelido)}"><div><strong>${goleiroEscape(g.apelido||g.nomeCompleto)}</strong><span>${goleiroEscape(g.nomeCompleto)}</span><small>Ano ${goleiroEscape(g.ano||'-')} • Nasc. ${goleiroEscape(g.nascimento||'-')}</small></div></div>`;
}
function goleiroJogoAtual(){
 const id=goleirosTecnicoState.jogoId;
 if(!id)return null;
 return (goleirosTecnicoState.jogos||[]).find(j=>String(j.id)===String(id))||null;
}
function renderGoleirosTecnicoModal(){
 const modal=document.getElementById('goleiros-tecnico-modal');if(!modal)return;
 const goleiros=goleirosListaTecnica();
 const selecionado=goleiroSelecionadoAtual();
 const registro=goleirosTecnicoState.registro;
 const texto=registro?.informacoes_tecnicas||'';
 const atualizado=registro?.atualizado_em?`Última atualização: ${goleiroBRData(registro.atualizado_em)}`:'Nenhuma informação salva ainda.';
 const options=goleiros.map(g=>`<option value="${g.index}" ${String(g.index)===String(goleirosTecnicoState.selecionadoIndex)?'selected':''}>${goleiroEscape(g.apelido)} - ${goleiroEscape(g.ano)}</option>`).join('');
 const jogos=goleirosTecnicoState.jogos||[];
 const jogo=goleiroJogoAtual();
 const mostrarDetalhe=!!jogo && goleirosTecnicoState.jogoModo==='editar';
 const jogosOpts=jogos.map(j=>`<option value="${goleiroEscape(String(j.id))}" ${mostrarDetalhe&&String(j.id)===String(goleirosTecnicoState.jogoId)?'selected':''}>${goleiroEscape(goleiroJogoDataBR(j.data_jogo))} – ${goleiroEscape(j.adversario||'Adversário')}</option>`).join('');
 const dataVal=mostrarDetalhe?String(jogo?.data_jogo||'').slice(0,10):'';
 const advVal=mostrarDetalhe?(jogo?.adversario||''):'';
 const infoJogoVal=mostrarDetalhe?(jogo?.informacoes||''):'';
 const disabled=!selecionado?'disabled':'';
 const detalhe=mostrarDetalhe?`<div class="goleiros-jogo-campos"><label class="goleiros-label" for="goleiro-jogo-data">Data do jogo</label><input type="date" id="goleiro-jogo-data" value="${goleiroEscape(dataVal)}" ${disabled}><label class="goleiros-label" for="goleiro-jogo-adversario">Adversário</label><input type="text" id="goleiro-jogo-adversario" placeholder="Nome do adversário" value="${goleiroEscape(advVal)}" ${disabled}><label class="goleiros-label" for="goleiro-jogo-info">Informação do jogo</label><textarea id="goleiro-jogo-info" placeholder="Escreva aqui a informação deste jogo..." ${disabled}>${goleiroEscape(infoJogoVal)}</textarea></div><div class="goleiros-jogo-acoes"><button type="button" onclick="salvarGoleiroJogo()" ${selecionado?'':'disabled'}>Salvar jogo</button><button type="button" class="goleiros-jogo-excluir" onclick="excluirGoleiroJogo()" ${selecionado?'':'disabled'}>Excluir jogo</button><span id="goleiro-jogo-status"></span></div>`:'';
 modal.innerHTML=`<div class="goleiros-tecnico-card"><button class="goleiros-close" onclick="closeGoleirosTecnicoModal()">×</button><div class="goleiros-head"><img src="logo.png"><div><h2>Goleiros</h2><p>Informações técnicas individuais dos goleiros</p></div></div><div class="goleiros-body"><aside><label class="goleiros-label">Selecionar goleiro</label><select id="goleiro-tecnico-select" onchange="selecionarGoleiroTecnico(this.value)" ${goleiros.length?'':'disabled'}><option value="">${goleiros.length?'Escolha um goleiro...':'Nenhum goleiro encontrado'}</option>${options}</select>${goleiroMontarCard(selecionado)}</aside><section><div class="goleiros-textarea-group"><label class="goleiros-text-title" for="goleiro-info-textarea">Informações Técnicas:</label><textarea id="goleiro-info-textarea" placeholder="Escreva aqui as informações técnicas do goleiro selecionado..." ${disabled}>${goleiroEscape(texto)}</textarea></div><div class="goleiros-footer"><span id="goleiro-info-status">${goleirosTecnicoState.carregando?'Carregando...':goleiroEscape(atualizado)}</span><button type="button" onclick="salvarGoleiroInformacoesTecnicas()" ${selecionado?'':'disabled'}>Salvar informações técnicas</button></div><div class="goleiros-jogos-box"><div class="goleiros-jogos-head"><label class="goleiros-text-title">Informações do jogo</label><button type="button" class="goleiros-jogo-novo" onclick="novoGoleiroJogo()" ${disabled}>Novo jogo</button></div><label class="goleiros-label" for="goleiro-jogo-select">Selecionar o jogo</label><select id="goleiro-jogo-select" onchange="selecionarGoleiroJogo(this.value)" ${disabled}><option value="">Selecione o jogo</option>${jogosOpts}</select>${detalhe}</div></section></div></div>`;
 modal.style.display='flex';
}
async function openGoleirosTecnicoModal(){
 let modal=document.getElementById('goleiros-tecnico-modal');
 if(!modal){modal=document.createElement('div');modal.id='goleiros-tecnico-modal';modal.className='goleiros-tecnico-overlay';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeGoleirosTecnicoModal();});}
 const goleiros=goleirosListaTecnica();
 goleirosTecnicoState={selecionadoIndex:goleiros[0]?.index??null,registro:null,carregando:false,jogos:[],jogoId:null,jogoModo:'idle'};
 renderGoleirosTecnicoModal();
 if(goleirosTecnicoState.selecionadoIndex!==null) await carregarGoleiroInformacaoTecnica();
}
function closeGoleirosTecnicoModal(){const modal=document.getElementById('goleiros-tecnico-modal');if(modal)modal.style.display='none';fecharPopupNovoGoleiroJogo();}
async function selecionarGoleiroTecnico(index){
 goleirosTecnicoState.selecionadoIndex=index!==''?parseInt(index,10):null;
 goleirosTecnicoState.registro=null;
 goleirosTecnicoState.jogos=[];
 goleirosTecnicoState.jogoId=null;
 goleirosTecnicoState.jogoModo='idle';
 renderGoleirosTecnicoModal();
 if(goleirosTecnicoState.selecionadoIndex!==null) await carregarGoleiroInformacaoTecnica();
}
async function carregarGoleiroInformacaoTecnica(){
 const g=goleiroSelecionadoAtual();if(!g)return;
 const keepId=goleirosTecnicoState.jogoId;
 const keepModo=goleirosTecnicoState.jogoModo;
 goleirosTecnicoState.carregando=true;renderGoleirosTecnicoModal();
 try{
  const [{data,error},{data:jogos,error:erroJogos}]=await Promise.all([
   _supabase.from(GOLEIROS_INFO_TABELA).select('*').eq('nome_completo',g.nomeCompleto).eq('nascimento',g.nascimento).maybeSingle(),
   _supabase.from(GOLEIROS_JOGOS_TABELA).select('*').eq('nome_completo',g.nomeCompleto).eq('nascimento',g.nascimento).order('data_jogo',{ascending:false}).order('atualizado_em',{ascending:false})
  ]);
  if(error)throw error;
  if(erroJogos)throw erroJogos;
  goleirosTecnicoState.registro=data||null;
  goleirosTecnicoState.jogos=Array.isArray(jogos)?jogos:[];
  const aindaExiste=keepId && goleirosTecnicoState.jogos.some(j=>String(j.id)===String(keepId));
  if(aindaExiste && keepModo==='editar'){
   goleirosTecnicoState.jogoId=keepId;
   goleirosTecnicoState.jogoModo='editar';
  }else{
   goleirosTecnicoState.jogoId=null;
   goleirosTecnicoState.jogoModo='idle';
  }
 }catch(e){console.error(e);alert('Não foi possível carregar informações do goleiro. Verifique as tabelas no Supabase.');}
 finally{goleirosTecnicoState.carregando=false;renderGoleirosTecnicoModal();}
}
async function salvarGoleiroInformacoesTecnicas(){
 const g=goleiroSelecionadoAtual();if(!g)return alert('Selecione um goleiro.');
 const textarea=document.getElementById('goleiro-info-textarea');
 const status=document.getElementById('goleiro-info-status');
 const info=String(textarea?.value||'').trim();
 const btn=document.querySelector('#goleiros-tecnico-modal .goleiros-footer button');
 if(btn){btn.disabled=true;btn.textContent='Salvando...';}
 if(status)status.textContent='Salvando no Supabase...';
 const payload={nome_completo:g.nomeCompleto,nascimento:g.nascimento,apelido:g.apelido,ano:g.ano,informacoes_tecnicas:info,informacoes_jogo:goleirosTecnicoState.registro?.informacoes_jogo||'',atualizado_em:new Date().toISOString()};
 try{
  const {error}=await _supabase.from(GOLEIROS_INFO_TABELA).upsert(payload,{onConflict:'nome_completo,nascimento'});
  if(error)throw error;
  goleirosTecnicoState.registro=Object.assign({},goleirosTecnicoState.registro||{},payload);
  if(status)status.textContent=info?'Informações técnicas salvas.':'Informações técnicas apagadas e salvas em branco.';
  alert((info?'Informações técnicas salvas para ':'Informações técnicas apagadas para ')+(g.apelido||g.nomeCompleto)+'.');
 }catch(e){console.error(e);alert('Erro ao salvar informações técnicas. Verifique a tabela/políticas no Supabase.');if(status)status.textContent='Erro ao salvar.';}
 finally{if(btn){btn.disabled=false;btn.textContent='Salvar informações técnicas';}}
}
function fecharPopupNovoGoleiroJogo(){
 const pop=document.getElementById('goleiros-jogo-novo-overlay');
 if(pop)pop.style.display='none';
}
function novoGoleiroJogo(){
 const g=goleiroSelecionadoAtual();
 if(!g)return alert('Selecione um goleiro.');
 let pop=document.getElementById('goleiros-jogo-novo-overlay');
 if(!pop){
  pop=document.createElement('div');
  pop.id='goleiros-jogo-novo-overlay';
  pop.className='goleiros-jogo-novo-overlay';
  document.body.appendChild(pop);
  pop.addEventListener('click',e=>{if(e.target===pop)fecharPopupNovoGoleiroJogo();});
 }
 pop.innerHTML=`<div class="goleiros-jogo-novo-card"><button type="button" class="goleiros-close" onclick="fecharPopupNovoGoleiroJogo()">×</button><h3>Novo jogo</h3><p>${goleiroEscape(g.apelido||g.nomeCompleto)}</p><label class="goleiros-label" for="goleiro-jogo-novo-data">Data do jogo</label><input type="date" id="goleiro-jogo-novo-data"><label class="goleiros-label" for="goleiro-jogo-novo-adversario">Adversário</label><input type="text" id="goleiro-jogo-novo-adversario" placeholder="Nome do adversário"><label class="goleiros-label" for="goleiro-jogo-novo-info">Informação do jogo</label><textarea id="goleiro-jogo-novo-info" placeholder="Escreva aqui a informação deste jogo..."></textarea><div class="goleiros-jogo-acoes"><button type="button" onclick="salvarNovoGoleiroJogoPopup()">Salvar jogo</button><button type="button" class="goleiros-jogo-excluir" onclick="fecharPopupNovoGoleiroJogo()">Cancelar</button></div></div>`;
 pop.style.display='flex';
}
function selecionarGoleiroJogo(id){
 if(!id){
  goleirosTecnicoState.jogoId=null;
  goleirosTecnicoState.jogoModo='idle';
  renderGoleirosTecnicoModal();
  return;
 }
 goleirosTecnicoState.jogoId=id;
 goleirosTecnicoState.jogoModo='editar';
 renderGoleirosTecnicoModal();
}
async function persistirGoleiroJogo(payload, manterId){
 const {data,error}=await _supabase.from(GOLEIROS_JOGOS_TABELA).upsert(payload).select().maybeSingle();
 if(error)throw error;
 goleirosTecnicoState.jogoId=(data&&data.id)||manterId||null;
 goleirosTecnicoState.jogoModo=goleirosTecnicoState.jogoId?'editar':'idle';
 await carregarGoleiroInformacaoTecnica();
}
async function salvarNovoGoleiroJogoPopup(){
 const g=goleiroSelecionadoAtual();if(!g)return alert('Selecione um goleiro.');
 const dataJogo=String(document.getElementById('goleiro-jogo-novo-data')?.value||'').trim();
 const adversario=goleiroNormalizar(document.getElementById('goleiro-jogo-novo-adversario')?.value||'');
 const informacoes=String(document.getElementById('goleiro-jogo-novo-info')?.value||'').trim();
 if(!dataJogo)return alert('Informe a data do jogo.');
 if(!adversario)return alert('Informe o adversário.');
 const payload={nome_completo:g.nomeCompleto,nascimento:g.nascimento,apelido:g.apelido,ano:g.ano,data_jogo:dataJogo,adversario,informacoes,atualizado_em:new Date().toISOString()};
 try{
  await persistirGoleiroJogo(payload,null);
  fecharPopupNovoGoleiroJogo();
  alert('Jogo salvo.');
 }catch(e){console.error(e);alert('Erro ao salvar o jogo. Verifique a tabela goleiros_informacoes_jogos no Supabase.');}
}
async function salvarGoleiroJogo(){
 const g=goleiroSelecionadoAtual();if(!g)return alert('Selecione um goleiro.');
 if(goleirosTecnicoState.jogoModo!=='editar'||!goleirosTecnicoState.jogoId)return alert('Selecione um jogo.');
 const dataJogo=String(document.getElementById('goleiro-jogo-data')?.value||'').trim();
 const adversario=goleiroNormalizar(document.getElementById('goleiro-jogo-adversario')?.value||'');
 const informacoes=String(document.getElementById('goleiro-jogo-info')?.value||'').trim();
 const status=document.getElementById('goleiro-jogo-status');
 if(!dataJogo)return alert('Informe a data do jogo.');
 if(!adversario)return alert('Informe o adversário.');
 const payload={id:goleirosTecnicoState.jogoId,nome_completo:g.nomeCompleto,nascimento:g.nascimento,apelido:g.apelido,ano:g.ano,data_jogo:dataJogo,adversario,informacoes,atualizado_em:new Date().toISOString()};
 try{
  if(status)status.textContent='Salvando jogo...';
  await persistirGoleiroJogo(payload,payload.id);
  const st=document.getElementById('goleiro-jogo-status');
  if(st)st.textContent='Jogo salvo.';
 }catch(e){console.error(e);alert('Erro ao salvar o jogo. Verifique a tabela goleiros_informacoes_jogos no Supabase.');if(status)status.textContent='Erro ao salvar jogo.';}
}
async function excluirGoleiroJogo(){
 const g=goleiroSelecionadoAtual();if(!g)return;
 const id=goleirosTecnicoState.jogoId;
 if(!id || goleirosTecnicoState.jogoModo!=='editar')return alert('Selecione um jogo para excluir.');
 const jogo=goleiroJogoAtual();
 const rotulo=jogo?`${goleiroJogoDataBR(jogo.data_jogo)} – ${jogo.adversario||''}`:'este jogo';
 if(!confirm('Excluir as informações de '+rotulo+'?'))return;
 try{
  const {error}=await _supabase.from(GOLEIROS_JOGOS_TABELA).delete().eq('id',id).eq('nome_completo',g.nomeCompleto).eq('nascimento',g.nascimento);
  if(error)throw error;
  goleirosTecnicoState.jogoId=null;
  goleirosTecnicoState.jogoModo='idle';
  await carregarGoleiroInformacaoTecnica();
 }catch(e){console.error(e);alert('Erro ao excluir o jogo.');}
}

/* === PREPARAÇÃO FÍSICA - QUEIXAS DOS ATLETAS === */
const PREPARACAO_FISICA_TABELA = 'portal_preparacao_fisica';
let preparacaoFisicaState = { lista: [], selecionadoId: null, filtro: 'pendente', carregando: false };

let preparacaoFisicaPendentesCount = 0;
function renderIndicadorPreparacaoFisica(){
 const count=Number(preparacaoFisicaPendentesCount)||0;
 document.querySelectorAll('[data-prep-alert]').forEach(el=>{
  el.classList.toggle('prep-alerta-pendente',count>0);
  if(count>0){el.setAttribute('data-prep-count',String(count));el.title=`${count} queixa(s) pendente(s) na Preparação Física`;}
  else{el.removeAttribute('data-prep-count');el.title='Preparação Física';}
 });
}
async function atualizarIndicadorPreparacaoFisica(){
 try{
  const {count,error}=await _supabase.from(PREPARACAO_FISICA_TABELA).select('id',{count:'exact',head:true}).eq('status','pendente');
  if(error){console.warn('Indicador de preparação física não carregado:',error.message);return;}
  preparacaoFisicaPendentesCount=count||0;
  renderIndicadorPreparacaoFisica();
 }catch(e){console.warn('Erro ao atualizar indicador de preparação física:',e);}
}

function prepEscape(valor){return typeof escapeHtmlJogos==='function'?escapeHtmlJogos(valor):String(valor??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[s]));}
function prepISO(data){const d=new Date(data);if(isNaN(d))return '';return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function prepHojeISO(){return prepISO(new Date());}
function prepBR(valor){if(!valor)return '';const s=String(valor);let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return `${m[3]}/${m[2]}/${m[1]}`;const d=new Date(s);return isNaN(d)?'':d.toLocaleString('pt-BR');}
function prepDataRespostaAte(dias){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+(Math.max(1,parseInt(dias,10)||1)-1));return prepISO(d);}
function prepLinhaStatus(row){
 const resp=String(row?.resposta||'').trim();
 if(resp){
  const ate=String(row?.resposta_ate||'').slice(0,10);
  if(ate && ate < prepHojeISO())return {classe:'expirada',label:'Resposta expirada'};
  return {classe:'respondida',label:'Respondida'};
 }
 return {classe:'pendente',label:'Pendente'};
}
function prepListaFiltrada(){
 const lista=preparacaoFisicaState.lista||[];
 if(preparacaoFisicaState.filtro==='todas')return lista;
 return lista.filter(r=>{
  const st=prepLinhaStatus(r).classe;
  if(preparacaoFisicaState.filtro==='pendente')return st==='pendente';
  if(preparacaoFisicaState.filtro==='respondida')return st==='respondida';
  if(preparacaoFisicaState.filtro==='expirada')return st==='expirada';
  return true;
 });
}
function prepSelecionada(){return (preparacaoFisicaState.lista||[]).find(r=>String(r.id)===String(preparacaoFisicaState.selecionadoId))||null;}
function prepResumoTexto(txt,tam=90){txt=String(txt||'').trim();return txt.length>tam?txt.slice(0,tam-1)+'…':txt;}
function renderPreparacaoFisicaQueixasModal(){
 const modal=document.getElementById('preparacao-fisica-modal');if(!modal)return;
 const lista=prepListaFiltrada();
 const selecionada=prepSelecionada();
 const filtros=['pendente','respondida','expirada','todas'].map(f=>`<button class="${preparacaoFisicaState.filtro===f?'active':''}" onclick="setPreparacaoFisicaFiltro('${f}')">${f==='pendente'?'Pendentes':f==='respondida'?'Respondidas':f==='expirada'?'Expiradas':'Todas'}</button>`).join('');
 const linhas=lista.map(r=>{const st=prepLinhaStatus(r);const ativo=String(r.id)===String(preparacaoFisicaState.selecionadoId);return `<button class="prep-queixa-item ${ativo?'active':''}" onclick="selecionarPreparacaoFisicaQueixa('${r.id}')"><div><strong>${prepEscape(r.apelido||r.nome_completo||'Atleta')}</strong><span>${prepEscape(r.ano||'')} • ${prepBR(r.criado_em)}</span></div><p>${prepEscape(prepResumoTexto(r.queixa||''))}</p><em class="${st.classe}">${st.label}</em></button>`;}).join('')||'<div class="prep-empty">Nenhuma queixa encontrada neste filtro.</div>';
 const detalhe=selecionada?renderPreparacaoFisicaDetalhe(selecionada):'<div class="prep-detalhe-empty">Selecione uma queixa para responder.</div>';
 modal.innerHTML=`<div class="prep-fisica-card"><button class="prep-close" onclick="closePreparacaoFisicaQueixasModal()">×</button><div class="prep-head"><img src="logo.png"><div><h2>Preparação Física</h2><p>Queixas de dores enviadas pelos atletas</p></div></div><div class="prep-toolbar"><div>${filtros}</div><button class="prep-refresh" onclick="carregarPreparacaoFisicaQueixas()">Atualizar</button></div><div class="prep-layout"><aside><div class="prep-list-head"><b>Queixas</b><span>${lista.length} registro(s)</span></div><div class="prep-list">${preparacaoFisicaState.carregando?'<div class="prep-loading">Carregando...</div>':linhas}</div></aside><section>${detalhe}</section></div></div>`;
 modal.style.display='flex';
 atualizarPreparacaoFisicaDataAtePreview();
}
function renderPreparacaoFisicaDetalhe(r){
 const st=prepLinhaStatus(r);
 const dias=Number(r.resposta_dias)||3;
 return `<div class="prep-detalhe"><div class="prep-atleta"><strong>${prepEscape(r.apelido||r.nome_completo||'Atleta')}</strong><span>${prepEscape(r.nome_completo||'')}</span><small>Ano ${prepEscape(r.ano||'-')} • Nasc. ${prepEscape(r.nascimento||'-')} • Enviado em ${prepBR(r.criado_em)}</small><em class="${st.classe}">${st.label}</em></div><label>Queixa do atleta</label><div class="prep-queixa-texto">${prepEscape(r.queixa||'').replace(/\n/g,'<br>')}</div><label for="prep-resposta-textarea">Resposta / recomendação</label><div class="prep-quick"><button onclick="setPreparacaoRespostaRapida('Visto',1)">Visto</button><button onclick="setPreparacaoRespostaRapida('Não realizar academia.',3)">Não realizar academia</button><button onclick="setPreparacaoRespostaRapida('Reduzir carga e avisar a preparação física antes do treino.',3)">Reduzir carga</button><button onclick="setPreparacaoRespostaRapida('Procurar a preparação física antes do treino.',2)">Procurar preparação</button></div><textarea id="prep-resposta-textarea" placeholder="Digite a resposta para o atleta...">${prepEscape(r.resposta||'')}</textarea><div class="prep-dias"><label>Dias que a resposta ficará visível<input id="prep-resposta-dias" type="number" min="1" max="30" value="${dias}" oninput="atualizarPreparacaoFisicaDataAtePreview()"></label><span id="prep-resposta-ate-preview"></span></div><div class="prep-actions"><button class="salvar" onclick="salvarRespostaPreparacaoFisica()">Salvar resposta</button><button class="limpar" onclick="limparRespostaPreparacaoFisica()">Limpar resposta</button></div></div>`;
}
async function openPreparacaoFisicaQueixasModal(){
 let modal=document.getElementById('preparacao-fisica-modal');
 if(!modal){modal=document.createElement('div');modal.id='preparacao-fisica-modal';modal.className='prep-fisica-overlay';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closePreparacaoFisicaQueixasModal();});}
 modal.style.display='flex';
 renderPreparacaoFisicaQueixasModal();
 await carregarPreparacaoFisicaQueixas();
}
function closePreparacaoFisicaQueixasModal(){const modal=document.getElementById('preparacao-fisica-modal');if(modal)modal.style.display='none';}
async function carregarPreparacaoFisicaQueixas(){
 preparacaoFisicaState.carregando=true;renderPreparacaoFisicaQueixasModal();
 try{
  const {data,error}=await _supabase.from(PREPARACAO_FISICA_TABELA).select('*').order('criado_em',{ascending:false});
  if(error)throw error;
  preparacaoFisicaState.lista=data||[];
  preparacaoFisicaPendentesCount=preparacaoFisicaState.lista.filter(r=>String(r.status||'').toLowerCase()==='pendente').length;
  renderIndicadorPreparacaoFisica();
  if(!preparacaoFisicaState.lista.some(r=>String(r.id)===String(preparacaoFisicaState.selecionadoId)))preparacaoFisicaState.selecionadoId=preparacaoFisicaState.lista[0]?.id||null;
 }catch(e){console.error(e);alert('Erro ao carregar queixas. Verifique a tabela portal_preparacao_fisica no Supabase.');preparacaoFisicaState.lista=[];}
 finally{preparacaoFisicaState.carregando=false;renderPreparacaoFisicaQueixasModal();}
}
function setPreparacaoFisicaFiltro(filtro){preparacaoFisicaState.filtro=filtro;renderPreparacaoFisicaQueixasModal();}
function selecionarPreparacaoFisicaQueixa(id){preparacaoFisicaState.selecionadoId=id;renderPreparacaoFisicaQueixasModal();}
function setPreparacaoRespostaRapida(texto,dias){const t=document.getElementById('prep-resposta-textarea');if(t)t.value=texto;const d=document.getElementById('prep-resposta-dias');if(d)d.value=dias||3;atualizarPreparacaoFisicaDataAtePreview();}
function atualizarPreparacaoFisicaDataAtePreview(){const el=document.getElementById('prep-resposta-ate-preview');if(!el)return;const dias=document.getElementById('prep-resposta-dias')?.value||1;el.textContent='Visível até '+prepBR(prepDataRespostaAte(dias));}
async function salvarRespostaPreparacaoFisica(){
 const r=prepSelecionada();if(!r)return alert('Selecione uma queixa.');
 const resposta=String(document.getElementById('prep-resposta-textarea')?.value||'').trim();
 if(!resposta)return alert('Digite uma resposta ou use uma resposta rápida.');
 const dias=Math.max(1,parseInt(document.getElementById('prep-resposta-dias')?.value,10)||1);
 const payload={resposta,resposta_dias:dias,resposta_ate:prepDataRespostaAte(dias),respondido_por:'Preparação Física',status:'respondido',visto_atleta:false,atualizado_em:new Date().toISOString()};
 const btn=document.querySelector('#preparacao-fisica-modal .prep-actions .salvar');if(btn){btn.disabled=true;btn.textContent='Salvando...';}
 try{
  const {error}=await _supabase.from(PREPARACAO_FISICA_TABELA).update(payload).eq('id',r.id);
  if(error)throw error;
  alert('Resposta salva com sucesso.');
  await carregarPreparacaoFisicaQueixas();
  await atualizarIndicadorPreparacaoFisica();
 }catch(e){console.error(e);alert('Erro ao salvar resposta.');}
 finally{if(btn){btn.disabled=false;btn.textContent='Salvar resposta';}}
}
async function limparRespostaPreparacaoFisica(){
 const r=prepSelecionada();if(!r)return alert('Selecione uma queixa.');
 if(!confirm('Limpar a resposta desta queixa e voltar para pendente?'))return;
 const payload={resposta:null,resposta_dias:null,resposta_ate:null,respondido_por:null,status:'pendente',visto_atleta:false,atualizado_em:new Date().toISOString()};
 try{
  const {error}=await _supabase.from(PREPARACAO_FISICA_TABELA).update(payload).eq('id',r.id);
  if(error)throw error;
  await carregarPreparacaoFisicaQueixas();
  await atualizarIndicadorPreparacaoFisica();
 }catch(e){console.error(e);alert('Erro ao limpar resposta.');}
}


/* === MONITORAMENTO DE CARGA - PSR/PSE === */

/* === CALENDÁRIO DE TREINOS + CONFIGURAÇÃO DE JOGO POR DATA/CATEGORIA === */
const CAL_TREINO_CATS=[{id:'sub11',label:'Sub 11'},{id:'sub12',label:'Sub 12'},{id:'sub13',label:'Sub 13'},{id:'sub16',label:'Sub 16'}];
const CAL_JOGO_TABELA='portal_jogos_calendario';
let calTreinoState={ano:0,mes:0,sel:'',lista:[],jogos:[],carregando:false,ready:false,gameReady:false,error:'',jogoError:'',salvando:false,request:0};
let calJogoEditorState=null;

function calTreinoISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function calTreinoParse(iso){const m=String(iso||'').match(/^(\d{4})-(\d{2})-(\d{2})/);return m?new Date(+m[1],+m[2]-1,+m[3]):new Date();}
function calTreinoPadrao(cat,d){const dia=d.getDay();if(!CAL_TREINO_CATS.some(c=>c.id===cat))return false;return cat==='sub11'?[1,3,5].includes(dia):[1,2,3,4,5].includes(dia);}
function calTreinoExcecao(iso,cat){return (calTreinoState.lista||[]).find(r=>String(r.data).slice(0,10)===iso&&r.categoria===cat);}
function calTreinoJogo(iso,cat){return (calTreinoState.jogos||[]).find(r=>String(r.data).slice(0,10)===iso&&r.categoria===cat)||null;}
function calTreinoJogoAtivo(iso,cat){return calTreinoJogo(iso,cat)?.jogo_liberado===true;}
function calTreinoTem(iso,cat,tipo){const ex=calTreinoExcecao(iso,cat),pad=calTreinoPadrao(cat,calTreinoParse(iso));if(tipo==='psr'||tipo==='pse')return ex?ex[tipo+'_liberado']===true:pad;return calTreinoTem(iso,cat,'psr')||calTreinoTem(iso,cat,'pse');}
function calJogoEsc(v){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));}
function calJogoHHMM(v){return String(v||'').slice(0,5);}
function calJogoHorariosPadrao(cat){return cat==='sub11'||cat==='sub12'?{pre_jogo_abre:'06:00',pre_jogo_fecha:'16:30',pos_jogo_abre:'16:30',pos_jogo_fecha:'23:00'}:{pre_jogo_abre:'06:00',pre_jogo_fecha:'15:00',pos_jogo_abre:'15:01',pos_jogo_fecha:'23:00'};}
function calJogoMinutos(v){const m=String(v||'').match(/^(\d{2}):(\d{2})/);if(!m)return null;const h=Number(m[1]),n=Number(m[2]);return h<=23&&n<=59?h*60+n:null;}
function calJogoHorariosValidos(v){const pa=calJogoMinutos(v.pre_jogo_abre),pf=calJogoMinutos(v.pre_jogo_fecha),oa=calJogoMinutos(v.pos_jogo_abre),of=calJogoMinutos(v.pos_jogo_fecha);return pa!==null&&pf!==null&&oa!==null&&of!==null&&pa<pf&&oa<of&&pf<=oa;}
function calJogoIdentidadeKey(id){const nome=id?.nomeCompleto||id?.nome_completo||id?.nome||'',nasc=id?.nascimento||id?.data_nascimento||'';return AE.key({nomeCompleto:nome,nascimento:nasc})||'';}
function calJogoListaTodosCT(){
 const saida=[],seen=new Set();
 for(const atleta of trabalhoTodosAtletas()){
  const id=atleta.id||{},key=calJogoIdentidadeKey(id);if(!key)continue;
  const vinculo=AE.vinculo(id),aparicoes=[{ano:String(id.ano||''),tipo:'Ano de origem'}];
  if(vinculo?.calendario===true&&String(vinculo.ano_destino||'')&&String(vinculo.ano_destino)!==String(id.ano||''))aparicoes.push({ano:String(vinculo.ano_destino),tipo:'Representando'});
  for(const ap of aparicoes){
   const categoria=AE.categoriaAno(ap.ano),k=key+'||'+ap.ano+'||'+ap.tipo;if(seen.has(k))continue;seen.add(k);
   saida.push({identityKey:key,anoExibicao:ap.ano,tipoAparicao:ap.tipo,categoria,apelido:id.apelido||id.nomeCompleto,nomeCompleto:id.nomeCompleto,nascimento:id.nascimento});
  }
 }
 return saida.sort((a,b)=>Number(a.anoExibicao)-Number(b.anoExibicao)||String(a.apelido).localeCompare(String(b.apelido),'pt-BR')||String(a.nomeCompleto).localeCompare(String(b.nomeCompleto),'pt-BR'));
}
function calJogoListaElegiveis(cat){return calJogoListaTodosCT().filter(x=>x.categoria===cat);}
function calJogoIdentidadesUnicas(aparicoes){const mapa=new Map();(aparicoes||[]).forEach(a=>{if(a?.identityKey&&!mapa.has(a.identityKey))mapa.set(a.identityKey,{nomeCompleto:a.nomeCompleto,nascimento:a.nascimento});});return mapa;}
function calJogoAtualizarCache(cfg){
 if(!cfg)return;const iso=String(cfg.data||'').slice(0,10),cat=cfg.categoria;if(!iso||!cat)return;
 const arr=(calTreinoState.jogos||[]).filter(r=>!(String(r.data).slice(0,10)===iso&&r.categoria===cat));
 arr.push({...cfg,data:iso});calTreinoState.jogos=arr;
}
function openCalendarioTreino(){
 const hoje=new Date();calTreinoState.ano=hoje.getFullYear();calTreinoState.mes=hoje.getMonth();calTreinoState.sel=calTreinoISO(hoje);
 let m=document.getElementById('calendario-treino-modal');
 if(!m){m=document.createElement('div');m.id='calendario-treino-modal';m.className='cal-treino-overlay';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m)closeCalendarioTreino();});}
 m.style.display='flex';carregarCalendarioTreino();
}
function closeCalendarioTreino(){const m=document.getElementById('calendario-treino-modal');if(m)m.style.display='none';calJogoCloseEditor();}
function calTreinoMes(delta){const d=new Date(calTreinoState.ano,calTreinoState.mes+delta,1);calTreinoState.ano=d.getFullYear();calTreinoState.mes=d.getMonth();calTreinoState.sel=calTreinoISO(d);return carregarCalendarioTreino();}
function calTreinoSel(iso){calTreinoState.sel=iso;renderCalendarioTreino();}
async function carregarCalendarioTreino(){
 const request=(calTreinoState.request||0)+1;calTreinoState.request=request;
 const ano=calTreinoState.ano,mes=calTreinoState.mes;
 calTreinoState.carregando=true;calTreinoState.ready=false;calTreinoState.gameReady=false;calTreinoState.jogos=[];calTreinoState.jogoError='';calTreinoState.error='';renderCalendarioTreino();
 try{
  const inicio=calTreinoISO(new Date(ano,mes,1)),fim=calTreinoISO(new Date(ano,mes+1,0));
  const [excecoes,jogos]=await Promise.all([
   _supabase.from('dias_treino_excecao').select('data,categoria,psr_liberado,pse_liberado').gte('data',inicio).lte('data',fim).order('data'),
   _supabase.from(CAL_JOGO_TABELA).select('data,categoria,jogo_liberado,pre_jogo_abre,pre_jogo_fecha,pos_jogo_abre,pos_jogo_fecha,convocacao_importada,treino_nao_convocados,atualizado_em').gte('data',inicio).lte('data',fim).order('data')
  ]);
  if(excecoes.error)throw excecoes.error;
  if((excecoes.data||[]).some(r=>typeof r.psr_liberado!=='boolean'||typeof r.pse_liberado!=='boolean'))throw new Error('SQL do calendário separado ainda não instalado.');
  if(calTreinoState.request!==request)return;
  calTreinoState.lista=excecoes.data||[];calTreinoState.ready=true;
  if(jogos.error){calTreinoState.jogos=[];calTreinoState.gameReady=false;calTreinoState.jogoError='Configuração Jogo indisponível. Execute o SQL de Jogo antes de usar este recurso.';}
  else if((jogos.data||[]).some(r=>typeof r.jogo_liberado!=='boolean')){calTreinoState.jogos=[];calTreinoState.gameReady=false;calTreinoState.jogoError='A tabela de configuração Jogo está incompleta. Confira a migração do Supabase.';}
  else{calTreinoState.jogos=jogos.data||[];calTreinoState.gameReady=true;calTreinoState.jogoError='';}
 }catch(e){if(calTreinoState.request!==request)return;console.warn(e);calTreinoState.lista=[];calTreinoState.jogos=[];calTreinoState.ready=false;calTreinoState.gameReady=false;calTreinoState.error='Não foi possível carregar PSR/PSE. Confira a conexão e o SQL do calendário.';}
 finally{if(calTreinoState.request===request){calTreinoState.carregando=false;renderCalendarioTreino();}}
}
async function calTreinoToggle(cat,tipo,on){
 if(!calTreinoState.ready||calTreinoState.carregando||calTreinoState.salvando)return;
 if(!CAL_TREINO_CATS.some(c=>c.id===cat)||!['psr','pse'].includes(tipo))return;
 const iso=calTreinoState.sel,ano=calTreinoState.ano,mes=calTreinoState.mes;calTreinoState.salvando=true;calTreinoState.error='';renderCalendarioTreino();
 try{
  const {data,error}=await _supabase.rpc('cal_questionario_definir',{p_data:iso,p_categoria:cat,p_tipo:tipo,p_liberado:!!on});
  if(error)throw error;if(!data||typeof data.psr_liberado!=='boolean'||typeof data.pse_liberado!=='boolean')throw new Error('Resposta inválida ao salvar calendário.');
  if(calTreinoState.ano===ano&&calTreinoState.mes===mes){const rest=calTreinoState.lista.filter(r=>!(String(r.data).slice(0,10)===iso&&r.categoria===cat));if(data.excecao)rest.push({data:iso,categoria:cat,psr_liberado:data.psr_liberado,pse_liberado:data.pse_liberado});calTreinoState.lista=rest;}
 }catch(e){console.warn(e);calTreinoState.error='Não foi possível salvar a alteração. Atualize o calendário e tente novamente.';}
 finally{calTreinoState.salvando=false;renderCalendarioTreino();}
}
function calTreinoCapturarScroll(){const card=document.querySelector('#calendario-treino-modal .cal-treino-card');return card?{top:card.scrollTop,left:card.scrollLeft}:null;}
function calTreinoRestaurarScroll(pos){if(!pos)return;const card=document.querySelector('#calendario-treino-modal .cal-treino-card');if(card){card.scrollTop=pos.top;card.scrollLeft=pos.left;}}
async function calTreinoToggleJogo(cat,on){
 if(!calTreinoState.gameReady||calTreinoState.carregando||calTreinoState.salvando)return;
 if(!CAL_TREINO_CATS.some(c=>c.id===cat))return;
 const iso=calTreinoState.sel,ano=calTreinoState.ano,mes=calTreinoState.mes,existente=calTreinoJogo(iso,cat),padrao=calJogoHorariosPadrao(cat),scroll=calTreinoCapturarScroll();
 calTreinoState.salvando=true;calTreinoState.jogoError='';renderCalendarioTreino();calTreinoRestaurarScroll(scroll);
 try{
  let query;
  if(on){
   const times={pre_jogo_abre:calJogoHHMM(existente?.pre_jogo_abre)||padrao.pre_jogo_abre,pre_jogo_fecha:calJogoHHMM(existente?.pre_jogo_fecha)||padrao.pre_jogo_fecha,pos_jogo_abre:calJogoHHMM(existente?.pos_jogo_abre)||padrao.pos_jogo_abre,pos_jogo_fecha:calJogoHHMM(existente?.pos_jogo_fecha)||padrao.pos_jogo_fecha};
   if(!calJogoHorariosValidos(times)){Object.assign(times,padrao);}
   const payload={data:iso,categoria:cat,jogo_liberado:true,...times,convocacao_importada:existente?.convocacao_importada===true,treino_nao_convocados:existente?.treino_nao_convocados===true,atualizado_em:new Date().toISOString()};
   query=existente?_supabase.from(CAL_JOGO_TABELA).update({...payload}).eq('data',iso).eq('categoria',cat).select('*').single():_supabase.from(CAL_JOGO_TABELA).insert(payload).select('*').single();
  }else{
   if(!existente)return;
   query=_supabase.from(CAL_JOGO_TABELA).update({jogo_liberado:false,atualizado_em:new Date().toISOString()}).eq('data',iso).eq('categoria',cat).select('*').single();
  }
  const {data,error}=await query;if(error)throw error;if(!data)throw new Error('Não houve confirmação do Supabase.');
  if(calTreinoState.ano===ano&&calTreinoState.mes===mes)calJogoAtualizarCache(data);
 }catch(e){console.warn(e);calTreinoState.jogoError='Não foi possível salvar Jogo. Confira a migração e tente novamente.';}
 finally{const scrollFinal=calTreinoCapturarScroll()||scroll;calTreinoState.salvando=false;renderCalendarioTreino();calTreinoRestaurarScroll(scrollFinal);}
}
function calJogoEnsureOverlay(id,className,closeFn){let m=document.getElementById(id);if(!m){m=document.createElement('div');m.id=id;m.className=className;document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m)closeFn();});}return m;}
function calJogoCloseModal(id){const m=document.getElementById(id);if(m)m.style.display='none';}
function calJogoCloseEditor(){calJogoCloseModal('cal-jogo-ct-atletas-modal');calJogoCloseModal('cal-jogo-lista-salva-modal');calJogoCloseModal('cal-jogo-manual-modal');calJogoCloseModal('cal-jogo-editor-modal');calJogoEditorState=null;}
function calJogoTimesEditor(cfg,cat){const p=calJogoHorariosPadrao(cat);return {pre_jogo_abre:calJogoHHMM(cfg?.pre_jogo_abre)||p.pre_jogo_abre,pre_jogo_fecha:calJogoHHMM(cfg?.pre_jogo_fecha)||p.pre_jogo_fecha,pos_jogo_abre:calJogoHHMM(cfg?.pos_jogo_abre)||p.pos_jogo_abre,pos_jogo_fecha:calJogoHHMM(cfg?.pos_jogo_fecha)||p.pos_jogo_fecha};}
async function calTreinoEditarJogo(cat){
 if(!calTreinoState.gameReady||!CAL_TREINO_CATS.some(c=>c.id===cat))return;
 const iso=calTreinoState.sel,cfg=calTreinoJogo(iso,cat);if(!cfg?.jogo_liberado)return;
 calJogoEditorState={data:iso,categoria:cat,config:{...cfg,...calJogoTimesEditor(cfg,cat)},convocados:[],rosterLoaded:cfg.convocacao_importada!==true,rosterLoading:false,rosterError:'',busy:false,error:'',notice:'',salvas:[],manualEntries:[],manualTodosEntries:[],manualAnoFiltro:'todos',manualBuscaTodos:'',manualSelected:new Set(),manualMap:new Map()};
 const m=calJogoEnsureOverlay('cal-jogo-editor-modal','cal-jogo-overlay',calJogoCloseEditor);m.style.display='flex';calJogoRenderEditor();
 if(cfg.convocacao_importada===true)await calJogoCarregarConvocados();
}
function calJogoRenderEditor(){
 const s=calJogoEditorState,m=document.getElementById('cal-jogo-editor-modal');if(!s||!m)return;
 const c=CAL_TREINO_CATS.find(x=>x.id===s.categoria),t=s.config;
 m.innerHTML=`<div class="cal-jogo-card"><button class="cal-jogo-close" aria-label="Fechar" onclick="calJogoCloseEditor()">×</button><h2>Editar Jogo — ${calJogoEsc(c?.label||s.categoria)}</h2><p class="cal-jogo-date">${calTreinoParse(s.data).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}</p><section class="cal-jogo-times"><h3>Horários dos questionários</h3><p>Para convocados, a janela Pré controla PSR/Pré e a janela Pós controla PSE/Pós. Não convocados seguem os horários normais de PSR/PSE; os valores iniciais das janelas usam os horários habituais da categoria e podem ser ajustados para este jogo.</p><div class="cal-jogo-time-grid"><label>Pré-Jogo — abre<input id="cal-jogo-pre-abre" type="time" value="${calJogoHHMM(t.pre_jogo_abre)}"></label><label>Pré-Jogo — fecha<input id="cal-jogo-pre-fecha" type="time" value="${calJogoHHMM(t.pre_jogo_fecha)}"></label><label>Pós-Jogo — abre<input id="cal-jogo-pos-abre" type="time" value="${calJogoHHMM(t.pos_jogo_abre)}"></label><label>Pós-Jogo — fecha<input id="cal-jogo-pos-fecha" type="time" value="${calJogoHHMM(t.pos_jogo_fecha)}"></label></div><small class="cal-jogo-hint">A hora de fechamento é exclusiva; Pré-Jogo precisa terminar antes ou no início de Pós-Jogo.</small></section><label class="cal-jogo-treino"><input id="cal-jogo-treino-nao-convocados" type="checkbox" ${t.treino_nao_convocados===true?'checked':''}> Não convocados terão treino (libera PSE; PSR segue liberado)</label><small class="cal-jogo-hint">Convocados: PSR/Pré na janela Pré e PSE/Pós na janela Pós. Não convocados: PSR e, se o treino estiver marcado, PSE nos horários normais; não recebem Pré/Pós.</small><div class="cal-jogo-convocacao"><h3>Convocação</h3><p id="cal-jogo-roster-status" class="cal-jogo-roster-status"></p><div class="cal-jogo-actions"><button type="button" onclick="calJogoAbrirImportacaoSalva()">Importar convocação salva</button><button type="button" onclick="calJogoAbrirSelecaoManual()" ${s.busy||s.rosterLoading||(s.config.convocacao_importada===true&&!s.rosterLoaded)?'disabled':''}>Selecionar manualmente</button></div><div id="cal-jogo-roster-view" class="cal-jogo-roster-view" role="region" aria-label="Convocados para conferência" aria-live="polite"></div></div><div id="cal-jogo-editor-msg" class="cal-jogo-msg" role="status"></div><div class="cal-jogo-footer"><button type="button" class="cal-jogo-save" onclick="calJogoSalvarConfiguracao()" ${s.busy?'disabled':''}>Salvar horários e treinos</button><button type="button" class="cal-jogo-cancel" onclick="calJogoCloseEditor()">Fechar</button></div></div>`;
 calJogoAtualizarStatusEditor();calJogoRenderListaConvocados();if(s.error)calJogoMensagemEditor(s.error,'error');else if(s.notice)calJogoMensagemEditor(s.notice,'ok');
}
function calJogoMensagemEditor(texto,tipo=''){const el=document.getElementById('cal-jogo-editor-msg');if(el){el.textContent=texto||'';el.className='cal-jogo-msg'+(tipo?' '+tipo:'');}}
function calJogoAtualizarStatusEditor(){
 const s=calJogoEditorState,el=document.getElementById('cal-jogo-roster-status');if(!s||!el)return;
 if(s.rosterLoading){el.textContent='Carregando convocados importados…';el.className='cal-jogo-roster-status loading';}
 else if(s.rosterError){el.textContent=s.rosterError;el.className='cal-jogo-roster-status error';}
 else if(s.config.convocacao_importada===true){el.textContent=`Convocação importada: ${s.convocados.length} atleta(s). PSR é liberado para todos; PSE depende da convocação/treino.`;el.className='cal-jogo-roster-status imported';}
 else{el.textContent='Convocação ainda não importada. PSR é liberado para todos; PSE e Pré/Pós aguardam a importação da lista.';el.className='cal-jogo-roster-status pending';}
}
function calJogoDataNascimentoBR(v){const s=String(v||'').trim(),m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}/${m[2]}/${m[1]}`:s;}
function calJogoRenderListaConvocados(){
 const s=calJogoEditorState,el=document.getElementById('cal-jogo-roster-view');if(!s||!el)return;
 if(s.rosterError){el.innerHTML='<p class="cal-jogo-roster-empty error">Lista indisponível para conferência.</p>';return;}
 if(s.config.convocacao_importada!==true){el.innerHTML='<p class="cal-jogo-roster-empty">Convocação ainda não importada.</p>';return;}
 if(s.rosterLoading||!s.rosterLoaded){el.innerHTML='<p class="cal-jogo-roster-empty">Carregando convocados…</p>';return;}
 const lista=[...(s.convocados||[])].sort((a,b)=>String(a.nomeCompleto||'').localeCompare(String(b.nomeCompleto||''),'pt-BR'));
 if(!lista.length){el.innerHTML='<p class="cal-jogo-roster-empty">Convocação importada sem atletas.</p>';return;}
 el.innerHTML=`<ul class="cal-jogo-roster-list">${lista.map(a=>`<li><span>${calJogoEsc(a.nomeCompleto||'')}</span><small>Nascimento: ${calJogoEsc(calJogoDataNascimentoBR(a.nascimento))}</small></li>`).join('')}</ul>`;
}
async function calJogoCarregarConvocados(){
 const s=calJogoEditorState;if(!s||s.rosterLoading)return;
 s.rosterLoading=true;s.rosterError='';calJogoAtualizarStatusEditor();calJogoRenderListaConvocados();
 try{
  const {data,error}=await _supabase.rpc('portal_jogo_convocacao_listar',{p_data:s.data,p_categoria:s.categoria});if(error)throw error;
  let r=data;if(typeof r==='string')r=JSON.parse(r);if(!r||r.convocacao_importada!==true||!Array.isArray(r.convocados))throw new Error('Resposta inválida do Supabase.');
  s.convocados=r.convocados.map(v=>({nomeCompleto:v.nome_completo||v.nomeCompleto||'',nascimento:v.nascimento||''})).filter(v=>v.nomeCompleto&&v.nascimento);
  s.rosterLoaded=true;
 }catch(e){console.warn('Lista de convocados do jogo:',e);s.rosterError='Não foi possível carregar a lista salva para conferência. Verifique a conexão e a RPC de consulta da convocação.';s.rosterLoaded=false;}
 finally{s.rosterLoading=false;calJogoAtualizarStatusEditor();calJogoRenderListaConvocados();const b=document.querySelector('#cal-jogo-editor-modal .cal-jogo-actions button:nth-child(2)');if(b)b.disabled=s.busy||(s.config.convocacao_importada===true&&!s.rosterLoaded);}
}
async function calJogoSalvarConfiguracao(){
 const s=calJogoEditorState;if(!s||s.busy)return;
 const valores={pre_jogo_abre:document.getElementById('cal-jogo-pre-abre')?.value||'',pre_jogo_fecha:document.getElementById('cal-jogo-pre-fecha')?.value||'',pos_jogo_abre:document.getElementById('cal-jogo-pos-abre')?.value||'',pos_jogo_fecha:document.getElementById('cal-jogo-pos-fecha')?.value||'',treino_nao_convocados:!!document.getElementById('cal-jogo-treino-nao-convocados')?.checked};
 if(!calJogoHorariosValidos(valores)){calJogoMensagemEditor('Confira os horários: cada abertura deve ser anterior ao fechamento e Pré-Jogo deve terminar até o início de Pós-Jogo.','error');return;}
 s.busy=true;s.error='';s.notice='';const btn=document.querySelector('#cal-jogo-editor-modal .cal-jogo-save');if(btn){btn.disabled=true;btn.textContent='Salvando…';}
 try{
  const {data,error}=await _supabase.from(CAL_JOGO_TABELA).update({...valores,atualizado_em:new Date().toISOString()}).eq('data',s.data).eq('categoria',s.categoria).select('*').single();if(error)throw error;if(!data)throw new Error('Jogo não encontrado no calendário.');
  s.config={...s.config,...data,...valores};calJogoAtualizarCache(s.config);renderCalendarioTreino();calJogoCloseEditor();
 }catch(e){console.warn(e);s.error='Não foi possível salvar os horários ou a opção de treino. Confira a conexão e tente novamente.';calJogoMensagemEditor(s.error,'error');if(btn){btn.disabled=false;btn.textContent='Salvar horários e treinos';}}
 finally{s.busy=false;if(calJogoEditorState===s){const b=document.querySelector('#cal-jogo-editor-modal .cal-jogo-save');if(b){b.disabled=false;b.textContent='Salvar horários e treinos';}const man=document.querySelector('#cal-jogo-editor-modal .cal-jogo-actions button:nth-child(2)');if(man)man.disabled=s.config.convocacao_importada===true&&!s.rosterLoaded;}}
}
async function calJogoAbrirImportacaoSalva(){
 const s=calJogoEditorState;if(!s||s.busy)return;calJogoMensagemEditor('Buscando convocações salvas…');
 try{
  const {data,error}=await _supabase.from('convocacoes').select('nome,dados,atualizado_em').order('nome');if(error)throw error;
  if(!data?.length){calJogoMensagemEditor('Nenhuma convocação salva foi encontrada.','error');return;}
  s.salvas=data;const m=calJogoEnsureOverlay('cal-jogo-lista-salva-modal','cal-jogo-suboverlay',()=>calJogoCloseModal('cal-jogo-lista-salva-modal'));
  m.innerHTML=`<div class="cal-jogo-subcard"><h3>Importar convocação salva</h3><p>Serão importados todos os atletas identificáveis da convocação salva, inclusive os de outras categorias. Se convocados, seguirão os horários deste Jogo.</p><select id="cal-jogo-convocacao-salva" size="8">${data.map((x,i)=>`<option value="${i}">${calJogoEsc(x.nome)}${x.atualizado_em?' — '+calJogoEsc(new Date(x.atualizado_em).toLocaleDateString('pt-BR')):''}</option>`).join('')}</select><div class="cal-jogo-sub-actions"><button type="button" class="primary" onclick="calJogoAplicarConvocacaoSalva()">Importar selecionada</button><button type="button" onclick="calJogoCloseModal('cal-jogo-lista-salva-modal')">Cancelar</button></div></div>`;m.style.display='flex';
  calJogoMensagemEditor('');
 }catch(e){console.warn(e);calJogoMensagemEditor('Não foi possível carregar as convocações salvas.','error');}
}
async function calJogoAplicarConvocacaoSalva(){
 const s=calJogoEditorState;if(!s||s.busy)return;const i=Number(document.getElementById('cal-jogo-convocacao-salva')?.value),registro=s.salvas[i];if(!registro)return alert('Selecione uma convocação salva.');
 let dados=registro.dados||{};if(typeof dados==='string'){try{dados=JSON.parse(dados);}catch(e){dados={};}}
 const detalhes=Array.isArray(dados.selecionadosDetalhes)?dados.selecionadosDetalhes:[];if(!detalhes.length)return alert('A convocação salva não contém atletas identificáveis.');
 try{await AE.load(true);}catch(e){return alert(AE.estado.error||'Não foi possível sincronizar Atletas Extras.');}
 const incluidosPorIdentidade=new Map();
 detalhes.forEach(x=>{const key=calJogoIdentidadeKey(x),nomeCompleto=x.nomeCompleto||x.nome_completo||x.nome||'',nascimento=x.nascimento||x.data_nascimento||'';if(key&&nomeCompleto&&nascimento&&!incluidosPorIdentidade.has(key))incluidosPorIdentidade.set(key,{nomeCompleto,nascimento});});
 const incluidos=[...incluidosPorIdentidade.values()];
 if(!incluidos.length)return alert('A convocação salva não contém atletas com nome e nascimento identificáveis.');
 if(await calJogoImportarConvocados(incluidos))calJogoCloseModal('cal-jogo-lista-salva-modal');
}
async function calJogoAbrirSelecaoManual(){
 const s=calJogoEditorState;if(!s||s.busy||s.rosterLoading||(s.config.convocacao_importada===true&&!s.rosterLoaded))return;
 try{await AE.load(true);}catch(e){alert(AE.estado.error||'Não foi possível sincronizar Atletas Extras.');return;}
 const entradas=calJogoListaElegiveis(s.categoria),todas=calJogoListaTodosCT();if(!todas.length)return alert('Não há atletas cadastrados no CT para selecionar.');
 const mapa=calJogoIdentidadesUnicas(todas);s.manualEntries=entradas;s.manualTodosEntries=todas;s.manualAnoFiltro='todos';s.manualBuscaTodos='';s.manualMap=mapa;s.manualSelected=new Set((s.convocados||[]).map(calJogoIdentidadeKey).filter(k=>mapa.has(k)));
 const m=calJogoEnsureOverlay('cal-jogo-manual-modal','cal-jogo-suboverlay',()=>calJogoCloseModal('cal-jogo-manual-modal'));calJogoRenderSelecaoManual();m.style.display='flex';
}
function calJogoRenderSelecaoManual(){
 const s=calJogoEditorState,m=document.getElementById('cal-jogo-manual-modal');if(!s||!m)return;
 const grupos=[...new Set(s.manualEntries.map(x=>x.anoExibicao))].sort((a,b)=>Number(a)-Number(b));
 const conteudo=grupos.map(ano=>{const itens=s.manualEntries.map((x,i)=>({x,i})).filter(y=>y.x.anoExibicao===ano);return `<section class="cal-jogo-year-group" data-year-group="${ano}"><h4>Ano ${calJogoEsc(ano)}</h4>${itens.map(({x,i})=>`<label class="cal-jogo-manual-row" data-search="${calJogoEsc([x.apelido,x.nomeCompleto,x.anoExibicao,x.tipoAparicao].join(' ').toLocaleLowerCase('pt-BR'))}"><input type="checkbox" data-entry-index="${i}" data-identity-key="${encodeURIComponent(x.identityKey)}" ${s.manualSelected.has(x.identityKey)?'checked':''} onchange="calJogoManualToggle(${i},this.checked)"><span><strong>${calJogoEsc(x.apelido||x.nomeCompleto)}</strong><small>${calJogoEsc(x.tipoAparicao)} ${calJogoEsc(x.anoExibicao)}${x.apelido&&x.nomeCompleto&&x.apelido!==x.nomeCompleto?' · '+calJogoEsc(x.nomeCompleto):''}</small></span></label>`).join('')}</section>`;}).join('');
 m.innerHTML=`<div class="cal-jogo-subcard cal-jogo-manual-card"><button class="cal-jogo-sub-close" aria-label="Fechar" onclick="calJogoCloseModal('cal-jogo-manual-modal')">×</button><h3>Selecionar convocados manualmente</h3><p>A lista mostra atletas desta categoria, incluindo extras no ano de origem/representação. Use + Atletas para convocar alguém de outra categoria; a mesma identidade é gravada uma única vez.</p><input id="cal-jogo-busca-manual" class="cal-jogo-search" placeholder="Buscar atleta..." oninput="calJogoFiltrarManual()"><div class="cal-jogo-manual-tools"><button type="button" onclick="calJogoManualMarcarVisiveis(true)">Selecionar visíveis</button><button type="button" onclick="calJogoManualMarcarVisiveis(false)">Limpar visíveis</button><button type="button" onclick="calJogoAbrirAtletasTodosCT()">+ Atletas</button><strong id="cal-jogo-manual-count"></strong></div><div class="cal-jogo-manual-list">${conteudo||'<p>Nenhum atleta desta categoria. Use “+ Atletas” para convocar alguém de outra categoria.</p>'}</div><div id="cal-jogo-manual-warning" class="cal-jogo-warning"></div><div class="cal-jogo-sub-actions"><button type="button" class="primary" onclick="calJogoSalvarSelecaoManual()">Salvar convocados</button><button type="button" onclick="calJogoCloseModal('cal-jogo-manual-modal')">Cancelar</button></div></div>`;
 calJogoManualSync();
}
function calJogoFiltrarManual(){
 const q=String(document.getElementById('cal-jogo-busca-manual')?.value||'').trim().toLocaleLowerCase('pt-BR');
 document.querySelectorAll('#cal-jogo-manual-modal .cal-jogo-manual-row').forEach(row=>{row.hidden=!!q&&!row.dataset.search.includes(q);});
 document.querySelectorAll('#cal-jogo-manual-modal .cal-jogo-year-group').forEach(g=>{g.hidden=!g.querySelector('.cal-jogo-manual-row:not([hidden])');});
}
function calJogoManualToggle(i,checked){const s=calJogoEditorState,x=s?.manualEntries?.[i];if(!s||!x)return;if(checked)s.manualSelected.add(x.identityKey);else s.manualSelected.delete(x.identityKey);calJogoManualSync();}
function calJogoManualSync(){
 const s=calJogoEditorState;if(!s)return;
 document.querySelectorAll('#cal-jogo-manual-modal input[data-entry-index]').forEach(el=>{const a=s.manualEntries[Number(el.dataset.entryIndex)];if(a)el.checked=s.manualSelected.has(a.identityKey);});
 const visiveis=new Set((s.manualEntries||[]).map(x=>x.identityKey)),outras=[...s.manualSelected].filter(k=>!visiveis.has(k)).length;
 const count=document.getElementById('cal-jogo-manual-count');if(count)count.textContent=`Selecionados: ${s.manualSelected.size}${outras?` (${outras} de outras categorias; veja + Atletas)`:''}`;
 const fora=(s.convocados||[]).filter(a=>!s.manualMap.has(calJogoIdentidadeKey(a))).length;const aviso=document.getElementById('cal-jogo-manual-warning');if(aviso)aviso.textContent=fora?`${fora} convocado(s) salvo(s) não estão no cadastro atual e serão removidos ao salvar manualmente.`:'';
 calJogoTodosCTSync();
}
async function calJogoAbrirAtletasTodosCT(){
 const s=calJogoEditorState;if(!s||s.busy)return;
 try{if(!AE.estado.ready)await AE.load(true);}catch(e){alert(AE.estado.error||'Não foi possível sincronizar Atletas Extras.');return;}
 s.manualTodosEntries=calJogoListaTodosCT();if(!s.manualTodosEntries.length)return alert('Não há atletas cadastrados no CT para selecionar.');
 for(const [key,atleta] of calJogoIdentidadesUnicas(s.manualTodosEntries))if(!s.manualMap.has(key))s.manualMap.set(key,atleta);
 s.manualAnoFiltro='todos';s.manualBuscaTodos='';
 const m=calJogoEnsureOverlay('cal-jogo-ct-atletas-modal','cal-jogo-suboverlay cal-jogo-ct-overlay',()=>calJogoCloseModal('cal-jogo-ct-atletas-modal'));
 calJogoRenderTodosCT();m.style.display='flex';calJogoManualSync();
}
function calJogoRenderTodosCT(){
 const s=calJogoEditorState,m=document.getElementById('cal-jogo-ct-atletas-modal');if(!s||!m)return;
 const entries=s.manualTodosEntries||[],anos=[...new Set(entries.map(x=>String(x.anoExibicao||'')))].sort((a,b)=>Number(a)-Number(b));
 const opcoes=anos.map(a=>{const valor=a||'__sem_ano__';return `<option value="${calJogoEsc(valor)}" ${s.manualAnoFiltro===valor?'selected':''}>${a?calJogoEsc(a):'Ano não informado'}</option>`;}).join('');
 const grupos=[...new Set(entries.map(x=>String(x.anoExibicao||'')))].sort((a,b)=>Number(a)-Number(b));
 const conteudo=grupos.map(ano=>{const itens=entries.map((x,i)=>({x,i})).filter(y=>String(y.x.anoExibicao||'')===ano);return `<section class="cal-jogo-year-group" data-year-group="${calJogoEsc(ano)}"><h4>${ano?'Ano '+calJogoEsc(ano):'Ano não informado'}</h4>${itens.map(({x,i})=>{const cat=CAL_TREINO_CATS.find(c=>c.id===x.categoria)?.label||'Categoria não mapeada';return `<label class="cal-jogo-manual-row" data-year="${calJogoEsc(ano)}" data-search="${calJogoEsc([x.apelido,x.nomeCompleto,x.anoExibicao,x.tipoAparicao,cat].join(' ').toLocaleLowerCase('pt-BR'))}"><input type="checkbox" data-todos-ct-index="${i}" ${s.manualSelected.has(x.identityKey)?'checked':''} onchange="calJogoTodosCTToggle(${i},this.checked)"><span><strong>${calJogoEsc(x.apelido||x.nomeCompleto)}</strong><small>${calJogoEsc(x.tipoAparicao)} ${ano?calJogoEsc(ano):'sem ano'} · ${calJogoEsc(cat)}${x.apelido&&x.nomeCompleto&&x.apelido!==x.nomeCompleto?' · '+calJogoEsc(x.nomeCompleto):''}</small></span></label>`;}).join('')}</section>`;}).join('');
 m.innerHTML=`<div class="cal-jogo-subcard cal-jogo-manual-card cal-jogo-ct-card"><button class="cal-jogo-sub-close" aria-label="Fechar" onclick="calJogoCloseModal('cal-jogo-ct-atletas-modal')">×</button><h3>+ Atletas — todo o CT</h3><p>Marque atletas de qualquer ano/categoria para incluí-los na convocação deste Jogo. As aparições do mesmo Atleta Extra ficam sincronizadas e cada identidade é gravada uma única vez.</p><div class="cal-jogo-ct-filters"><label>Filtrar por ano<select id="cal-jogo-ct-ano" onchange="calJogoFiltrarTodosCT()"><option value="todos" ${s.manualAnoFiltro==='todos'?'selected':''}>Todos os anos</option>${opcoes}</select></label><input id="cal-jogo-busca-todos-ct" class="cal-jogo-search" aria-label="Buscar atleta em todo o CT" placeholder="Buscar atleta..." value="${calJogoEsc(s.manualBuscaTodos||'')}" oninput="calJogoFiltrarTodosCT()"></div><div class="cal-jogo-manual-tools"><button type="button" onclick="calJogoTodosCTMarcarVisiveis(true)">Selecionar visíveis</button><button type="button" onclick="calJogoTodosCTMarcarVisiveis(false)">Limpar visíveis</button><strong id="cal-jogo-ct-count"></strong></div><div class="cal-jogo-manual-list cal-jogo-ct-list">${conteudo||'<p>Nenhum atleta encontrado.</p>'}</div><div class="cal-jogo-sub-actions"><button type="button" class="primary" onclick="calJogoCloseModal(\'cal-jogo-ct-atletas-modal\')">Concluir seleção</button></div></div>`;
 calJogoFiltrarTodosCT();calJogoTodosCTSync();
}
function calJogoFiltrarTodosCT(){
 const s=calJogoEditorState;if(!s)return;
 const filtroAno=document.getElementById('cal-jogo-ct-ano')?.value;s.manualAnoFiltro=filtroAno===undefined?'todos':(filtroAno||'todos');s.manualBuscaTodos=String(document.getElementById('cal-jogo-busca-todos-ct')?.value||'').trim().toLocaleLowerCase('pt-BR');
 const anoSelecionado=s.manualAnoFiltro==='__sem_ano__'?'':s.manualAnoFiltro;
 document.querySelectorAll('#cal-jogo-ct-atletas-modal .cal-jogo-manual-row').forEach(row=>{const anoOK=s.manualAnoFiltro==='todos'||row.dataset.year===anoSelecionado;row.hidden=!anoOK||!!s.manualBuscaTodos&&!row.dataset.search.includes(s.manualBuscaTodos);});
 document.querySelectorAll('#cal-jogo-ct-atletas-modal .cal-jogo-year-group').forEach(g=>{g.hidden=!g.querySelector('.cal-jogo-manual-row:not([hidden])');});
 calJogoTodosCTSync();
}
function calJogoTodosCTToggle(i,checked){const s=calJogoEditorState,x=s?.manualTodosEntries?.[i];if(!s||!x)return;if(checked){s.manualSelected.add(x.identityKey);s.manualMap.set(x.identityKey,{nomeCompleto:x.nomeCompleto,nascimento:x.nascimento});}else s.manualSelected.delete(x.identityKey);calJogoManualSync();}
function calJogoTodosCTSync(){
 const s=calJogoEditorState;if(!s)return;
 document.querySelectorAll('#cal-jogo-ct-atletas-modal input[data-todos-ct-index]').forEach(el=>{const x=s.manualTodosEntries[Number(el.dataset.todosCtIndex)];if(x)el.checked=s.manualSelected.has(x.identityKey);});
 const count=document.getElementById('cal-jogo-ct-count');if(count)count.textContent=`Selecionados no total: ${s.manualSelected.size}`;
}
function calJogoTodosCTMarcarVisiveis(marcar){
 const s=calJogoEditorState;if(!s)return;
 document.querySelectorAll('#cal-jogo-ct-atletas-modal .cal-jogo-manual-row:not([hidden]) input[data-todos-ct-index]').forEach(el=>{const x=s.manualTodosEntries[Number(el.dataset.todosCtIndex)];if(!x)return;if(marcar){s.manualSelected.add(x.identityKey);s.manualMap.set(x.identityKey,{nomeCompleto:x.nomeCompleto,nascimento:x.nascimento});}else s.manualSelected.delete(x.identityKey);});calJogoManualSync();
}
function calJogoManualMarcarVisiveis(marcar){
 const s=calJogoEditorState;if(!s)return;
 document.querySelectorAll('#cal-jogo-manual-modal .cal-jogo-manual-row:not([hidden]) input[data-entry-index]').forEach(el=>{const a=s.manualEntries[Number(el.dataset.entryIndex)];if(!a)return;if(marcar)s.manualSelected.add(a.identityKey);else s.manualSelected.delete(a.identityKey);});calJogoManualSync();
}
async function calJogoSalvarSelecaoManual(){
 const s=calJogoEditorState;if(!s||s.busy)return;const lista=[...s.manualSelected].map(k=>s.manualMap.get(k)).filter(Boolean);
 if(!lista.length&&!confirm('A lista ficará sem convocados. Confirmar que a convocação foi importada e não há atleta convocado?'))return;
 const fora=(s.convocados||[]).filter(a=>!s.manualMap.has(calJogoIdentidadeKey(a))).length;if(fora&&!confirm(`${fora} convocado(s) atualmente salvo(s) não estão no cadastro/lista elegível e serão removidos. Continuar?`))return;
 if(await calJogoImportarConvocados(lista))calJogoCloseModal('cal-jogo-manual-modal');
}
async function calJogoImportarConvocados(lista){
 const s=calJogoEditorState;if(!s||s.busy)return false;
 const unicos=new Map();(lista||[]).forEach(x=>{const k=calJogoIdentidadeKey(x);if(k&&!unicos.has(k))unicos.set(k,{nomeCompleto:x.nomeCompleto||x.nome_completo||'',nascimento:x.nascimento||''});});
 const payload=[...unicos.values()].filter(x=>x.nomeCompleto&&x.nascimento).map(x=>({nome_completo:x.nomeCompleto,nascimento:x.nascimento}));
 s.busy=true;s.error='';s.notice='Importando convocação…';calJogoAtualizarStatusEditor();calJogoMensagemEditor(s.notice);
 try{
  const {data,error}=await _supabase.rpc('portal_jogo_convocacao_importar',{p_data:s.data,p_categoria:s.categoria,p_convocados:payload});if(error)throw error;
  let r=data;if(typeof r==='string')r=JSON.parse(r);if(r?.convocacao_importada!==true)throw new Error('O Supabase não confirmou a importação.');
  s.convocados=payload.map(x=>({nomeCompleto:x.nome_completo,nascimento:x.nascimento}));s.rosterLoaded=true;s.rosterError='';s.config={...s.config,convocacao_importada:true,atualizado_em:new Date().toISOString()};s.notice=`Convocação importada: ${payload.length} atleta(s).`;calJogoAtualizarCache(s.config);renderCalendarioTreino();calJogoMensagemEditor(s.notice,'ok');return true;
 }catch(e){console.warn('Importação da convocação do jogo:',e);s.error='Não foi possível importar a convocação. Confira o SQL e tente novamente.';s.notice='';calJogoMensagemEditor(s.error,'error');return false;}
 finally{s.busy=false;calJogoAtualizarStatusEditor();calJogoRenderListaConvocados();const b=document.querySelector('#cal-jogo-editor-modal .cal-jogo-actions button:nth-child(2)');if(b)b.disabled=s.config.convocacao_importada===true&&!s.rosterLoaded;const save=document.querySelector('#cal-jogo-editor-modal .cal-jogo-save');if(save)save.disabled=false;}
}
function renderCalendarioTreino(){
 const m=document.getElementById('calendario-treino-modal');if(!m)return;
 const ano=calTreinoState.ano,mes=calTreinoState.mes,titulo=new Date(ano,mes,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}),start=(new Date(ano,mes,1).getDay()+6)%7,days=new Date(ano,mes+1,0).getDate(),hoje=calTreinoISO(new Date()),cells=[];
 for(let i=0;i<start;i++)cells.push('<div class="cal-treino-empty"></div>');
 for(let day=1;day<=days;day++){
  const d=new Date(ano,mes,day),iso=calTreinoISO(d),wk=[0,6].includes(d.getDay()),nPSR=CAL_TREINO_CATS.filter(c=>calTreinoTem(iso,c.id,'psr')).length,nPSE=CAL_TREINO_CATS.filter(c=>calTreinoTem(iso,c.id,'pse')).length,nJogo=CAL_TREINO_CATS.filter(c=>calTreinoJogoAtivo(iso,c.id)).length;
  cells.push(`<button type="button" class="cal-treino-day${calTreinoState.sel===iso?' sel':''}${iso===hoje?' hoje':''}${wk?' wk':''}${calTreinoState.ready&&(nPSR||nPSE||nJogo)?' ok':''}${nJogo?' has-game':''}" data-cal-data="${iso}" onclick="calTreinoSel('${iso}')"><b>${day}</b><i>PSR ${calTreinoState.ready?nPSR+'/4':'—'}</i><i>PSE ${calTreinoState.ready?nPSE+'/4':'—'}</i><i>Jogo ${calTreinoState.gameReady?nJogo+'/4':'—'}</i></button>`);
 }
 const disabled=!calTreinoState.ready||calTreinoState.carregando||calTreinoState.salvando,gameDisabled=!calTreinoState.gameReady||calTreinoState.carregando||calTreinoState.salvando;
 const checks=CAL_TREINO_CATS.map(c=>{
  const jogo=calTreinoJogoAtivo(calTreinoState.sel,c.id);
  const q=['psr','pse'].map(tipo=>{const on=calTreinoTem(calTreinoState.sel,c.id,tipo),pad=calTreinoPadrao(c.id,calTreinoParse(calTreinoState.sel));return `<label class="${on&&calTreinoState.ready?'on':''}"><input type="checkbox" data-cal-cat="${c.id}" data-cal-tipo="${tipo}" aria-label="${c.label} — ${tipo.toUpperCase()}" ${on&&calTreinoState.ready?'checked':''} ${disabled?'disabled':''} onchange="calTreinoToggle('${c.id}','${tipo}',this.checked)"><span>${tipo.toUpperCase()}</span>${calTreinoState.ready&&on!==pad?'<em>alterado</em>':''}</label>`;}).join('');
  return `<div class="cal-questionario-row"><strong>${c.label}</strong>${q}<div class="cal-jogo-control">${jogo?`<button type="button" class="cal-jogo-edit" title="Editar configuração do Jogo" aria-label="Editar configuração do Jogo — ${c.label}" ${gameDisabled?'disabled':''} onclick="calTreinoEditarJogo('${c.id}')">✏️</button>`:''}<label class="cal-jogo-toggle${jogo?' on':''}${gameDisabled?' disabled':''}"><input type="checkbox" aria-label="${c.label} — Jogo" ${jogo?'checked':''} ${gameDisabled?'disabled':''} onchange="calTreinoToggleJogo('${c.id}',this.checked)"><span>Jogo</span></label></div></div>`;
 }).join('');
 m.innerHTML=`<div class="cal-treino-card"><button class="cal-treino-close" onclick="closeCalendarioTreino()">×</button><h2>Calendário — PSR, PSE e Jogo</h2><p class="cal-treino-help">Jogo é uma configuração por data e categoria. Atletas só veem Pré/Pós depois da importação da convocação; coordenação mantém o acesso de conferência.</p><div class="cal-treino-nav"><button type="button" onclick="calTreinoMes(-1)" ${calTreinoState.salvando?'disabled':''}>‹</button><strong>${titulo}</strong><button type="button" onclick="calTreinoMes(1)" ${calTreinoState.salvando?'disabled':''}>›</button></div><div class="cal-treino-week"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div><div class="cal-treino-grid">${cells.join('')}</div>${calTreinoState.error?'<div class="cal-treino-error" role="alert">'+calJogoEsc(calTreinoState.error)+'</div>':''}${calTreinoState.jogoError?'<div class="cal-treino-error cal-jogo-calendar-error" role="alert">'+calJogoEsc(calTreinoState.jogoError)+'</div>':''}${calTreinoState.carregando?'<p class="cal-treino-load">Carregando...</p>':''}${calTreinoState.salvando?'<p class="cal-treino-load" role="status">Salvando...</p>':''}<div class="cal-treino-dia"><h3>${calTreinoParse(calTreinoState.sel).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'})}</h3><div class="cal-questionarios">${checks}</div></div><button type="button" class="cal-treino-refresh" ${calTreinoState.salvando?'disabled':''} onclick="carregarCalendarioTreino()">Atualizar calendário</button></div>`;
}

const MONITORAMENTO_CARGA_VIEW = 'vw_monitoramento_carga_psr_pse';

let monitorCargaState = { lista: [], carregando: false, data: '', ano: 'todos', zona: 'todas', busca: '', somenteAlertas: false, regraOuro: false };

function mcEscape(valor){return typeof escapeHtmlJogos==='function'?escapeHtmlJogos(valor):String(valor??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[s]));}
function mcNorm(valor){return String(valor||'').trim().replace(/\s+/g,' ');}
function mcBR(valor){if(!valor)return '';const s=String(valor).slice(0,10);const m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(m)return `${m[3]}/${m[2]}/${m[1]}`;const d=new Date(valor);return isNaN(d)?s:d.toLocaleDateString('pt-BR');}
function mcNum(valor,dig=0){if(valor===null||valor===undefined||valor==='')return '—';const n=Number(valor);if(Number.isNaN(n))return '—';return dig>0?n.toFixed(dig).replace('.',','):String(Math.round(n));}
function mcParseAlertas(valor){if(Array.isArray(valor))return valor.filter(Boolean);if(typeof valor==='string'){try{const arr=JSON.parse(valor);return Array.isArray(arr)?arr.filter(Boolean):[];}catch(e){return valor? [valor]:[];}}return [];}
function mcValorFlex(row,termos){const chave=Object.keys(row||{}).find(k=>termos.some(t=>String(k).toLowerCase().includes(String(t).toLowerCase())));return chave?row[chave]:'';}
function mcAtletaBase(row){return (excelData||[]).find(r=>AE.key(aeIdRow(r))===AE.key(row))||null;}
function mcApelido(row){const base=mcAtletaBase(row);return base?(mcNorm(mcValorFlex(base,['apelido'])||valorColunaExata(base,'APELIDO'))||row.nome_completo):row.nome_completo;}
function mcAno(row){const base=mcAtletaBase(row);return AE.ano(base?aeIdRow(base):{...row,ano:String(row?.ano||'')},'monitoramento');}
function mcTemAlerta(row){
 const alertas=mcParseAlertas(row.alertas_itens);
 return alertas.length>0 || !!row.regra_ouro_ajustar || ['amarelo','vermelho'].includes(String(row.zona_cor||'')) || ['salto','salto grande'].includes(String(row.alerta_variacao||''));
}
function mcDadosFiltrados(){
 let dados=[...(monitorCargaState.lista||[])];
 if(monitorCargaState.data)dados=dados.filter(r=>String(r.data).slice(0,10)===monitorCargaState.data);
 if(monitorCargaState.ano!=='todos')dados=dados.filter(r=>mcAno(r)===monitorCargaState.ano);
 if(monitorCargaState.zona!=='todas')dados=dados.filter(r=>String(r.zona_cor||'sem')===monitorCargaState.zona);
 if(monitorCargaState.somenteAlertas)dados=dados.filter(mcTemAlerta);
 if(monitorCargaState.regraOuro)dados=dados.filter(r=>!!r.regra_ouro_ajustar);
 const busca=mcNorm(monitorCargaState.busca).toLowerCase();
 if(busca)dados=dados.filter(r=>`${mcApelido(r)} ${r.nome_completo||''} ${mcAno(r)}`.toLowerCase().includes(busca));
 return dados.sort((a,b)=>String(b.data).localeCompare(String(a.data))||String(mcApelido(a)).localeCompare(String(mcApelido(b)),'pt-BR'));
}
function mcAnosDisponiveis(){return [...new Set([...aeAnosDestino(),...(excelData||[]).map(r=>AE.ano(aeIdRow(r),'monitoramento'))])].filter(Boolean).sort();}
function mcResumo(dados){
 return {total:dados.length, ouro:dados.filter(r=>r.regra_ouro_ajustar).length, vermelho:dados.filter(r=>r.zona_cor==='vermelho').length, amarelo:dados.filter(r=>r.zona_cor==='amarelo').length, alertas:dados.filter(mcTemAlerta).length};
}
function mcZonaLabel(row){return row.zona||'Histórico insuficiente';}
function mcAlertasHTML(row){
 const a=mcParseAlertas(row.alertas_itens);
 if(row.alerta_variacao)a.push(row.alerta_variacao==='salto grande'?'Salto grande de carga':'Salto de carga');
 if(row.regra_ouro_ajustar)a.push('Regra de ouro: ajustar carga');
 return a.length?a.map(x=>`<span>${mcEscape(x)}</span>`).join(''):'<em>—</em>';
}
function renderMonitoramentoCargaTabela(dados){
 if(!dados.length)return '<div class="mc-empty">Nenhum registro encontrado para os filtros selecionados.</div>';
 return `<div class="mc-table-wrap"><table class="mc-table"><thead><tr><th>Atleta</th><th>Data</th><th>PSE</th><th>PSR</th><th>Carga</th><th>CA 7</th><th>CC 28</th><th>ACWR</th><th>Zona</th><th>Recuperação</th><th>Variação</th><th>Alertas</th></tr></thead><tbody>${dados.map(r=>`<tr class="${r.regra_ouro_ajustar?'mc-regra':''}"><td class="mc-atleta"><b>${mcEscape(mcApelido(r))}</b><small>${mcEscape(r.nome_completo||'')} ${mcAnoReal(r)?'• '+mcEscape(mcAnoReal(r)):''}</small></td><td>${mcBR(r.data)}</td><td>${mcNum(r.pse_valor)}</td><td>${mcNum(r.psr_total)}</td><td>${mcNum(r.carga_sessao)}</td><td>${mcNum(r.carga_aguda)}</td><td>${mcNum(r.carga_cronica,1)}</td><td>${mcNum(r.acwr,2)}</td><td><span class="mc-zona ${mcEscape(r.zona_cor||'sem')}">${mcEscape(mcZonaLabel(r))}</span></td><td>${mcEscape(r.classificacao_recuperacao||'—')}</td><td>${r.perc_variacao!==null&&r.perc_variacao!==undefined?mcNum(r.perc_variacao,1)+'%':'—'}</td><td class="mc-alertas">${mcAlertasHTML(r)}</td></tr>`).join('')}</tbody></table></div>`;
}
function renderMonitoramentoCargaModal(){
 const modal=document.getElementById('monitoramento-carga-modal');if(!modal)return;
 const dados=mcDadosFiltrados();const res=mcResumo(dados);const anos=mcAnosDisponiveis();
 const datas=[...new Set((monitorCargaState.lista||[]).map(r=>String(r.data).slice(0,10)).filter(Boolean))].sort().reverse();
 const html=`<div class="mc-card"><button class="mc-close" onclick="closeMonitoramentoCargaModal()">×</button><div class="mc-head"><img src="logo.png"><div><h2>Monitoramento de Carga</h2><p>PSR × PSE • sRPE 120min • últimos 7/28 registros válidos</p></div></div><div class="mc-filtros"><label>Data <input type="date" value="${mcEscape(monitorCargaState.data)}" onchange="setMonitorCargaFiltro('data',this.value)"></label><button onclick="setMonitorCargaFiltro('data','')">Todas datas</button><select onchange="setMonitorCargaFiltro('ano',this.value)"><option value="todos">Todos os anos</option>${anos.map(a=>`<option value="${mcEscape(a)}" ${monitorCargaState.ano===a?'selected':''}>${mcEscape(a)}</option>`).join('')}</select><select onchange="setMonitorCargaFiltro('zona',this.value)"><option value="todas">Todas as zonas</option><option value="azul" ${monitorCargaState.zona==='azul'?'selected':''}>Azul - baixa</option><option value="verde" ${monitorCargaState.zona==='verde'?'selected':''}>Verde - normal</option><option value="amarelo" ${monitorCargaState.zona==='amarelo'?'selected':''}>Amarelo - atenção</option><option value="vermelho" ${monitorCargaState.zona==='vermelho'?'selected':''}>Vermelho - sobrecarga</option><option value="sem" ${monitorCargaState.zona==='sem'?'selected':''}>Histórico insuficiente</option></select><input class="mc-busca" placeholder="Buscar atleta..." value="${mcEscape(monitorCargaState.busca)}" oninput="setMonitorCargaFiltro('busca',this.value)"><label class="mc-check"><input type="checkbox" ${monitorCargaState.somenteAlertas?'checked':''} onchange="setMonitorCargaFiltro('somenteAlertas',this.checked)"> Alertas</label><label class="mc-check"><input type="checkbox" ${monitorCargaState.regraOuro?'checked':''} onchange="setMonitorCargaFiltro('regraOuro',this.checked)"> Regra ouro</label><button class="mc-refresh" onclick="carregarMonitoramentoCarga()">Atualizar</button><button onclick="imprimirMonitoramentoCarga()">Imprimir/PDF</button></div><div class="mc-summary"><div><b>${res.total}</b><span>Registros</span></div><div class="ouro"><b>${res.ouro}</b><span>Regra ouro</span></div><div class="red"><b>${res.vermelho}</b><span>Sobrecarga</span></div><div class="yellow"><b>${res.amarelo}</b><span>Atenção</span></div><div><b>${res.alertas}</b><span>Com alertas</span></div></div><div id="mc-print-area"><p class="mc-note">CA e % variação aparecem a partir de 7 registros válidos de PSE. CC e ACWR aparecem a partir de 28 registros válidos.</p>${monitorCargaState.carregando?'<div class="mc-loading">Carregando dados...</div>':renderMonitoramentoCargaTabela(dados)}</div></div>`;
 const busca=modal.querySelector('.mc-busca');
 if(busca && document.activeElement===busca && modal.querySelector('.mc-summary') && modal.querySelector('#mc-print-area')){
  const template=document.createElement('template');template.innerHTML=html;
  modal.querySelector('.mc-summary').replaceWith(template.content.querySelector('.mc-summary'));
  modal.querySelector('#mc-print-area').replaceWith(template.content.querySelector('#mc-print-area'));
 }else{modal.innerHTML=html;}
 modal.style.display='flex';
}
async function openMonitoramentoCargaModal(){
 if(!await aeExigir())return;
 let modal=document.getElementById('monitoramento-carga-modal');
 if(!modal){modal=document.createElement('div');modal.id='monitoramento-carga-modal';modal.className='mc-overlay';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeMonitoramentoCargaModal();});}
 modal.style.display='flex';renderMonitoramentoCargaModal();await carregarMonitoramentoCarga();
}
function closeMonitoramentoCargaModal(){const modal=document.getElementById('monitoramento-carga-modal');if(modal)modal.style.display='none';}
function setMonitorCargaFiltro(campo,valor){monitorCargaState[campo]=valor;renderMonitoramentoCargaModal();}
async function carregarMonitoramentoCarga(){
 monitorCargaState.carregando=true;renderMonitoramentoCargaModal();
 try{
  const {data,error}=await _supabase.from(MONITORAMENTO_CARGA_VIEW).select('*').order('data',{ascending:false}).limit(5000);
  if(error)throw error;
  monitorCargaState.lista=data||[];
  if(!monitorCargaState.data&&monitorCargaState.lista.length)monitorCargaState.data=String(monitorCargaState.lista[0].data).slice(0,10);
 }catch(e){console.error(e);alert('Erro ao carregar Monitoramento de Carga. Verifique a view vw_monitoramento_carga_psr_pse no Supabase.');monitorCargaState.lista=[];}
 finally{monitorCargaState.carregando=false;renderMonitoramentoCargaModal();}
}
function imprimirMonitoramentoCarga(){
 const area=document.getElementById('mc-print-area');if(!area)return;
 const w=window.open('','_blank','width=1200,height=850');
 w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Monitoramento de Carga</title><style>body{font-family:Arial,sans-serif;margin:12px}.mc-note{font-size:11px;color:#555}.mc-table{width:100%;border-collapse:collapse;font-size:10px}.mc-table th{background:#58111a;color:#f9c614}.mc-table th,.mc-table td{border:1px solid #999;padding:4px;text-align:center}.mc-atleta{text-align:left!important}.mc-atleta b{display:block}.mc-atleta small{display:block;color:#555}.mc-zona{border-radius:8px;padding:3px 6px;font-weight:bold}.mc-zona.azul{background:#dbeafe}.mc-zona.verde{background:#dcfce7}.mc-zona.amarelo{background:#fef3c7}.mc-zona.vermelho{background:#fee2e2}.mc-alertas span{display:block}.mc-regra{background:#fff1f2}@page{size:landscape;margin:8mm}</style></head><body><h2>Monitoramento de Carga - CFA Prosol</h2>${area.outerHTML}<script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`);
 w.document.close();
}

/* === RELATÓRIO PSR / PSE - PORTAL DO ATLETA === */
const RELATORIO_PSRPSE_EXTRAS_KEY = 'prosol_relatorio_psrpse_extras_v1';
let relatorioPsrPseState = {
 tipo:'psr',
 data:'',
 view:'notas',
 sort:{key:'nome',dir:'asc'},
 categorias:{sub11:false,sub12:false,sub13:false,sub16:false},
 respostas:[],
 carregando:false
};
let relatorioPsrPseExtraModal = {categoriaId:'sub16',filtroAno:'todos',busca:''};
let relatorioPsrPseExtras = carregarRelatorioPsrPseExtras();

function rppEscape(v){return typeof escapeHtmlJogos==='function'?escapeHtmlJogos(v):String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[s]));}
function rppCats(){return categoriasTrabalhoDiarioConfig();}
function rppCatIds(){return Object.keys(rppCats());}
function rppDataISO(data){
 if(data instanceof Date && !isNaN(data)) return data.getFullYear()+'-'+String(data.getMonth()+1).padStart(2,'0')+'-'+String(data.getDate()).padStart(2,'0');
 const s=String(data||'');
 const m=s.match(/(\d{4})-(\d{2})-(\d{2})/);
 if(m) return m[1]+'-'+m[2]+'-'+m[3];
 const d=new Date(data); if(isNaN(d)) return '';
 return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function rppParseData(valor){const s=String(valor||'');const m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return new Date(+m[1],+m[2]-1,+m[3]);const d=new Date(s);return isNaN(d)?new Date():d;}
function rppBR(valor,ano=false){const d=rppParseData(valor);return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}${ano?`/${d.getFullYear()}`:''}`;}
function rppAjustarFimSemanaParaSexta(valor){const d=rppParseData(valor);const dia=d.getDay();if(dia===6)d.setDate(d.getDate()-1);else if(dia===0)d.setDate(d.getDate()-2);return rppDataISO(d);}
function rppDataPadrao(){return rppAjustarFimSemanaParaSexta(rppDataISO(new Date()));}
function rppInicioSemana(valor){const d=rppParseData(valor);const dia=d.getDay();const diff=dia===0?-6:1-dia;d.setDate(d.getDate()+diff);d.setHours(0,0,0,0);return d;}
function rppDiasUteisSemana(valor){const ini=rppInicioSemana(valor);return [0,1,2,3,4].map(i=>{const d=new Date(ini);d.setDate(ini.getDate()+i);return rppDataISO(d);});}
function rppDiasUteisMes(valor){const base=rppParseData(valor);const d=new Date(base.getFullYear(),base.getMonth(),1);const out=[];while(d.getMonth()===base.getMonth()){const dia=d.getDay();if(dia>=1&&dia<=5)out.push(rppDataISO(d));d.setDate(d.getDate()+1);}return out;}
function rppDiasUteisEntre(iniISO,fimISO){
 const a=rppParseData(iniISO), b=rppParseData(fimISO);
 if(isNaN(a)||isNaN(b)) return [relatorioPsrPseState.data];
 const ini=a<=b?a:b, fim=a<=b?b:a;
 const out=[]; const d=new Date(ini.getFullYear(),ini.getMonth(),ini.getDate());
 while(d<=fim){ const wd=d.getDay(); if(wd>=1&&wd<=5) out.push(rppDataISO(d)); d.setDate(d.getDate()+1); }
 return out.length?out:[rppDataISO(ini)];
}
function rppPeriodoAtual(){
 if(relatorioPsrPseState.view==='semanal'){const dias=rppDiasUteisSemana(relatorioPsrPseState.data);return {inicio:dias[0],fim:dias[dias.length-1],dias};}
 if(relatorioPsrPseState.view==='mensal'){const dias=rppDiasUteisMes(relatorioPsrPseState.data);return {inicio:dias[0]||relatorioPsrPseState.data,fim:dias[dias.length-1]||relatorioPsrPseState.data,dias};}
 if(relatorioPsrPseState.view==='medias'){
  const modo=relatorioPsrPseState.mediasModo||'diaria';
  if(modo==='semanal'){const dias=rppDiasUteisSemana(relatorioPsrPseState.data);return {inicio:dias[0],fim:dias[dias.length-1],dias};}
  if(modo==='mensal'){const dias=rppDiasUteisMes(relatorioPsrPseState.data);return {inicio:dias[0]||relatorioPsrPseState.data,fim:dias[dias.length-1]||relatorioPsrPseState.data,dias};}
  if(modo==='periodo'){
   const de=relatorioPsrPseState.mediasDe||relatorioPsrPseState.data;
   const ate=relatorioPsrPseState.mediasAte||relatorioPsrPseState.data;
   const dias=rppDiasUteisEntre(de,ate);
   return {inicio:dias[0],fim:dias[dias.length-1],dias};
  }
  return {inicio:relatorioPsrPseState.data,fim:relatorioPsrPseState.data,dias:[relatorioPsrPseState.data]};
 }
 return {inicio:relatorioPsrPseState.data,fim:relatorioPsrPseState.data,dias:[relatorioPsrPseState.data]};
}
function rppDefaultCategorias(){const out={};rppCatIds().forEach(id=>out[id]=false);return out;}
function rppCategoriasSelecionadas(){return rppCatIds().filter(id=>!!relatorioPsrPseState.categorias[id]);}
function carregarRelatorioPsrPseExtras(){return {sub11:[],sub12:[],sub13:[],sub16:[]};}
function salvarRelatorioPsrPseExtras(){/* Cadastro antigo desativado. */}
function rppKeyAtletaId(id){return trabalhoChaveAtleta(id);}
function rppKeyExtra(extra){const nome=normalizarTextoTrabalho(extra?.nomeCompleto||extra?.nome_completo||extra?.nome||'');const nasc=normalizarTextoTrabalho(extra?.nascimento||extra?.data_nascimento||'');const ano=normalizarTextoTrabalho(extra?.ano||'');return nome+'||'+(nasc||ano);}
function rppNormalizarExtra(item,catId){const id=item?.id||item||{};return {nomeCompleto:normalizarTextoTrabalho(id.nomeCompleto||id.nome_completo||id.nome||''),apelido:normalizarTextoTrabalho(id.apelido||id.nomeCompleto||id.nome||''),nascimento:normalizarTextoTrabalho(id.nascimento||''),ano:normalizarTextoTrabalho(id.ano||''),categoriaId:catId};}
function rppExtraList(catId){return aeExtrasCat(catId,relatorioPsrPseState.tipo).map(a=>rppNormalizarExtra(a,catId));}
function rppLocalizarExtra(extra){
 const nome=normalizarTextoTrabalho(extra?.nomeCompleto||extra?.nome_completo||extra?.nome||'');
 const nasc=rppNormNasc(extra?.nascimento||extra?.data_nascimento||'');
 const ano=normalizarTextoTrabalho(extra?.ano||'');
 if(!nome) return null;
 const candidatos=trabalhoTodosAtletas().filter(a=>normalizarTextoTrabalho(a.id.nomeCompleto)===nome);
 // Datas ISO e brasileiras identificam a mesma pessoa; não confundir homônimos.
 let item=nasc?candidatos.find(a=>rppNormNasc(a.id.nascimento)===nasc):null;
 if(!item && !nasc){
  const porAno=ano?candidatos.filter(a=>String(a.id.ano)===ano):candidatos;
  if(porAno.length===1) item=porAno[0];
 }
 if(item) return item;
 return {id:{nomeCompleto:nome,apelido:normalizarTextoTrabalho(extra?.apelido||nome),nascimento:nasc,ano}};
}
function rppAtletasRelatorio(){
 // Mesma composição das médias e dos gráficos, inclusive quando só a categoria
 // de origem está selecionada: extras de outras categorias não retornam a ela.
 const mapa=new Map();
 rppCategoriasSelecionadas().forEach(catId=>{
  rppAtletasCategoriaTodas(catId).forEach(item=>{
   const key=rppKeyAtletaId(item.id);
   if(key) mapa.set(key,item);
  });
 });
 return Array.from(mapa.values());
}
function rppRespostaAtletaData(atleta,dataISO){
 const nome=normalizarTextoTrabalho(atleta?.id?.nomeCompleto||'');
 const nasc=rppNormNasc(atleta?.id?.nascimento||'');
 const alvo=rppIsoData(dataISO);
 const idx=relatorioPsrPseState.respIdx;
 if(idx && idx.size){
  if(nasc && idx.has(alvo+'|'+nome+'|'+nasc)) return idx.get(alvo+'|'+nome+'|'+nasc);
  if(idx.has(alvo+'|'+nome)) return idx.get(alvo+'|'+nome);
  return null;
 }
 return (relatorioPsrPseState.respostas||[]).find(r=>{
  const rn=normalizarTextoTrabalho(r.nome_completo||r.nomeCompleto||'');
  const rnas=rppNormNasc(r.nascimento||r.data_nascimento||'');
  const rd=rppIsoData(r.data);
  if(rd!==alvo) return false;
  if(rn!==nome) return false;
  if(nasc && rnas && nasc!==rnas) return false;
  return true;
 })||null;
}
function rppObjResposta(row,tipo=relatorioPsrPseState.tipo){const obj=row&&row[tipo];if(obj&&typeof obj==='object')return obj;if(tipo==='pse'&&obj!==undefined&&obj!==null&&obj!=='')return {valor:obj};return {};}
function rppRespondido(row,tipo=relatorioPsrPseState.tipo){
 const obj=rppObjResposta(row,tipo);
 if(tipo==='psr')return ['sono','fadiga','dor_muscular','estresse_mental','motivacao'].some(k=>obj[k]!==undefined&&obj[k]!==null&&obj[k]!=='' ) || !!obj.preenchido_em;
 return obj.valor!==undefined&&obj.valor!==null&&obj.valor!=='' || !!obj.preenchido_em;
}
function rppValorCampo(atleta,key,dataISO=relatorioPsrPseState.data){
 const row=rppRespostaAtletaData(atleta,dataISO);const obj=rppObjResposta(row);
 if(key==='nome')return atleta.id.apelido||atleta.id.nomeCompleto||'';
 if(key==='ano')return atleta.id.ano||'';
 if(key==='respondeu')return rppRespondido(row)?1:0;
 if(key==='descricao')return relatorioPsrPseState.tipo==='psr'?(obj.dor_descricao||''):(obj.descricao||'');
 if(key==='pse_valor')return obj.valor;
 if(key==='sono')return obj.sono;
 if(key==='fadiga')return obj.fadiga;
 if(key==='dor_muscular')return obj.dor_muscular;
 if(key==='estresse_mental')return obj.estresse_mental;
 if(key==='motivacao')return obj.motivacao;
 if(key.startsWith('dia:')){const dia=key.slice(4);return rppRespondido(rppRespostaAtletaData(atleta,dia))?1:0;}
 if(key==='nota_psr'){return rppNotaPsrNum(rppRespostaAtletaData(atleta,dataISO));}
 if(key==='total'){return rppPeriodoAtual().dias.reduce((acc,d)=>acc+(rppRespondido(rppRespostaAtletaData(atleta,d))?1:0),0);}
 return '';
}
function rppSortHeader(key,label){
 const sort=relatorioPsrPseState.sort||{};const active=sort.key===key;const arrow=active?(sort.dir==='asc'?' ▲':' ▼'):'';
 return `<th class="${active?'rpp-sort-active':''}"><button type="button" onclick="sortRelatorioPsrPse('${key}')">${rppEscape(label)}${arrow}</button></th>`;
}
function rppCompareNome(a,b){return String(a.id.apelido||a.id.nomeCompleto||'').localeCompare(String(b.id.apelido||b.id.nomeCompleto||''),'pt-BR');}
function rppAtletaEhGoleiro(atleta){
 const id=atleta?.id||{};
 const row=atleta?.row||(Number.isInteger(atleta?.index)?(excelData||[])[atleta.index]:{});
 const posicao=typeof goleiroPosicao==='function'?goleiroPosicao(row):'';
 const texto=[posicao,atleta?.posicao,atleta?.position,id.posicao,id.position].filter(v=>v!==undefined&&v!==null).join(' ');
 const normalizado=texto.normalize?texto.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase():texto.toLowerCase();
 return normalizado.includes('goleir');
}
function rppOrdenarAtletasNome(atletas){
 return [...(atletas||[])].sort((a,b)=>{
  if(relatorioPsrPseState.tipo==='pse'){
   const grupo=Number(rppAtletaEhGoleiro(b))-Number(rppAtletaEhGoleiro(a));
   if(grupo)return grupo;
  }
  return rppCompareNome(a,b);
 });
}
function rppOrdenarAtletas(atletas){
 const sort=relatorioPsrPseState.sort||{key:'nome',dir:'asc'};const key=sort.key;const dir=sort.dir==='desc'?-1:1;
 const numericKeys=['nota_psr','sono','fadiga','dor_muscular','estresse_mental','motivacao','pse_valor','respondeu','total'];
 return [...atletas].sort((a,b)=>{
  if(relatorioPsrPseState.tipo==='pse'){
   const grupo=Number(rppAtletaEhGoleiro(b))-Number(rppAtletaEhGoleiro(a));
   if(grupo)return grupo;
  }
  if(key==='nome')return dir*rppCompareNome(a,b);
  if(key==='ano'){const r=String(a.id.ano||'').localeCompare(String(b.id.ano||''),'pt-BR',{numeric:true});return r?dir*r:rppCompareNome(a,b);}
  if(key==='descricao'){
   const va=String(rppValorCampo(a,key)||'').trim();const vb=String(rppValorCampo(b,key)||'').trim();
   const ha=va?1:0,hb=vb?1:0;
   if(ha!==hb)return sort.dir==='desc'?hb-ha:ha-hb;
   const r=va.localeCompare(vb,'pt-BR');return r||rppCompareNome(a,b);
  }
  if(key.startsWith('dia:')||numericKeys.includes(key)){
   const va=rppValorCampo(a,key),vb=rppValorCampo(b,key);
   const ea=va===undefined||va===null||va==='',eb=vb===undefined||vb===null||vb==='';
   if(ea&&eb)return rppCompareNome(a,b);
   if(ea)return 1;if(eb)return -1;
   const na=Number(va),nb=Number(vb);const r=na===nb?0:(na>nb?1:-1);
   return r?dir*r:rppCompareNome(a,b);
  }
  return rppCompareNome(a,b);
 });
}
function rppDefaultSortParaView(view,tipo){if(view==='notas')return {key:tipo==='psr'?'nome':'nome',dir:'asc'};if(view==='mensal')return {key:'total',dir:'desc'};return {key:'nome',dir:'asc'};}
function rppValorHTML(valor){return (valor===undefined||valor===null||valor==='')?'<span class="rpp-muted">—</span>':rppEscape(valor);}
function rppVX(respondeu){return respondeu?'<span class="rpp-v">V</span>':'<span class="rpp-x">X</span>';}
function rppRenderTabelaNotas(atletas){
 const tipo=relatorioPsrPseState.tipo;
 let notaMedia=null;
 if(tipo==='psr'){
  const vals=[];
  (atletas||[]).forEach(a=>{ const n=rppNotaPsrNum(rppRespostaAtletaData(a,relatorioPsrPseState.data)); if(n!==null) vals.push(n); });
  if(vals.length) notaMedia=vals.reduce((s,v)=>s+v,0)/vals.length;
 }
 const cols=tipo==='psr'
  ? [{k:'nome',l:'Nome'},{k:'ano',l:'Ano'},{k:'nota_psr',l:'Nota ('+rppMediaBR(notaMedia)+')'},{k:'sono',l:'Qualidade do sono'},{k:'fadiga',l:'Fadiga'},{k:'estresse_mental',l:'Estresse'},{k:'motivacao',l:'Motivação'},{k:'dor_muscular',l:'Dor Muscular'},{k:'descricao',l:'Descrição'}]
  : [{k:'nome',l:'Nome'},{k:'ano',l:'Ano'},{k:'pse_valor',l:'PSE'},{k:'descricao',l:'Descrição'}];
 const rows=rppOrdenarAtletas(atletas).map(a=>{
  const row=rppRespostaAtletaData(a,relatorioPsrPseState.data);const obj=rppObjResposta(row,tipo);
  const classeGoleiro=tipo==='pse'&&rppAtletaEhGoleiro(a)?' class="rpp-goleiro-row"':'';
  if(tipo==='psr'){
   const nota=rppNotaPsrNum(row);
   return `<tr><td class="rpp-nome">${rppEscape(a.id.apelido||a.id.nomeCompleto)}</td><td>${rppEscape(a.id.ano||'')}</td><td><strong>${nota==null?'—':rppMediaBR(nota)}</strong></td><td>${rppValorHTML(obj.sono)}</td><td>${rppValorHTML(obj.fadiga)}</td><td>${rppValorHTML(obj.estresse_mental)}</td><td>${rppValorHTML(obj.motivacao)}</td><td>${rppValorHTML(obj.dor_muscular)}</td><td class="rpp-desc">${rppValorHTML(obj.dor_descricao)}</td></tr>`;
  }
  return `<tr${classeGoleiro}><td class="rpp-nome">${rppEscape(a.id.apelido||a.id.nomeCompleto)}</td><td>${rppEscape(a.id.ano||'')}</td><td>${rppValorHTML(obj.valor)}</td><td class="rpp-desc">${rppValorHTML(obj.descricao)}</td></tr>`;
 }).join('')||`<tr><td colspan="${cols.length}" class="rpp-empty">Nenhum atleta nas categorias selecionadas.</td></tr>`;
 return `<table class="rpp-table"><thead><tr>${cols.map(c=>rppSortHeader(c.k,c.l)).join('')}</tr></thead><tbody>${rows}</tbody></table>`;
}
function rppNomeAnoAtleta(atleta){return (atleta?.id?.apelido||atleta?.id?.nomeCompleto||'')+' - '+String(atleta?.id?.ano||'');}
function rppDiaSemanaTexto(valor){return rppParseData(valor).toLocaleDateString('pt-BR',{weekday:'long'}).replace(/^./,c=>c.toUpperCase());}
function rppRenderListaPresencaDiaria(atletas){
 const ordenados=rppOrdenarAtletasNome(atletas);
 if(!ordenados.length)return `<div class="rpp-list-report"><div class="rpp-empty">Selecione uma categoria para visualizar o relatório.</div></div>`;
 const respondidos=[];const ausentes=[];
 ordenados.forEach(a=>{(rppRespondido(rppRespostaAtletaData(a,relatorioPsrPseState.data))?respondidos:ausentes).push(a);});
 const lista=(arr,ok)=>arr.length?arr.map(a=>{const goleiro=relatorioPsrPseState.tipo==='pse'&&rppAtletaEhGoleiro(a);return `<li class="${ok?'ok':'no'}${goleiro?' rpp-goleiro-item':''}"><span>${ok?'✓':'×'}</span>${rppEscape(rppNomeAnoAtleta(a))}</li>`;}).join(''):'<li class="empty">Nenhum atleta.</li>';
 return `<div class="rpp-list-report"><div class="rpp-list-date">📅 ${rppBR(relatorioPsrPseState.data,true)} — ${rppEscape(rppDiaSemanaTexto(relatorioPsrPseState.data))}</div><div class="rpp-list-obs"><strong>Observações:</strong> -</div><div class="rpp-list-cols"><section class="rpp-list-col ok"><h3>Respondido (${respondidos.length})</h3><ul>${lista(respondidos,true)}</ul></section><section class="rpp-list-col no"><h3>Ausentes (${ausentes.length})</h3><ul>${lista(ausentes,false)}</ul></section></div></div>`;
}
function rppRenderTabelaResumo(atletas){
 const periodo=rppPeriodoAtual();
 const dias=periodo.dias;
 const view=relatorioPsrPseState.view;
 if(view==='diario')return rppRenderListaPresencaDiaria(atletas);
 const headDias=dias.map(d=>rppSortHeader('dia:'+d,rppBR(d))).join('');
 const totalHead=rppSortHeader('total','Total');
 const pctHead='<th><button type="button" disabled>%</button></th>';
 const rows=rppOrdenarAtletas(atletas).map(a=>{
  let total=0;
  const cells=dias.map(d=>{const ok=rppRespondido(rppRespostaAtletaData(a,d));if(ok)total++;return `<td>${rppVX(ok)}</td>`;}).join('');
  const pct=dias.length?Math.round((total/dias.length)*100):0;
  const classeGoleiro=relatorioPsrPseState.tipo==='pse'&&rppAtletaEhGoleiro(a)?' class="rpp-goleiro-row"':'';
  return `<tr${classeGoleiro}><td class="rpp-nome">${rppEscape(a.id.apelido||a.id.nomeCompleto)}</td><td>${rppEscape(a.id.ano||'')}</td>${cells}<td><strong>${total}/${dias.length}</strong></td><td>${pct}%</td></tr>`;
 }).join('')||`<tr><td colspan="${dias.length+4}" class="rpp-empty">Nenhum atleta nas categorias selecionadas.</td></tr>`;
 return `<table class="rpp-table rpp-table-resumo"><thead><tr>${rppSortHeader('nome','Nome')}${rppSortHeader('ano','Ano')}${headDias}${totalHead}${pctHead}</tr></thead><tbody>${rows}</tbody></table>`;
}
function rppTituloView(){
 const tipo=relatorioPsrPseState.tipo.toUpperCase();
 if(relatorioPsrPseState.view==='medias')return `${tipo} - médias`;
 if(relatorioPsrPseState.view==='notas')return `${tipo} - notas do dia ${rppBR(relatorioPsrPseState.data,true)}`;
 if(relatorioPsrPseState.view==='diario')return `${tipo} - relatório diário ${rppBR(relatorioPsrPseState.data,true)}`;
 if(relatorioPsrPseState.view==='semanal'){const dias=rppDiasUteisSemana(relatorioPsrPseState.data);return `${tipo} - relatório semanal ${rppBR(dias[0])} a ${rppBR(dias[4],true)}`;}
 const d=rppParseData(relatorioPsrPseState.data);return `${tipo} - relatório mensal ${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
}
function rppCategoriasTitulo(){const cats=rppCats();const sels=rppCategoriasSelecionadas();return sels.length?sels.map(id=>cats[id]?.label||id).join(', '):'Nenhuma categoria selecionada';}
function rppRenderExtrasChips(){return aeTextoCentral();}

function rppIsoData(v){
 if(!v) return '';
 const s=String(v);
 const m=s.match(/(\d{4})-(\d{2})-(\d{2})/);
 if(m) return m[1]+'-'+m[2]+'-'+m[3];
 const d=rppParseData(v);
 if(!d||isNaN(d)) return '';
 return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function rppNormNasc(v){
 const s=String(v||'').trim();
 const iso=s.match(/^(\d{4})-(\d{2})-(\d{2})/);
 if(iso) return iso[1]+'-'+iso[2]+'-'+iso[3];
 const br=s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
 if(br) return br[3]+'-'+br[2]+'-'+br[1];
 return normalizarTextoTrabalho(s);
}
function rppChaveAtletaAnularPse(item){
 const id=item&&item.id&&typeof item.id==='object'?item.id:(item||{});
 const chave=AE.key(id);if(chave)return chave;
 let raw=String(item&&item.atleta_key||trabalhoChaveAtleta(id)||'').trim();
 const sep=raw.lastIndexOf('||');
 if(sep>=0){const normalizada=AE.key({nomeCompleto:raw.slice(0,sep),nascimento:raw.slice(sep+2)});if(normalizada)return normalizada;}
 return normalizarTextoTrabalho(raw).toLowerCase();
}
function rppPseFoiAnulado(atleta,dataISO){
 if(relatorioPsrPseState.tipo!=='pse')return false;
 const idx=relatorioPsrPseState.avdPseAnulacoes;
 if(!(idx instanceof Map))return false;
 const key=rppChaveAtletaAnularPse(atleta),dia=rppIsoData(dataISO);
 return !!(key&&dia&&idx.get(dia+'|'+key));
}
function rppIndexarAnulacoesPse(rows){
 const latest=new Map();
 (rows||[]).forEach(r=>{
  const dia=rppIsoData(r.data),key=rppChaveAtletaAnularPse(r);if(!dia||!key)return;
  const id=dia+'|'+key,stamp=String(r.atualizado||r.atualizado_em||'');
  const catAtual=typeof AE.categoria==='function'?AE.categoria(r,'avd'):'';
  const preferida=r.categoria===catAtual?1:0,prev=latest.get(id);
  if(!prev||stamp>prev.stamp||(stamp===prev.stamp&&preferida>=prev.preferida))latest.set(id,{value:r.anular_pse===true||r.anular_pse==='true',stamp,preferida});
 });
 return new Map([...latest].map(([k,v])=>[k,v.value]));
}
async function rppFetchAnulacoesPse(inicio,fim){
 const page=1000,all=[];let from=0;
 while(true){
  const {data,error}=await _supabase.from('avaliacao_diaria_notas').select('data,categoria,atleta_key,nome_completo,nascimento,ano,anular_pse,atualizado').gte('data',inicio).lte('data',fim).order('data',{ascending:true}).order('categoria',{ascending:true}).range(from,from+page-1);
  if(error)throw error;
  const chunk=data||[];all.push(...chunk);if(chunk.length<page)break;from+=page;
 }
 return rppIndexarAnulacoesPse(all);
}
function rppColunaAnularPseAusente(error){
 const texto=[error&&error.message,error&&error.details,error&&error.hint,error&&error.code].filter(Boolean).join(' ').toLowerCase();
 return texto.includes('anular_pse')&&(texto.includes('column')||texto.includes('schema cache')||texto.includes('42703')||texto.includes('pgrst204'));
}
function rppNotaPseNum(row){
 if(!row) return null;
 let v=null;
 const obj=row.pse;
 if(obj && typeof obj==='object') v=obj.valor!==undefined?obj.valor:obj.pse;
 else if(obj!==undefined && obj!==null && obj!=='') v=obj;
 if(v===undefined||v===null||v==='') return null;
 const raw=String(v).trim().toLowerCase();
 if(raw===''||raw==='0'||raw==='0.0'||raw==='0,0'||raw.indexOf('repouso')>=0) return null;
 const n=Number(String(v).replace(',','.'));
 if(!Number.isFinite(n) || n===0) return null;
 return n;
}
function rppPsrCampo(v){
 if(v===undefined||v===null||v==='') return null;
 const n=Number(String(v).replace(',','.'));
 return Number.isFinite(n)?n:null;
}
function rppNotaPsrNum(row){
 const obj=rppObjResposta(row,'psr');
 const sono=rppPsrCampo(obj.sono);
 const fadiga=rppPsrCampo(obj.fadiga);
 const dor=rppPsrCampo(obj.dor_muscular);
 const estresse=rppPsrCampo(obj.estresse_mental);
 const motiv=rppPsrCampo(obj.motivacao);
 if([sono,fadiga,dor,estresse,motiv].some(v=>v===null)) return null;
 return sono + (5-fadiga) + (5-dor) + (5-estresse) + motiv;
}
function rppNotaParaMedia(row){
 return relatorioPsrPseState.tipo==='psr' ? rppNotaPsrNum(row) : rppNotaPseNum(row);
}
function rppMediaBR(n){ return (n==null||!Number.isFinite(n))?'—':n.toFixed(1).replace('.',','); }
function rppNomeDia(iso){
 const d=rppParseData(iso); const n=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
 return n[d.getDay()]||'';
}
function rppChaveExtraAtleta(extra,item){
 if(item&&item.id) return rppKeyAtletaId(item.id)||rppKeyExtra(extra);
 return rppKeyExtra(extra);
}
function rppAtletasCategoriaTodas(catId){return aeAtletasCat(catId,relatorioPsrPseState.tipo);}
function rppAtletaNoGrupoMediaPse(atleta,grupo){
 if(relatorioPsrPseState.tipo!=='pse'||!grupo)return true;
 const goleiro=rppAtletaEhGoleiro(atleta);
 return grupo==='goleiros'?goleiro:!goleiro;
}
function rppMediaCatDia(catId, iso, grupo){
 const atletas=rppAtletasCategoriaTodas(catId).filter(a=>rppAtletaNoGrupoMediaPse(a,grupo));
 const vals=[];
 const visto=new Set();
 atletas.forEach(a=>{
  const row=rppRespostaAtletaData(a, iso);
  const n=rppNotaParaMedia(row);
  if(n===null||rppPseFoiAnulado(a,iso)) return;
  const k=rppKeyAtletaId(a.id)||normalizarTextoTrabalho(a.id&&a.id.nomeCompleto||'');
  if(k && visto.has(k)) return;
  if(k) visto.add(k);
  vals.push(n);
 });
 if(!vals.length) return null;
 return vals.reduce((s,v)=>s+v,0)/vals.length;
}
function rppMediaCatPeriodo(catId, dias, grupo){
 const vals=[];
 const atletas=rppAtletasCategoriaTodas(catId).filter(a=>rppAtletaNoGrupoMediaPse(a,grupo));
 dias.forEach(iso=>{
  atletas.forEach(a=>{
   const n=rppNotaParaMedia(rppRespostaAtletaData(a, iso));
   if(n!==null&&!rppPseFoiAnulado(a,iso)) vals.push(n);
  });
 });
 if(!vals.length) return null;
 return vals.reduce((s,v)=>s+v,0)/vals.length;
}
function rppLinhaCats(mediasMap){
 return rppCatIds().map(id=>{
  const lab=(rppCats()[id]&&rppCats()[id].label)||id;
  return `<span class="rpp-med-cat"><b>${rppEscape(lab)}</b> ${rppMediaBR(mediasMap[id])}</span>`;
 }).join('');
}
function rppMediasTabela(rows){
 const cats=rppCatIds();
 const separarPse=relatorioPsrPseState.tipo==='pse';
 const head=separarPse
  ? '<th rowspan="2">Dia</th>'+cats.map(id=>'<th colspan="2">'+rppEscape((rppCats()[id]&&rppCats()[id].label)||id)+'</th>').join('')
  : '<th>Dia</th>'+cats.map(id=>'<th>'+rppEscape((rppCats()[id]&&rppCats()[id].label)||id)+'</th>').join('');
 const subHead=separarPse?'<tr>'+cats.map(()=>'<th>Linha</th><th class="rpp-med-sub-goleiros">Goleiros</th>').join('')+'</tr>':'';
 const body=rows.map(r=>{
  const tds=cats.map(id=>{
   const nomeCat=(rppCats()[id]&&rppCats()[id].label)||id;
   if(separarPse){
    const med=r.map[id]||{};
    const botao=grupo=>r.geral?` <button type="button" class="rpp-chart-btn rpp-no-print" title="Gráfico ${rppEscape(nomeCat)} — ${grupo==='linha'?'Linha':'Goleiros'}" onclick="rppAbrirGraficoMedias('${id}','${grupo}')">${rppChartIcon()}</button>`:'';
    return `<td class="rpp-med-linha">${rppMediaBR(med.linha)}${botao('linha')}</td><td class="rpp-med-goleiros">${rppMediaBR(med.goleiros)}${botao('goleiros')}</td>`;
   }
   const med=rppMediaBR(r.map[id]);
   if(!r.geral) return '<td>'+med+'</td>';
   return '<td>'+med+' <button type="button" class="rpp-chart-btn rpp-no-print" title="Gráfico '+rppEscape(nomeCat)+'" onclick="rppAbrirGraficoMedias(\''+id+'\')">'+rppChartIcon()+'</button></td>';
  }).join('');
  const lab=r.geral?(rppEscape(r.label)+' <button type="button" class="rpp-chart-btn rpp-no-print" title="Gráficos" onclick="rppAbrirGraficoMedias()">'+rppChartIcon()+'</button>'):rppEscape(r.label);
  return `<tr class="${r.geral?'rpp-med-geral-row':''}"><td class="rpp-nome">${lab}</td>${tds}</tr>`;
 }).join('');
 return `<table class="rpp-table rpp-med-table${separarPse?' rpp-med-table-split':''}"><thead><tr>${head}</tr>${subHead}</thead><tbody>${body}</tbody></table>`;
}
function rppChartIcon(){
 return '<svg class="rpp-chart-ico" viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2" fill="none" stroke="currentColor" stroke-width="1.8"/><polyline fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round" points="6 16 10 11 13 13 18 7"/><circle cx="6" cy="16" r="1.4" fill="currentColor"/><circle cx="10" cy="11" r="1.4" fill="currentColor"/><circle cx="13" cy="13" r="1.4" fill="currentColor"/><circle cx="18" cy="7" r="1.4" fill="currentColor"/></svg>';
}
function rppFechaGraficoMedias(){
 const m=document.getElementById('rpp-graf-modal');
 if(m){
  const box=m.querySelector('.rpp-graf-box');
  if(box && box.__rppZoomCleanup) box.__rppZoomCleanup();
  m.remove();
 }
}
function rppSvgSerie(pts, modo){
 const weekMode=modo==='mensal'||modo==='periodo';
 const w=560, h=weekMode?280:260, pl=42, pr=16, pt=28, pb=weekMode?58:52;
 const iw=w-pl-pr, ih=h-pt-pb;
 const n=Math.max(1, pts.length-1);
 const defined=pts.map((p,i)=>({i,v:p.v,wk:p.wk})).filter(p=>p.v!=null && Number.isFinite(p.v));
 let minY=0, maxY=1;
 if(defined.length){
  const vs=defined.map(p=>p.v);
  minY=Math.min.apply(null,vs)-0.5;
  maxY=Math.max.apply(null,vs)+0.5;
  if(maxY<=minY) maxY=minY+1;
 }
 function X(i){ return pl+(n? (i/n)*iw : iw/2); }
 function Y(v){ return pt+ih-((v-minY)/(maxY-minY))*ih; }
 const cores=['rgba(88,17,26,.16)','rgba(9,132,227,.16)','rgba(0,184,148,.16)','rgba(249,198,20,.22)','rgba(214,48,49,.14)','rgba(108,92,231,.16)'];
 let bands='';
 let labs='';
 if(weekMode){
  const weeks=[];
  pts.forEach(function(p,i){
   const k=p.wk||'';
   if(!weeks.length || weeks[weeks.length-1].k!==k) weeks.push({k:k, i0:i, i1:i, lab:p.wlab||''});
   else weeks[weeks.length-1].i1=i;
  });
  weeks.forEach(function(wk,wi){
   const x0=X(wk.i0)-(n?iw/n/2:8);
   const x1=X(wk.i1)+(n?iw/n/2:8);
   bands+='<rect x="'+Math.max(pl,x0)+'" y="'+pt+'" width="'+Math.max(4,Math.min(w-pr,x1)-Math.max(pl,x0))+'" height="'+ih+'" fill="'+cores[wi%cores.length]+'" stroke="none"/>';
   labs+='<text x="'+((X(wk.i0)+X(wk.i1))/2)+'" y="'+(h-22)+'" text-anchor="middle" font-size="9" font-weight="800" fill="#58111a">Semana</text>';
   labs+='<text x="'+((X(wk.i0)+X(wk.i1))/2)+'" y="'+(h-8)+'" text-anchor="middle" font-size="9" fill="#333">'+(wk.lab||'')+'</text>';
  });
 }else{
  labs=pts.map((p,i)=>'<text x="'+X(i)+'" y="'+(h-10)+'" text-anchor="middle" font-size="10" fill="#444">'+(p.l||'')+'</text>').join('');
 }
 let grid='';
 const steps=4;
 for(let g=0;g<=steps;g++){
  const val=minY+(maxY-minY)*(g/steps);
  const yy=Y(val);
  grid+='<line x1="'+pl+'" y1="'+yy+'" x2="'+(w-pr)+'" y2="'+yy+'" stroke="#e8e8e8" stroke-width="1"/>';
  grid+='<text x="'+(pl-6)+'" y="'+(yy+4)+'" text-anchor="end" font-size="10" fill="#666">'+val.toFixed(1).replace('.',',')+'</text>';
 }
 let d='';
 let lastI=-99;
 defined.forEach(function(p){
  const gap=p.i-lastI>2;
  d+=(d===''||gap?' M':' L')+X(p.i).toFixed(1)+' '+Y(p.v).toFixed(1);
  lastI=p.i;
 });
 const line=d?'<path d="'+d+'" fill="none" stroke="#58111a" stroke-width="3.6" stroke-linejoin="round" stroke-linecap="round"/>':'';
 const midY=pt+ih/2;
 const dots=defined.map(function(p){
  const txt=p.v.toFixed(1).replace('.',',');
  const cy=Y(p.v);
  const below=cy<midY;
  const ty=below? cy+20 : cy-12;
  return '<circle cx="'+X(p.i)+'" cy="'+cy+'" r="6" fill="#f9c614" stroke="#58111a" stroke-width="2"/>'
   +'<text x="'+X(p.i)+'" y="'+ty+'" text-anchor="middle" font-size="11" font-weight="800" fill="#58111a" stroke="#fff" stroke-width="3.5" paint-order="stroke">'+txt+'</text>';
 }).join('');
 return '<svg viewBox="0 0 '+w+' '+h+'" width="100%" height="'+h+'">'+bands+grid+line+dots+labs+'</svg>';
}
function rppPtsGrafico(catId, dias, modo, grupo){
 if(modo==='semanal'){
  return dias.map(function(iso){
   const v=rppMediaCatDia(catId, iso, grupo);
   const d=String(iso).slice(8,10)+'/'+String(iso).slice(5,7);
   return {l:d, v:v, wk:iso, weekend:false};
  });
 }
 if(!dias.length) return [];
 const a=rppParseData(dias[0]), b=rppParseData(dias[dias.length-1]);
 const out=[];
 for(let d=new Date(a.getTime()); d.getTime()<=b.getTime(); d.setDate(d.getDate()+1)){
  const iso=rppDataISO(d);
  const wd=d.getDay();
  const weekend=wd===0||wd===6;
  const ini=rppInicioSemana(iso);
  const fim=new Date(ini.getTime()); fim.setDate(ini.getDate()+4);
  const dd=function(dt){ return String(dt.getDate()).padStart(2,'0')+'/'+String(dt.getMonth()+1).padStart(2,'0'); };
  const wlab=dd(ini)+' a '+dd(fim);
  out.push({
   iso:iso, weekend:weekend, wk:rppDataISO(ini), wlab:wlab,
   v: weekend?null:rppMediaCatDia(catId, iso, grupo),
   l: weekend?'':dd(d)
  });
 }
 return out;
}
function rppAbrirGraficoMedias(catId,grupo){
 const modo=relatorioPsrPseState.mediasModo||'diaria';
 if(modo==='diaria') return;
 const periodo=rppPeriodoAtual();
 const dias=periodo.dias||[];
 if(!dias.length){ alert('Sem dias neste período.'); return; }
 const cats=catId?[catId]:rppCatIds();
 const grupos=relatorioPsrPseState.tipo==='pse'?(grupo?[grupo]:['linha','goleiros']):[null];
 const tit=modo==='semanal'?'semana':modo==='mensal'?'mês':'período';
 const blocos=cats.map(function(id){
  const lab=(rppCats()[id]&&rppCats()[id].label)||id;
  return grupos.map(function(g){
   const nomeGrupo=g==='linha'?'Linha':g==='goleiros'?'Goleiros':'';
   const tituloSerie=nomeGrupo?lab+' — '+nomeGrupo:lab;
   const pts=rppPtsGrafico(id, dias, modo, g||undefined);
   return '<div class="rpp-graf-cat"><h3>'+rppEscape(tituloSerie)+'</h3>'+rppSvgSerie(pts, modo)+'</div>';
  }).join('');
 }).join('');
 let m=document.getElementById('rpp-graf-modal');
 if(!m){ m=document.createElement('div'); m.id='rpp-graf-modal'; document.body.appendChild(m); }
 m.className='rpp-graf-overlay';
 m.onclick=function(e){ if(e.target===m) rppFechaGraficoMedias(); };
 const previousBox=m.querySelector('.rpp-graf-box');
 if(previousBox && previousBox.__rppZoomCleanup) previousBox.__rppZoomCleanup();
 m.innerHTML='<div class="rpp-graf-box"><button type="button" class="rpp-close" onclick="rppFechaGraficoMedias()">×</button><h2>Gráfico das médias — '+tit+'</h2><div class="rpp-graf-zoom">'+blocos+'</div></div>';
 m.style.display='flex';
 rppBindGrafZoom(m.querySelector('.rpp-graf-box'));
}
function rppGrafDesktop(){
 // Preserve the existing pinch/scroll behavior on phones and touch devices.
 return !/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent||'') &&
  !(window.matchMedia && window.matchMedia('(pointer:coarse)').matches);
}
function rppBindGrafZoomDesktop(box){
 const inner=box.querySelector('.rpp-graf-zoom');
 if(!inner) return;
 const overlay=box.closest('.rpp-graf-overlay');
 const toolbar=document.createElement('div');
 toolbar.className='rpp-graf-zoom-controls';
 toolbar.innerHTML='<label>Zoom <input type="text" inputmode="decimal" value="100%" aria-label="Zoom dos gráficos em porcentagem" title="Zoom de 100% a 400%" autocomplete="off" spellcheck="false"></label>';
 inner.before(toolbar);
 const viewport=document.createElement('div');
 viewport.className='rpp-graf-desktop-scroll';
 const size=document.createElement('div');
 size.className='rpp-graf-desktop-size';
 inner.before(viewport); viewport.appendChild(size); size.appendChild(inner);
 const input=toolbar.querySelector('input');
 let z=1, drag=null;
 function layout(){
  const width=viewport.clientWidth;
  if(!width) return;
  inner.style.width=width+'px';
  inner.style.transform='scale('+z+')';
  size.style.width=(width*z)+'px';
  size.style.height=(inner.offsetHeight*z)+'px';
  viewport.style.cursor=z>1?'grab':'';
  if(z===1) viewport.scrollLeft=0;
 }
 function readZoom(){
  const text=input.value.trim().replace(/%$/, '').trim().replace(',', '.');
  if(!/^\d+(?:\.\d+)?$/.test(text)) return null;
  const n=Number(text);
  return Number.isFinite(n) && n>=100 && n<=400?n:null;
 }
 function update(){
  const value=readZoom();
  if(value==null) return;
  z=value/100; layout();
 }
 function commit(){update();input.value=String(Math.round(z*10000)/100)+'%';}
 input.addEventListener('input',update);
 input.addEventListener('change',commit);
 input.addEventListener('blur',commit);
 input.addEventListener('keydown',function(e){
  if(e.key==='Enter'){e.preventDefault();commit();}
 });
 // No wheel listener: the mouse wheel always scrolls the overlay, never zooms.
 viewport.addEventListener('pointerdown',function(e){
  if(z<=1 || e.button!==0 || e.pointerType==='touch') return;
  e.preventDefault();
  drag={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:overlay?overlay.scrollTop:0};
  viewport.setPointerCapture(e.pointerId);
  viewport.style.cursor='grabbing';
 });
 viewport.addEventListener('pointermove',function(e){
  if(!drag) return;
  viewport.scrollLeft=drag.left+drag.x-e.clientX;
  if(overlay) overlay.scrollTop=drag.top+drag.y-e.clientY;
 });
 function end(e){
  drag=null;
  if(viewport.hasPointerCapture?.(e.pointerId)) viewport.releasePointerCapture(e.pointerId);
  viewport.style.cursor=z>1?'grab':'';
 }
 viewport.addEventListener('pointerup',end);
 viewport.addEventListener('pointercancel',end);
 viewport.addEventListener('lostpointercapture',function(){drag=null;});
 layout();
 if(window.ResizeObserver){
  const resize=new ResizeObserver(layout); resize.observe(viewport);
  // Detached dialogs need no further resize work.
  box.__rppZoomCleanup=function(){resize.disconnect();};
 }
}
function rppBindGrafZoom(box){
 if(!box) return;
 if(rppGrafDesktop()){rppBindGrafZoomDesktop(box);return;}
 const inner=box.querySelector('.rpp-graf-zoom');
 if(!inner) return;
 let z=1, x=0, y=0, pinch0=null, pan0=null;
 function apply(){
  z=Math.min(4, Math.max(1, z));
  if(z===1){ x=0; y=0; }
  inner.style.transform='translate('+x+'px,'+y+'px) scale('+z+')';
  box.style.cursor=z>1?'grab':'';
  box.style.touchAction=z>1?'none':'pan-y';
 }
 inner.style.transformOrigin='0 0';
 box.addEventListener('wheel', function(e){
  e.preventDefault();
  const r=inner.getBoundingClientRect();
  const mx=e.clientX-r.left, my=e.clientY-r.top;
  const nz=z*(e.deltaY>0?0.9:1.12);
  const clamped=Math.min(4, Math.max(1, nz));
  const k=clamped/z;
  x=mx-(mx-x)*k;
  y=my-(my-y)*k;
  z=clamped;
  apply();
 }, {passive:false});
 box.addEventListener('touchstart', function(e){
  if(e.touches.length===2){
   const a=e.touches[0], b=e.touches[1];
   pinch0={d:Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY), z:z};
  }else if(e.touches.length===1 && z>1){
   pan0={x:e.touches[0].clientX-x, y:e.touches[0].clientY-y};
  }
 }, {passive:true});
 box.addEventListener('touchmove', function(e){
  if(e.touches.length===2 && pinch0){
   e.preventDefault();
   const a=e.touches[0], b=e.touches[1];
   const d=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);
   z=pinch0.z*(d/Math.max(1,pinch0.d));
   apply();
  }else if(e.touches.length===1 && pan0 && z>1){
   x=e.touches[0].clientX-pan0.x;
   y=e.touches[0].clientY-pan0.y;
   apply();
  }
 }, {passive:false});
 box.addEventListener('touchend', function(){ pinch0=null; pan0=null; });
 let drag=null;
 box.addEventListener('pointerdown', function(e){
  if(e.pointerType==='touch') return;
  if(z<=1) return;
  if(e.target.closest && e.target.closest('.rpp-close')) return;
  e.preventDefault();
  drag={x:e.clientX-x, y:e.clientY-y};
  box.setPointerCapture(e.pointerId);
  box.style.cursor='grabbing';
 });
 box.addEventListener('pointermove', function(e){
  if(!drag) return;
  x=e.clientX-drag.x;
  y=e.clientY-drag.y;
  apply();
 });
 box.addEventListener('pointerup', function(){ drag=null; box.style.cursor=z>1?'grab':''; });
 box.addEventListener('pointercancel', function(){ drag=null; });
}

function setRppMediasModo(modo){
 relatorioPsrPseState.mediasModo=modo;
 carregarRespostasRelatorioPsrPse();
}
function setRppMediasDe(v){ relatorioPsrPseState.mediasDe=v; if(relatorioPsrPseState.mediasModo==='periodo') carregarRespostasRelatorioPsrPse(); }
function setRppMediasAte(v){ relatorioPsrPseState.mediasAte=v; if(relatorioPsrPseState.mediasModo==='periodo') carregarRespostasRelatorioPsrPse(); }
function rppMediaCategoria(catId,dias,modo,iso){
 if(relatorioPsrPseState.tipo==='pse'){
  if(modo==='diaria')return {linha:rppMediaCatDia(catId,iso,'linha'),goleiros:rppMediaCatDia(catId,iso,'goleiros')};
  return {linha:rppMediaCatPeriodo(catId,dias,'linha'),goleiros:rppMediaCatPeriodo(catId,dias,'goleiros')};
 }
 return modo==='diaria'?rppMediaCatDia(catId,iso):rppMediaCatPeriodo(catId,dias);
}
function rppRenderMedias(){
 const modo=relatorioPsrPseState.mediasModo||'diaria';
 const periodo=rppPeriodoAtual();
 const cats=rppCatIds();
 const filtros=`<div class="rpp-med-filtros rpp-no-print">
  <button type="button" class="${modo==='diaria'?'active':''}" onclick="setRppMediasModo('diaria')">Diária</button>
  <button type="button" class="${modo==='semanal'?'active':''}" onclick="setRppMediasModo('semanal')">Semanal</button>
  <button type="button" class="${modo==='mensal'?'active':''}" onclick="setRppMediasModo('mensal')">Mensal</button>
  <button type="button" class="${modo==='periodo'?'active':''}" onclick="setRppMediasModo('periodo')">Período</button>
  ${modo==='periodo'?`<label>De <input type="date" value="${relatorioPsrPseState.mediasDe||relatorioPsrPseState.data}" onchange="setRppMediasDe(this.value)"></label><label>Até <input type="date" value="${relatorioPsrPseState.mediasAte||relatorioPsrPseState.data}" onchange="setRppMediasAte(this.value)"></label>`:''}
 </div><p class="rpp-med-nota rpp-no-print">Quem não respondeu não entra na média. Todas as categorias, independente do filtro acima.</p>`;
 if(modo==='diaria'){
  const dia=relatorioPsrPseState.data;
  const map={}; cats.forEach(id=>map[id]=rppMediaCategoria(id,[dia],'diaria',dia));
  return filtros+rppMediasTabela([{label:'Data '+rppBR(dia,true), map}]);
 }
 const mapG={}; cats.forEach(id=>mapG[id]=rppMediaCategoria(id,periodo.dias,'periodo'));
 const tit=modo==='semanal'?'Média geral da semana':modo==='mensal'?'Média geral do mês':'Média geral do período';
 const rows=[{label:tit, map:mapG, geral:true}].concat(periodo.dias.map(iso=>{
  const map={}; cats.forEach(id=>map[id]=rppMediaCategoria(id,[iso],'diaria',iso));
  return {label:rppNomeDia(iso)+' '+rppBR(iso,true), map};
 }));
 return filtros+rppMediasTabela(rows);
}

function renderRelatorioPsrPse(){
 const modal=document.getElementById('relatorio-psrpse-modal');if(!modal)return;
 const cats=rppCats();const atletas=rppAtletasRelatorio();
 const tabela=relatorioPsrPseState.carregando?'<div class="rpp-loading">Carregando respostas...</div>':(relatorioPsrPseState.view==='medias'?rppRenderMedias():(relatorioPsrPseState.view==='notas'?rppRenderTabelaNotas(atletas):rppRenderTabelaResumo(atletas)));
 const dataBR=rppBR(relatorioPsrPseState.data,true);
 modal.innerHTML=`<div class="rpp-card"><button class="rpp-close" onclick="closeRelatorioPsrPse()">×</button><div class="rpp-head"><div class="rpp-extra-box"><div class="rpp-extra-chips">${rppRenderExtrasChips()}</div></div><div class="rpp-title"><h2>${relatorioPsrPseState.tipo.toUpperCase()}</h2><strong>${dataBR}</strong><small>${rppTituloView()}</small></div><div class="rpp-cat-box">${Object.keys(cats).map(id=>`<label><input type="checkbox" ${relatorioPsrPseState.categorias[id]?'checked':''} onchange="toggleRelatorioPsrPseCategoria('${id}',this.checked)"> ${rppEscape(cats[id].label)}</label>`).join('')}</div></div><div class="rpp-toolbar"><label>Dia <input type="date" value="${relatorioPsrPseState.data}" onchange="setRelatorioPsrPseData(this.value)"></label><button type="button" class="${relatorioPsrPseState.view==='notas'?'active':''}" onclick="setRelatorioPsrPseView('notas')">Notas do dia</button><button type="button" class="${relatorioPsrPseState.view==='diario'?'active':''}" onclick="setRelatorioPsrPseView('diario')">Relatório diário</button><button type="button" class="${relatorioPsrPseState.view==='semanal'?'active':''}" onclick="setRelatorioPsrPseView('semanal')">Relatório semanal</button><button type="button" class="${relatorioPsrPseState.view==='mensal'?'active':''}" onclick="setRelatorioPsrPseView('mensal')">Relatório mensal</button><button type="button" class="${relatorioPsrPseState.view==='medias'?'active':''}" onclick="setRelatorioPsrPseView('medias')">Médias</button><button type="button" class="print" onclick="imprimirRelatorioPsrPse()"><i class="fa-solid fa-print"></i> Imprimir/Exportar</button></div><div class="rpp-meta${relatorioPsrPseState.view==='medias'?' rpp-no-print':''}"><span>${relatorioPsrPseState.view==='medias'?'Todas as categorias':rppEscape(rppCategoriasTitulo())}</span><span>${relatorioPsrPseState.view==='medias'?'':atletas.length+' atleta(s)'}</span></div><div id="rpp-print-area" class="rpp-print-area"><div class="rpp-print-title"><img src="logo.png"><div><h2>${rppEscape(rppTituloView())}</h2><p>${relatorioPsrPseState.view==='medias'?'Todas as categorias':rppEscape(rppCategoriasTitulo())}</p></div><img src="logo.png"></div>${relatorioPsrPseState.tipo==='pse'?`<div class="rpp-legenda-pse"><span><b>1–2</b> leve</span><span><b>3–4</b> médio</span><span><b>5–6</b> pesado</span><span><b>7</b> esforço máximo</span></div>`:''}<div class="rpp-table-wrap">${tabela}</div></div></div>`;
 modal.style.display='flex';
}
let rppRespCache={inicio:'',fim:'',rows:[]};
let rppLoadRequest=0;
function rppIndexarRespostas(rows){
 const idx=new Map();
 (rows||[]).forEach(function(r){
  const rd=rppIsoData(r.data);
  const rn=normalizarTextoTrabalho(r.nome_completo||r.nomeCompleto||'');
  const rnas=rppNormNasc(r.nascimento||r.data_nascimento||'');
  const k1=rd+'|'+rn;
  if(!idx.has(k1)) idx.set(k1,r);
  if(rnas) idx.set(rd+'|'+rn+'|'+rnas, r);
 });
 relatorioPsrPseState.respIdx=idx;
}
async function rppFetchRespostasPeriodo(inicio,fim){
 if(rppRespCache.rows.length && rppRespCache.inicio<=inicio && rppRespCache.fim>=fim){
  return rppRespCache.rows.filter(function(r){
   const d=rppIsoData(r.data);
   return d>=inicio && d<=fim;
  });
 }
 const page=1000;
 let from=0, all=[];
 const cols='data,nome_completo,nascimento,psr,pse';
 while(true){
  const {data,error}=await _supabase.from('portal_respostas_diarias').select(cols).gte('data',inicio).lte('data',fim).order('data',{ascending:true}).range(from, from+page-1);
  if(error) throw error;
  const chunk=data||[];
  all=all.concat(chunk);
  if(chunk.length<page) break;
  from+=page;
  if(from>30000) break;
 }
 rppRespCache={inicio:inicio,fim:fim,rows:all};
 return all;
}
async function carregarRespostasRelatorioPsrPse(){
 const request=++rppLoadRequest;
 if(!await aeExigir()){if(request===rppLoadRequest){relatorioPsrPseState.carregando=false;renderRelatorioPsrPse();}return;}
 if(request!==rppLoadRequest)return;
 const periodo=rppPeriodoAtual(),tipo=relatorioPsrPseState.tipo;
 relatorioPsrPseState.carregando=true;renderRelatorioPsrPse();
 try{
  const [respostas,anulacoes]=await Promise.all([
   rppFetchRespostasPeriodo(periodo.inicio,periodo.fim),
   tipo==='pse'?rppFetchAnulacoesPse(periodo.inicio,periodo.fim):Promise.resolve(new Map())
  ]);
  if(request!==rppLoadRequest)return;
  relatorioPsrPseState.respostas=respostas;
  relatorioPsrPseState.avdPseAnulacoes=anulacoes;
  rppIndexarRespostas(respostas);
 }catch(e){
  if(request!==rppLoadRequest)return;
  console.error(e);
  if(tipo==='pse'&&rppColunaAnularPseAusente(e))alert('A regra ANULAR PSE ainda não foi instalada no Supabase. Execute o arquivo SQL de instalação desta atualização e recarregue o Sistema.');
  else alert('Erro ao carregar respostas PSR/PSE. Verifique as tabelas portal_respostas_diarias e avaliacao_diaria_notas no Supabase.');
  relatorioPsrPseState.respostas=[];relatorioPsrPseState.respIdx=new Map();relatorioPsrPseState.avdPseAnulacoes=new Map();
 }
 finally{if(request===rppLoadRequest){relatorioPsrPseState.carregando=false;renderRelatorioPsrPse();}}
}
async function openRelatorioPsrPse(tipo){
 if(!await aeExigir())return;
 relatorioPsrPseState={tipo:tipo==='pse'?'pse':'psr',data:rppDataPadrao(),view:'notas',sort:{key:'nome',dir:'asc'},categorias:rppDefaultCategorias(),respostas:[],carregando:false};
 let modal=document.getElementById('relatorio-psrpse-modal');
 if(!modal){modal=document.createElement('div');modal.id='relatorio-psrpse-modal';modal.className='rpp-overlay';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeRelatorioPsrPse();});}
 modal.style.display='flex';renderRelatorioPsrPse();await carregarRespostasRelatorioPsrPse();
}
function closeRelatorioPsrPse(){rppLoadRequest++;const modal=document.getElementById('relatorio-psrpse-modal');if(modal)modal.style.display='none';}
function setRelatorioPsrPseData(valor){relatorioPsrPseState.data=rppAjustarFimSemanaParaSexta(valor||rppDataPadrao());carregarRespostasRelatorioPsrPse();}
function setRelatorioPsrPseView(view){relatorioPsrPseState.view=view;relatorioPsrPseState.sort=rppDefaultSortParaView(view,relatorioPsrPseState.tipo);carregarRespostasRelatorioPsrPse();}
function toggleRelatorioPsrPseCategoria(catId,checked){relatorioPsrPseState.categorias[catId]=!!checked;renderRelatorioPsrPse();}
function sortRelatorioPsrPse(key){
 const atual=relatorioPsrPseState.sort||{key:'nome',dir:'asc'};
 if(atual.key===key)relatorioPsrPseState.sort={key,dir:atual.dir==='asc'?'desc':'asc'};
 else{
  const descPadrao=['sono','fadiga','dor_muscular','estresse_mental','motivacao','pse_valor','descricao','respondeu','total'].includes(key)||key.startsWith('dia:');
  relatorioPsrPseState.sort={key,dir:descPadrao?'desc':'asc'};
 }
 renderRelatorioPsrPse();
}
