 if(f.squadOn&&typeof f.squadOn==='object')tpState.squadOn=JSON.parse(JSON.stringify(f.squadOn));
 if(Number.isFinite(parseInt(f.homeN,10)))tpState.homeN=Math.max(1,parseInt(f.homeN,10));
