function tpFillToken(ctx,r,p,t){
 const isGk=t==='gk-home'||t==='gk-away',c1=p.c1||(t==='home'?'#d63031':t==='away'?'#0984e3':t==='gk-home'?'#f9c614':'#111'),c2=p.c2||'#fff',st=p.kitStyle||'solid';
 ctx.save();ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.clip();
 if(st==='solid'||isGk){ctx.fillStyle=c1;ctx.fillRect(-r,-r,r*2,r*2);}
 else if(st==='halves'){ctx.fillStyle=c1;ctx.fillRect(-r,-r,r,r*2);ctx.fillStyle=c2;ctx.fillRect(0,-r,r,r*2);}
 else{const vert=st!=='hoops',step=Math.max(3,r/3);for(let i=-r;i<r;i+=step){ctx.fillStyle=(Math.floor((i+r)/step)%2===0)?c1:c2;if(st==='diag'){ctx.save();ctx.rotate(Math.PI/4);ctx.fillRect(i,-r*2,step,r*4);ctx.restore();}else if(vert)ctx.fillRect(i,-r,step,r*2);else ctx.fillRect(-r,i,r*2,step);}}
 ctx.restore();ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.strokeStyle='#fff';ctx.lineWidth=Math.max(1.2,r*0.12);ctx.stroke();
 const lab=p.showNum!==false?String(p.label==null?'':p.label):'';
 if(lab){ctx.fillStyle=t==='gk-home'?'#111':'#fff';ctx.font='bold '+Math.max(8,r*0.9)+'px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(lab.slice(0,3),0,1);}
 const name=p.showName!==false?String(p.name==null?'':p.name).trim():'';
 if(name){const y=p.namePos==='above'?-r-8:r+8;ctx.font='bold '+Math.max(8,r*0.78)+'px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.strokeStyle='#111';ctx.lineWidth=2.5;ctx.strokeText(name,0,y);ctx.fillStyle='#fff';ctx.fillText(name,0,y);}
 }
function tpDrawStyledGoal(ctx,pw,ph,p){
 const style=p.goalStyle||'official';
 ctx.save();
 if(style==='cones'){
  for(let i=0;i<4;i++){
   const x=-pw*.36+i*(pw*.24),h=ph*.8,w=h*.42;
   ctx.fillStyle='rgba(0,0,0,.18)';ctx.beginPath();ctx.ellipse(x,h*.39,w*.34,h*.08,0,0,Math.PI*2);ctx.fill();
   ctx.fillStyle='#f39c12';ctx.strokeStyle='#c0392b';ctx.lineWidth=Math.max(1,pw*.025);ctx.beginPath();ctx.moveTo(x-w*.28,h*.38);ctx.lineTo(x-w*.1,-h*.42);ctx.quadraticCurveTo(x,-h*.52,x+w*.1,-h*.42);ctx.lineTo(x+w*.28,h*.38);ctx.closePath();ctx.fill();ctx.stroke();
  }
  ctx.restore();return;
 }
 const x=-pw/2,y=-ph/2,post=Math.max(2,pw*.055),bar=Math.max(2,ph*.14);
 ctx.fillStyle='rgba(0,0,0,.2)';ctx.beginPath();ctx.ellipse(0,ph*.42,pw*.44,Math.max(1,ph*.06),0,0,Math.PI*2);ctx.fill();
 ctx.fillStyle='#f7f8fa';ctx.strokeStyle='#434c56';ctx.lineWidth=Math.max(1,pw*.012);
 ctx.fillRect(x,y,post,ph);ctx.strokeRect(x,y,post,ph);ctx.fillRect(x+pw-post,y,post,ph);ctx.strokeRect(x+pw-post,y,post,ph);ctx.fillRect(x,y,pw,bar);ctx.strokeRect(x,y,pw,bar);
 if(p.fullGoal!==false){ctx.strokeStyle='rgba(220,230,235,.9)';ctx.lineWidth=Math.max(1,pw*.008);const innerX=x+post,innerW=pw-2*post,innerY=y+bar,innerH=ph-bar;for(let i=1;i<=3;i++){const yy=innerY+innerH*i/4;ctx.beginPath();ctx.moveTo(innerX,yy);ctx.lineTo(innerX+innerW,yy);ctx.stroke();}for(let i=1;i<=4;i++){const xx=innerX+innerW*i/5;ctx.beginPath();ctx.moveTo(xx,innerY);ctx.lineTo(xx,innerY+innerH);ctx.stroke();}}
 ctx.restore();
}
function tpDrawPieces(ctx,W,H,pieces){
 const source=(pieces||[]).filter(Boolean);
 const explicitOrder=source.length>0&&source.every(p=>Number.isFinite(Number(p.layerOrder)));
 const drawList=explicitOrder?source.slice().sort((a,b)=>Number(a.layerOrder)-Number(b.layerOrder)):source;
 drawList.forEach(p=>{
  if(!p)return;const x=(Number(p.x)||0)/100*W,y=(Number(p.y)||0)/100*H,pw=(Number(p.w)||6)/100*W,ph=(Number(p.h)||6)/100*H;
  if(p.type==='arrow'){
   ctx.save();ctx.translate(x,y);ctx.rotate((Number(p.rot)||0)*Math.PI/180);const len=Math.max(12,pw),color=tpPieceColor(p);
   if(p.meaning==null&&p.lineStyle==null&&p.thickness==null&&p.doubleEnded==null){
    ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=2;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-len/2,0);ctx.lineTo(len/2-6,0);ctx.stroke();
    ctx.beginPath();ctx.moveTo(len/2,0);ctx.lineTo(len/2-6,-3);ctx.lineTo(len/2-6,3);ctx.closePath();ctx.fill();ctx.restore();return;
   }
   const width=tpClampNumber(p.thickness,1,12,2);ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=width;ctx.lineCap='round';
   const style=p.lineStyle||((p.stroke==='dash')?'dashed':'solid');ctx.setLineDash(style==='dashed'?[10,7]:style==='dotted'?[1,Math.max(4,width*2.2)]:[]);
   ctx.beginPath();ctx.moveTo(-len/2+6,0);ctx.lineTo(len/2-6,0);ctx.stroke();ctx.setLineDash([]);
   const headLen=Math.max(4,width*1.25),headHalf=Math.max(2,width*.65);
   const head=(dir)=>{ctx.beginPath();ctx.moveTo(dir*(len/2-1),0);ctx.lineTo(dir*(len/2-headLen),-headHalf);ctx.lineTo(dir*(len/2-headLen),headHalf);ctx.closePath();ctx.fill();};head(1);if(p.doubleEnded)head(-1);ctx.restore();return;
  }
  if(p.type==='square'||p.type==='circle'){
   ctx.save();ctx.translate(x,y);ctx.rotate((Number(p.rot)||0)*Math.PI/180);const color=tpPieceColor(p),width=tpClampNumber(p.thickness,1,12,2),style=p.strokeStyle||((p.stroke==='dash')?'dashed':'solid');
   if(p.fillMode==='color'&&Number(p.fillOpacity)>0){ctx.globalAlpha=tpClampNumber(p.fillOpacity,0,100,0)/100;ctx.fillStyle=tpSafeColor(p.fillColor,'#2e9d62');if(p.type==='circle'){ctx.beginPath();ctx.ellipse(0,0,pw/2,ph/2,0,0,Math.PI*2);ctx.fill();}else ctx.fillRect(-pw/2,-ph/2,pw,ph);ctx.globalAlpha=1;}
   ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(style==='dashed'?[9,6]:style==='dotted'?[1,Math.max(3,width*2.2)]:[]);if(p.type==='circle'){ctx.beginPath();ctx.ellipse(0,0,pw/2,ph/2,0,0,Math.PI*2);ctx.stroke();}else ctx.strokeRect(-pw/2,-ph/2,pw,ph);ctx.setLineDash([]);ctx.restore();return;
  }
  if(p.type==='text'){
   ctx.save();ctx.translate(x,y);ctx.rotate((Number(p.rot)||0)*Math.PI/180);ctx.fillStyle=tpPieceColor(p);const base=tpClampNumber(p.fontSize,8,64,18),scale=Math.max(.6,Math.min(2.2,W/720)),fs=base*scale;ctx.font='bold '+fs+'px Arial';ctx.textAlign='center';ctx.textBaseline='middle';const lines=String(p.text==null?'Texto':p.text).slice(0,80).split('\n'),lh=fs*1.15,startY=-(lines.length-1)*lh/2;lines.forEach((line,i)=>ctx.fillText(line,0,startY+i*lh));ctx.restore();return;
  }
  if(p.type==='goal'){
   if(p.goalStyle==null&&p.fullGoal==null){
    ctx.save();ctx.translate(x,y);if(p.rot)ctx.rotate(p.rot*Math.PI/180);const gw=Math.max(14,pw),gh=Math.max(16,ph);
    ctx.strokeStyle='rgba(255,255,255,.55)';ctx.lineWidth=1;for(let i=1;i<4;i++){const yy=-gh/2+(gh/4)*i;ctx.beginPath();ctx.moveTo(-gw/2,yy);ctx.lineTo(gw/2,yy);ctx.stroke();}for(let i=1;i<4;i++){const xx=-gw/2+(gw/4)*i;ctx.beginPath();ctx.moveTo(xx,-gh/2);ctx.lineTo(xx,gh/2);ctx.stroke();}ctx.strokeStyle='#fff';ctx.lineWidth=2.5;ctx.strokeRect(-gw/2,-gh/2,gw,gh);ctx.restore();return;
   }
   ctx.save();ctx.translate(x,y);ctx.rotate((Number(p.rot)||0)*Math.PI/180);tpDrawStyledGoal(ctx,Math.max(12,pw),Math.max(12,ph),p);ctx.restore();return;
  }
  if(p.type==='cone'){
   ctx.save();ctx.translate(x,y);ctx.rotate((Number(p.rot)||0)*Math.PI/180);const ch=Math.max(16,ph),cw=ch*.52;ctx.fillStyle='rgba(0,0,0,.22)';ctx.beginPath();ctx.ellipse(0,ch*.42,cw*.28,ch*.06,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f39c12';ctx.strokeStyle='#c0392b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-cw*.28,ch*.38);ctx.lineTo(-cw*.08,-ch*.42);ctx.quadraticCurveTo(0,-ch*.5,cw*.08,-ch*.42);ctx.lineTo(cw*.28,ch*.38);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.fillRect(-cw*.2,ch*.04,cw*.4,ch*.1);ctx.fillRect(-cw*.14,-ch*.18,cw*.28,ch*.09);ctx.fillStyle='#e67e22';ctx.fillRect(-cw*.3,ch*.32,cw*.6,ch*.1);ctx.restore();return;
  }
  if(p.type==='ball'){
   ctx.save();ctx.translate(x,y);ctx.rotate((Number(p.rot)||0)*Math.PI/180);const r=Math.max(6,Math.min(W,H)*.012);ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fillStyle='#f4f4f4';ctx.fill();ctx.strokeStyle='#111';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#111';ctx.beginPath();ctx.moveTo(0,-r*.5);ctx.lineTo(r*.4,-r*.18);ctx.lineTo(r*.25,r*.25);ctx.lineTo(-r*.25,r*.25);ctx.lineTo(-r*.4,-r*.18);ctx.closePath();ctx.fill();ctx.restore();return;
  }
  if(['home','away','gk-home','gk-away'].includes(p.type)){
   const base=Math.max(7,Math.min(W,H)*.0135),factor=({P:.76,M:1,G:1.34})[p.size||'M']||1,r=base*factor;ctx.save();ctx.translate(x,y);ctx.rotate((Number(p.rot)||0)*Math.PI/180);tpFillToken(ctx,r,p,p.type);ctx.restore();
  }
 });
}
function tpDrawPiecesOn(ctx,W,H){tpDrawPieces(ctx,W,H,(tpState&&tpState.pieces)||[]);}
function tpMixPieces(a,b,t){
 const mapB=new Map((b||[]).map(p=>[p.id,p])),out=[];
 (a||[]).forEach(pa=>{const pb=mapB.get(pa.id);if(!pb){out.push(JSON.parse(JSON.stringify(pa)));return;}const merged=Object.assign({},JSON.parse(JSON.stringify(pa)),JSON.parse(JSON.stringify(pb)));merged.id=pa.id;merged.type=pb.type||pa.type;merged.x=tpLerp(Number(pa.x)||0,Number(pb.x)||0,t);merged.y=tpLerp(Number(pa.y)||0,Number(pb.y)||0,t);merged.w=tpLerp(Number(pa.w)||0,Number(pb.w)||0,t);merged.h=tpLerp(Number(pa.h)||0,Number(pb.h)||0,t);merged.rot=tpLerp(Number(pa.rot)||0,Number(pb.rot)||0,t);out.push(merged);});
 (b||[]).forEach(pb=>{if(!(a||[]).some(pa=>pa.id===pb.id))out.push(JSON.parse(JSON.stringify(pb)));});return out;
}
async function tpCarregarProjeto(nome){
 const {data,error}=await _supabase.from('prancheta_projetos').select('dados').eq('nome',nome).single();
 if(error||!data){alert('Não carregou o projeto.');return;}
 const d=data.dados||{};
 tpState.pieces=Array.isArray(d.pieces)?JSON.parse(JSON.stringify(d.pieces)):[];
 tpState.frames=Array.isArray(d.frames)?JSON.parse(JSON.stringify(d.frames)):[];
 tpState.nextId=Math.max(1,parseInt(d.nextId,10)||1);
 tpState.homeN=Math.max(1,parseInt(d.homeN,10)||1);tpState.awayN=Math.max(1,parseInt(d.awayN,10)||1);
 tpState.kit=d.kit&&typeof d.kit==='object'?JSON.parse(JSON.stringify(d.kit)):null;
 tpState.squadOn=d.squadOn&&typeof d.squadOn==='object'?JSON.parse(JSON.stringify(d.squadOn)):{home:false,away:false};
 tpState.sel=null;tpState.selIds=[];tpUndo=[];
 const sel=document.getElementById('mini-tactical-system');if(sel&&d.sistema)sel.value=d.sistema;
 tpKitEnsure();tpRenderPieces();tpRenderFrames();tpPaintKitDiscs();if(typeof tpRenderSquad==='function')tpRenderSquad();
 tpFecharProjUI();
 /* Abrir projeto antigo só restaura em memória; não grava nem migra automaticamente. */
}

/* ATLETAS — categorias do registro configurado no Principal. */
function atletasEscaparHtml(value){
 return String(value==null?'':value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));
}
function atletasCategoriasConfiguradas(){
 return (typeof AE!=='undefined'&&AE&&AE.categorias&&typeof AE.categorias==='object')?AE.categorias:{};
}
function atletasObterAnosSelecionados(){return Array.from(document.querySelectorAll('.year-chk:checked')).map(el=>String(el.value));}
function atletasConjuntosIguais(a,b){const x=[...new Set((a||[]).map(String))].sort(),y=[...new Set((b||[]).map(String))].sort();return x.length===y.length&&x.every((v,i)=>v===y[i]);}
function atletasCategoriaExataDosAnos(anos){
 if(!anos||!anos.length)return null;
 const cats=atletasCategoriasConfiguradas();
 for(const [id,cat] of Object.entries(cats)){if(atletasConjuntosIguais(anos,cat.anos||[]))return{id,label:cat.label||id,anos:(cat.anos||[]).map(String)};}
 return null;
}
function atletasAtualizarSelectCategoria(){
 const select=document.getElementById('atletas-categoria-filter');if(!select)return;
 const cats=atletasCategoriasConfiguradas(),signature=JSON.stringify(Object.entries(cats).map(([id,c])=>[id,c.label,c.anos]));
 if(select.dataset.signature!==signature){
  const old=select.value;select.innerHTML='<option value="">Todas</option>'+Object.entries(cats).map(([id,c])=>'<option value="'+atletasEscaparHtml(id)+'">'+atletasEscaparHtml(c.label||id)+'</option>').join('')+'<option value="__manual__">Seleção manual</option>';
  select.dataset.signature=signature;if(old&&Array.from(select.options).some(o=>o.value===old))select.value=old;
 }
 const exact=atletasCategoriaExataDosAnos(atletasObterAnosSelecionados());
 if(exact)select.value=exact.id;
 else if(atletasObterAnosSelecionados().length)select.value='__manual__';
 else select.value='';
}
function atletasCategoriaSelecionada(id){
 const checks=Array.from(document.querySelectorAll('.year-chk'));
 if(id==='')checks.forEach(c=>c.checked=false);
 else if(id!=='__manual__'){
  const cat=atletasCategoriasConfiguradas()[id];if(cat)checks.forEach(c=>c.checked=(cat.anos||[]).map(String).includes(String(c.value)));
 }
 atletasAtualizarSelectCategoria();renderAtletasScreen();
}
function atletasAnosManuaisAlterados(){atletasAtualizarSelectCategoria();renderAtletasScreen();}
function atletasIndicesFiltradosPeloFiltroAtual(){
 const anos=atletasObterAnosSelecionados();
 return (excelData||[]).map((row,index)=>({row,index})).filter(({row})=>{
  const key=Object.keys(row||{}).find(k=>String(k).toLowerCase().trim()==='ano');const year=key?String(row[key]||'').trim():'';
  return !anos.length||anos.includes(year);
 }).map(x=>x.index);
}
function atletasNomeExibicao(row){
 const nickname=valorCampoAtleta(row,['APELIDO','apelido']);
 const full=valorCampoAtleta(row,['NOME COMPLETO','nome completo','nome']);
 return String(nickname||full||'Sem Nome').trim();
}
function renderAtletasScreen(){
 atletasAtualizarSelectCategoria();
 const selectedYears=atletasObterAnosSelecionados();
 const posLists={goleiros:document.getElementById('list-goleiros'),zagueiros:document.getElementById('list-zagueiros'),laterais:document.getElementById('list-laterais'),volantes:document.getElementById('list-volantes'),meias:document.getElementById('list-meias'),atacantes:document.getElementById('list-atacantes'),extremos:document.getElementById('list-extremos')};
 Object.values(posLists).forEach(el=>{if(el)el.innerHTML='';});
 (excelData||[]).forEach((row,globalIndex)=>{
  const yearKey=Object.keys(row||{}).find(k=>String(k).toLowerCase().trim()==='ano'),year=yearKey?String(row[yearKey]||'').trim():'';
  if(selectedYears.length&&!selectedYears.includes(year))return;
  const name=atletasNomeExibicao(row);
  const pos1=String(valorCampoAtleta(row,['Posição 1','posicao 1','posição','posicao'])||'').toLowerCase();
  const pos2=String(valorCampoAtleta(row,['Posição 2','posicao 2'])||'').toLowerCase();
  const pos=(pos1+' '+pos2).trim();
  let target='meias';
  if(pos.includes('goleiro'))target='goleiros';else if(pos.includes('zagueiro'))target='zagueiros';else if(pos.includes('lateral'))target='laterais';else if(pos.includes('volante'))target='volantes';else if(pos.includes('atacante'))target='atacantes';else if(pos.includes('extremo')||pos.includes('ponta'))target='extremos';
  const note=String(row.Anotacoes||valorCampoAtleta(row,['Anotacoes','Anotações'])||'').trim();
  const injuryKey=Object.keys(row||{}).find(k=>String(k).toLowerCase().trim()==='lesao'||String(k).toLowerCase().trim()==='lesão');
  const injured=injuryKey&&String(row[injuryKey]).toLowerCase().trim()==='sim';
  const redKey=Object.keys(row||{}).find(k=>String(k).toLowerCase().replace(/_/g,' ').replace(/\s+/g,' ').trim()==='cartao vermelho'||String(k).toLowerCase().replace(/_/g,'').replace(/\s+/g,'')==='cartaovermelho');
  const red=redKey&&String(row[redKey]).toLowerCase().trim()==='sim';
  const icons=(note?'<svg width="13" height="15" viewBox="0 0 24 24" fill="none" stroke="#555" stroke-width="2" style="display:inline-block;vertical-align:-2px;margin-left:8px" title="Atleta possui anotações"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" fill="#ccc"></rect><line x1="9" y1="12" x2="15" y2="12"></line></svg>':'')
   +(injured?'<span title="Atleta lesionado" style="color:#d63031;font-weight:900;margin-left:5px">✚</span>':'')
   +(red?'<span title="Cartão vermelho" style="display:inline-block;width:10px;height:14px;background:#d63031;border:1px solid #7a0000;border-radius:2px;margin-left:5px;vertical-align:-2px"></span>':'');
  const item=document.createElement('div');item.className='athlete-item'+(selectedAthleteIndex===globalIndex?' selected':'');item.draggable=true;item.dataset.atletaIndex=String(globalIndex);
  item.addEventListener('dragstart',event=>{event.dataTransfer.setData('text/plain',String(globalIndex));event.dataTransfer.effectAllowed='move';item.classList.add('arrastando-atleta');});
  item.addEventListener('dragend',()=>item.classList.remove('arrastando-atleta'));
  if(selectedAthleteIndex===globalIndex){item.style.backgroundColor='#0984e3';item.style.color='#fff';}
  item.innerHTML='<span>'+atletasEscaparHtml(name)+' '+icons+'</span><span>'+atletasEscaparHtml(year)+'</span>';
  item.onclick=()=>{selectedAthleteIndex=globalIndex;renderAtletasScreen();setTimeout(()=>mostrarCardAtletaSelecionado(globalIndex),0);};
  if(posLists[target])posLists[target].appendChild(item);
 });
 configurarDropAtletasPosicoes(posLists);
 if(selectedAthleteIndex!==null&&selectedAthleteIndex!==undefined)setTimeout(()=>mostrarCardAtletaSelecionado(selectedAthleteIndex),0);
 else esconderTooltipAtletaCadastro();
}
function atletasPosicoesPrincipais(){
 return [
  {label:'Goleiro',pos1:'Goleiro'},
  {label:'Lateral Dir.',pos1:'Lateral',pos2:'Lateral Dir.'},
  {label:'Lateral Esq.',pos1:'Lateral',pos2:'Lateral Esq.'},
  {label:'Zagueiro',pos1:'Zagueiro'},
  {label:'Volante',pos1:'Volante'},
  {label:'Meia',pos1:'Meia'},
  {label:'Atacante',pos1:'Atacante'},
  {label:'Ponta Dir.',pos1:'Extremo',pos2:'Ponta Dir.'},
  {label:'Ponta Esq.',pos1:'Extremo',pos2:'Ponta Esq.'}
 ];
}
function atletasPosicaoOpcoes(){return atletasPosicoesPrincipais();}
function atletasPosicaoKey(row,num){
 const wanted='posicao '+num;
 return Object.keys(row||{}).find(k=>String(k).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim()===wanted)||'Posição '+num;
}
function atletasOpcaoDaPosicao(valor){return atletasPosicoesPrincipais().find(o=>o.label===String(valor||''))||atletasPosicoesPrincipais().find(o=>o.label==='Meia');}
function atletasAplicarPosicaoEscolhida(row,opcao,isNew){
 if(!row||!opcao)return;
 const key1=atletasPosicaoKey(row,1),key2=atletasPosicaoKey(row,2);
 row[key1]=opcao.pos1;
 const current2=String(row[key2]||'').trim();
 if(opcao.pos2&&opcao.pos2!==opcao.pos1)row[key2]=opcao.pos2;
 else if(isNew)row[key2]='';
 else if(!current2)row[key2]='';
}
function aplicarNovaPosicaoAtleta(globalIndex,opcao){
 const row=excelData[globalIndex];if(!row||!opcao)return;
 garantirColunaAtleta('Posição 1');garantirColunaAtleta('Posição 2');
 atletasAplicarPosicaoEscolhida(row,opcao,false);selectedAthleteIndex=globalIndex;saveToStorage();renderAtletasScreen();
}
function abrirPopupPosicaoAtleta(globalIndex,grupo){
 const row=excelData[globalIndex];if(!row)return;
 const opcoes=atletasPosicaoOpcoes();const name=atletasNomeExibicao(row);
 let modal=document.getElementById('atleta-posicao-drop-modal');
 if(!modal){modal=document.createElement('div');modal.id='atleta-posicao-drop-modal';modal.className='atleta-posicao-drop-overlay';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)fecharPopupPosicaoAtleta();});}
 modal.innerHTML='<div class="atleta-posicao-drop-card"><button class="atleta-posicao-drop-close" onclick="fecharPopupPosicaoAtleta()" aria-label="Fechar">×</button><h3>Escolher posição</h3><p>'+atletasEscaparHtml(name)+' foi movido. Selecione uma das nove posições:</p><div class="atleta-posicao-drop-options">'+opcoes.map((op,i)=>'<button type="button" onclick="confirmarPopupPosicaoAtleta('+globalIndex+',\''+String(grupo||'meias').replace(/[^a-z0-9_-]/gi,'')+'\','+i+')">'+atletasEscaparHtml(op.label)+'</button>').join('')+'</div></div>';
 modal.style.display='flex';
}
function garantirOpcoesPosicaoAtletaModal(){
 const select=document.getElementById('add-posicao');if(!select)return;
 const previous=select.value;
 const options=atletasPosicoesPrincipais();
 select.innerHTML=options.map(o=>'<option value="'+atletasEscaparHtml(o.label)+'">'+atletasEscaparHtml(o.label)+'</option>').join('')+'<option value="__KEEP__">Manter posições atuais</option>';
 select.value=options.some(o=>o.label===previous)?previous:'Meia';
}
function atletasPosicaoEdicaoTexto(row){
 const p1=String(valorCampoAtleta(row,['Posição 1','posicao 1','posição','posicao'])||'').trim();
 const p2=String(valorCampoAtleta(row,['Posição 2','posicao 2'])||'').trim();
 return 'Manter posições atuais — Posição 1: '+(p1||'não informada')+'; Posição 2: '+(p2||'não informada');
}
function atletasPosicaoFormEditarManter(row){
 const select=document.getElementById('add-posicao');if(!select)return;
 const keep=select.querySelector('option[value="__KEEP__"]');if(keep)keep.textContent=atletasPosicaoEdicaoTexto(row);
 select.value='__KEEP__';
}
function abrirMapaCategoriaAtletas(){
 const anos=atletasObterAnosSelecionados(),exact=atletasCategoriaExataDosAnos(anos);
 const filterLabel=!anos.length?'Todas as categorias':(exact?exact.label:'Seleção manual — anos '+anos.slice().sort().join(', '));
 const indices=atletasIndicesFiltradosPeloFiltroAtual();
 const ids=['goleiro','lateral-esq','zagueiro','lateral-dir','volante','meia','ponta-esq','atacante','ponta-dir','outros'];
 const buckets=Object.fromEntries(ids.map(id=>[id,[]]));
 indices.forEach(i=>{const row=excelData[i]||{},yearKey=Object.keys(row).find(k=>String(k).toLowerCase().trim()==='ano'),year=yearKey?String(row[yearKey]||'').trim():'';const pos=atletasMapearPosicao(row);const item={name:atletasNomeExibicao(row),full:String(valorCampoAtleta(row,['NOME COMPLETO','nome completo','nome'])||'').trim(),year,index:i};buckets[pos||'outros']?.push(item);});
 const collator=new Intl.Collator('pt-BR',{sensitivity:'base'});
 Object.values(buckets).forEach(list=>list.sort((a,b)=>{const ya=Number(a.year)||Infinity,yb=Number(b.year)||Infinity;return ya-yb||collator.compare(a.name,b.name)||collator.compare(a.full,b.full);}));
 const labels={'goleiro':'Goleiro','lateral-esq':'Lateral Esq.','zagueiro':'Zagueiro','lateral-dir':'Lateral Dir.','volante':'Volante','meia':'Meia','ponta-esq':'Ponta Esq.','atacante':'Atacante','ponta-dir':'Ponta Dir.'};
 const fieldOrder=['ponta-esq','atacante','ponta-dir','lateral-esq','meia','lateral-dir','zagueiro','volante','goleiro'];
 const maxPositionCount=Math.max(0,...fieldOrder.map(id=>buckets[id].length)),denseMap=maxPositionCount>10;
 const card=(id)=>{const count=buckets[id].length,cols=count>14?3:count>4?2:1,font=count>20?7:count>10?8:9;return '<section class="atleta-mapa-pos '+id+'" style="--map-cols:'+cols+';--map-font:'+font+'px"><h3>'+labels[id]+' <small>('+count+')</small></h3><ul>'+buckets[id].map(a=>'<li title="'+atletasEscaparHtml(a.full||a.name)+'"><span>'+atletasEscaparHtml(a.name)+'</span><b>'+(a.year?atletasEscaparHtml(a.year):'Sem ano')+'</b></li>').join('')+'</ul></section>';};
 const otherHtml=buckets.outros.map(a=>{const r=excelData[a.index]||{},p1=String(valorCampoAtleta(r,['Posição 1','posicao 1','posição','posicao'])||'').trim(),p2=String(valorCampoAtleta(r,['Posição 2','posicao 2'])||'').trim(),description=[p1,p2].filter(Boolean).join(' / ')||'Posição não identificada';return '<li><span>'+atletasEscaparHtml(a.name)+'</span><b>'+(a.year?atletasEscaparHtml(a.year):'Sem ano')+'</b><small>'+atletasEscaparHtml(description)+'</small></li>';}).join('');
 const otherSection=buckets.outros.length?'<section class="atleta-mapa-outros"><h3>Outras posições/lado não informado <small>('+buckets.outros.length+')</small></h3><ul>'+otherHtml+'</ul></section>':'';
 let modal=document.getElementById('atletas-mapa-modal');
 if(!modal){modal=document.createElement('div');modal.id='atletas-mapa-modal';modal.className='atleta-mapa-overlay';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)fecharMapaCategoriaAtletas();});}
 modal.innerHTML='<div class="atleta-mapa-card"><header class="atleta-mapa-header"><img src="logo.png" alt="Logo do Sistema Principal" onerror="this.style.display=\'none\'"><div><h2>Mapa da categoria</h2><p>'+atletasEscaparHtml(filterLabel)+' · '+indices.length+' atletas</p></div><button type="button" onclick="fecharMapaCategoriaAtletas()" aria-label="Fechar mapa">×</button></header>'
  +'<div class="atleta-mapa-note">Distribuição por posição · ordenação por ano crescente e depois nome. Posições laterais sem lado informado e registros desconhecidos ficam em “Outras posições/lado não informado”.</div>'
  +'<div class="atleta-mapa-field'+(denseMap?' atleta-mapa-field-dense':'')+'"><img class="atleta-mapa-pitch-img" src="base_campo_relatorio.png" alt="Campo de futebol" onerror="this.classList.add(\'asset-missing\')">'
  +fieldOrder.map(card).join('')+(denseMap?otherSection:'')+'</div>'
  +(denseMap?'':otherSection)
  +'<footer class="atleta-mapa-footer"><span>Campo do anexo do PDF · sem marca d’água sobre o campo</span><img src="image-12.png" alt="Selo do mapa" onerror="this.style.display=\'none\'"></footer></div>';
 if(window.__atletasMapaBodyOverflow===undefined)window.__atletasMapaBodyOverflow=document.body.style.overflow||'';
 document.body.style.overflow='hidden';modal.style.display='flex';
}
function atletasMapearPosicao(row){
 const normalizar=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[._]/g,' ').replace(/\s+/g,' ');
 const p1=normalizar(valorCampoAtleta(row,['Posição 1','posicao 1','posição','posicao']));
 const p2=normalizar(valorCampoAtleta(row,['Posição 2','posicao 2']));
 const lado=txt=>/\b(dir|direito|direita)\b/.test(txt)?'dir':/\b(esq|esquerdo|esquerda)\b/.test(txt)?'esq':'';
 const classificar=(pos,contexto)=>{
  if(!pos)return null;
  if(pos.includes('goleiro'))return'goleiro';
  if(pos.includes('lateral')){const l=lado(contexto||pos);return l==='dir'?'lateral-dir':l==='esq'?'lateral-esq':'outros';}
  if(pos.includes('ponta')||pos.includes('extremo')){const l=lado(contexto||pos);return l==='dir'?'ponta-dir':l==='esq'?'ponta-esq':'outros';}
  if(pos.includes('zagueiro'))return'zagueiro';
  if(pos.includes('volante'))return'volante';
  if(pos.includes('meia'))return'meia';
  if(pos.includes('atacante')||pos.includes('centroavante'))return'atacante';
  return null;
 };
 if(p1){const primary=classificar(p1,p1+' '+p2);return primary||'outros';}
 if(p2){const secondary=classificar(p2,p2);return secondary||'outros';}
 return'outros';
}
