/* Correção visual solicitada: a troca por arraste volta ao fluxo anterior, por grupo de destino. */
function atletasPosicaoOpcoesArraste(grupo){
 const mapa={
  goleiros:[{label:'Goleiro',pos1:'Goleiro',pos2:'Goleiro'}],
  zagueiros:[{label:'Zagueiro',pos1:'Zagueiro',pos2:'Zagueiro'},{label:'Zagueiro Dir.',pos1:'Zagueiro',pos2:'Zagueiro Dir.'},{label:'Zagueiro Esq.',pos1:'Zagueiro',pos2:'Zagueiro Esq.'}],
  laterais:[{label:'Lateral Dir.',pos1:'Lateral',pos2:'Lateral Dir.'},{label:'Lateral Esq.',pos1:'Lateral',pos2:'Lateral Esq.'}],
  volantes:[{label:'Volante',pos1:'Volante',pos2:'Volante'},{label:'1º volante',pos1:'Volante',pos2:'1º volante'},{label:'2º volante',pos1:'Volante',pos2:'2º volante'}],
  meias:[{label:'Meia',pos1:'Meia',pos2:'Meia'},{label:'Meia central',pos1:'Meia',pos2:'Meia central'},{label:'Meia atacante',pos1:'Meia',pos2:'Meia atacante'}],
  atacantes:[{label:'Atacante',pos1:'Atacante',pos2:'Atacante'},{label:'Centroavante',pos1:'Atacante',pos2:'Centroavante'},{label:'Segundo atacante',pos1:'Atacante',pos2:'Segundo atacante'}],
  extremos:[{label:'Ponta Dir.',pos1:'Extremo',pos2:'Ponta Dir.'},{label:'Ponta Esq.',pos1:'Extremo',pos2:'Ponta Esq.'},{label:'Extremo',pos1:'Extremo',pos2:'Extremo'}]
 };
 return mapa[grupo]||mapa.meias;
}
