function atletasMapaAbrirExportacaoPrincipal(){
 if(!atletasMapaCategoriaSnapshotPrincipal)return;
 document.getElementById('atleta-mapa-export-modal')?.remove();
 const modal=document.createElement('div');modal.id='atleta-mapa-export-modal';modal.className='atleta-mapa-export-overlay';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-label','Salvar, exportar ou imprimir mapa');
 modal.innerHTML='<div class="atleta-mapa-export-card"><h2>Exportar ou imprimir</h2><p>O mapa será ajustado para uma folha A4 vertical.</p><div class="atleta-mapa-export-actions"><button type="button" data-action="export">Exportar PDF</button><button type="button" data-action="save">Salvar PDF</button><button type="button" data-action="print">Imprimir</button><button type="button" data-action="cancel">Cancelar</button></div><p class="atleta-mapa-export-status" aria-live="polite"></p></div>';
 document.body.appendChild(modal);
 modal.addEventListener('click',e=>{
  if(e.target===modal){modal.remove();return;}
  const action=e.target.closest('button')?.dataset.action;if(!action)return;
  if(action==='cancel'){modal.remove();return;}
  if(action==='print'){modal.remove();atletasMapaImprimirPrincipal();return;}
  if(action==='save'||action==='export')atletasMapaExportarPDFPrincipal(action,modal);
 });
 modal.addEventListener('keydown',e=>{if(e.key==='Escape'&&!atletasMapaExportandoPrincipal)modal.remove();});
 modal.querySelector('[data-action="export"]')?.focus();
}
function atletasMapaNomeArquivoPDFPrincipal(snapshot){
 const raw='Mapa da categoria - '+(snapshot?.filterLabel||'Todas as categorias');
 const safe=typeof prosolSanitizeFilename==='function'?prosolSanitizeFilename(raw):raw.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/gi,'_');
 return (safe||'Mapa_da_categoria')+'.pdf';
}
function atletasMapaBaixarBlobPrincipal(blob,nome){
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=nome;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
let atletasMapaPastaImagensLocalPrincipal=null,atletasMapaPastaPendentePrincipal=null;
function atletasMapaPdfAdapterArquivosPrincipal(fileList){
 const files=new Map();
 for(const file of Array.from(fileList||[])){
  const parts=String(file.webkitRelativePath||file.name||'').split('/').filter(Boolean);
  if(parts.length>1)parts.shift();
  if(parts.length)files.set(parts.join('/').toLowerCase(),file);
 }
 const make=prefix=>({
  getDirectoryHandle:async name=>make(prefix+String(name).toLowerCase()+'/'),
  getFileHandle:async name=>{
   const file=files.get((prefix+String(name).toLowerCase()).replace(/^\/+/,''));
   if(!file)throw new DOMException('Arquivo não encontrado na pasta selecionada.','NotFoundError');
   return {getFile:async()=>file};
  }
 });
 return make('');
}
function atletasMapaSelecionarPastaPrincipal(janela=window){
 if(atletasMapaPastaImagensLocalPrincipal)return Promise.resolve(atletasMapaPastaImagensLocalPrincipal);
 if(atletasMapaPastaPendentePrincipal)return atletasMapaPastaPendentePrincipal;
 atletasMapaPastaPendentePrincipal=new Promise((resolve,reject)=>{
  const d=janela.document,box=d.createElement('div');box.id='atleta-mapa-pasta-local-pdf';box.setAttribute('role','dialog');box.setAttribute('aria-label','Permitir leitura de imagens locais do Principal');
  box.style.cssText='position:fixed;inset:0;z-index:2147483647;background:#0009;display:flex;align-items:center;justify-content:center;padding:16px';
  const panel=d.createElement('div');panel.style.cssText='background:white;color:#173b59;padding:20px;border-radius:12px;max-width:470px;width:100%;font:15px/1.45 Arial,sans-serif;box-shadow:0 10px 35px #0005';
  const p=d.createElement('p');p.textContent='Para incluir o logo e outras imagens locais no PDF, escolha a pasta do Sistema Principal — a mesma que contém index.html e script.js. O acesso é somente para leitura; nada será enviado pela internet e nenhum arquivo será alterado.';panel.appendChild(p);
  const actions=d.createElement('div');actions.style.cssText='display:flex;gap:8px;flex-wrap:wrap;margin-top:12px';
  const choose=d.createElement('button');choose.type='button';choose.textContent='Escolher pasta do Principal';choose.style.cssText='padding:10px 12px;border:0;border-radius:7px;background:#58111a;color:#fff;font-weight:700;cursor:pointer';
  const fallback=d.createElement('button');fallback.type='button';fallback.textContent='Selecionar pasta por compatibilidade';fallback.style.cssText='display:none;padding:10px 12px;border:0;border-radius:7px;background:#173b59;color:#fff;font-weight:700;cursor:pointer';
  const cancel=d.createElement('button');cancel.type='button';cancel.textContent='Cancelar';cancel.style.cssText='padding:10px 12px;border:0;border-radius:7px;background:#e5edf0;color:#173b59;font-weight:700;cursor:pointer';
  actions.append(choose,fallback,cancel);panel.appendChild(actions);
  const note=d.createElement('small');note.style.cssText='display:block;margin-top:12px;color:#526779';note.textContent='Se preferir, é possível continuar sem imagens locais; nesse caso, o logo não aparecerá no PDF.';panel.appendChild(note);
  const omit=d.createElement('button');omit.type='button';omit.textContent='Gerar sem imagens locais';omit.style.cssText='margin-top:9px;padding:8px 10px;border:1px solid #cbd8de;border-radius:7px;background:#fff;color:#173b59;cursor:pointer';panel.appendChild(omit);
  const input=d.createElement('input');input.type='file';input.multiple=true;input.setAttribute('webkitdirectory','');input.setAttribute('directory','');input.style.cssText='position:absolute;width:1px;height:1px;opacity:0;pointer-events:none';d.body.appendChild(input);
  box.appendChild(panel);d.body.appendChild(box);
  const cleanup=()=>{box.remove();input.remove();};
  const finish=(handle,error)=>{cleanup();if(error)reject(error);else resolve(handle);};
  cancel.onclick=()=>finish(null,new DOMException('Seleção de pasta cancelada.','AbortError'));
  omit.onclick=()=>finish(null,null);
  const useFileInput=()=>{input.value='';input.click();};
  input.addEventListener('change',async()=>{
   if(!input.files?.length)return;
   try{
    const handle=atletasMapaPdfAdapterArquivosPrincipal(input.files);
    await handle.getFileHandle('index.html');await handle.getFileHandle('script.js');
    atletasMapaPastaImagensLocalPrincipal=handle;finish(handle,null);
   }catch(e){p.textContent='A pasta selecionada não contém index.html e script.js na raiz. Escolha a pasta exata do Sistema Principal. '+(e?.message||'');}
  });
  input.addEventListener('cancel',()=>{});
  choose.onclick=async()=>{
   if(typeof janela.showDirectoryPicker!=='function'){useFileInput();return;}
   try{
    const dir=await janela.showDirectoryPicker({mode:'read'});
    await dir.getFileHandle('index.html');await dir.getFileHandle('script.js');
    atletasMapaPastaImagensLocalPrincipal=dir;finish(dir,null);
   }catch(e){
    if(e?.name==='AbortError')return;
    p.textContent='Não foi possível autorizar essa pasta. Você pode tentar a seleção compatível; escolha a pasta que contém index.html e script.js. '+(e?.message||'');fallback.style.display='inline-block';
   }
  };
  fallback.onclick=useFileInput;
  choose.focus();
 }).finally(()=>{atletasMapaPastaPendentePrincipal=null;});
 return atletasMapaPastaPendentePrincipal;
}
async function atletasMapaPrepararImagensLocaisPrincipal(root,original=root,janela=window){
 if(!root)return ()=>{};
 const doc=root.ownerDocument||document,view=doc.defaultView||window,base=new URL('.',doc.baseURI||document.baseURI);
 const images=[...(root.matches?.('img')?[root]:[]),...root.querySelectorAll('img')],restore=[];
 if(janela.location.protocol!=='file:')return ()=>{};
 const pairs=[];
 for(const img of images){
  const raw=img.getAttribute('src')||'';let url;try{url=new URL(raw,doc.baseURI||document.baseURI);}catch(_){continue;}
  if(raw&&url.protocol==='file:')pairs.push({node:img,url,kind:'img',attr:raw});
 }
 const current=[root,...root.querySelectorAll('*')],sources=[original,...original.querySelectorAll('*')];
 current.forEach((node,i)=>{
  const source=sources[i];if(!source)return;let bg='';
  try{bg=(source.ownerDocument.defaultView||window).getComputedStyle(source).backgroundImage||'';}catch(_){}
  if(!bg||bg==='none')return;
  for(const match of bg.matchAll(/url\(["']?([^"')]+)["']?\)/g)){
   try{const url=new URL(match[1],source.ownerDocument.baseURI||document.baseURI);if(url.protocol==='file:')pairs.push({node,url,kind:'bg',background:bg,match:match[1],old:node.style.backgroundImage});}catch(_){}
  }
 });
 if(!pairs.length)return ()=>{};
 const ui=janela.frameElement?window:janela,cache=new Map();let directory;
 try{directory=await atletasMapaSelecionarPastaPrincipal(ui);}catch(e){throw e;}
 if(!directory){
  const transparent='data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';
  for(const item of pairs){
   if(item.kind==='img'){restore.push(()=>item.node.setAttribute('src',item.attr));item.node.setAttribute('src',transparent);}
   else{restore.push(()=>{item.node.style.backgroundImage=item.old;});item.node.style.backgroundImage='none';}
  }
  return ()=>restore.reverse().forEach(fn=>fn());
 }
 try{
  for(const item of pairs){
   const href=item.url.href.split('#')[0].split('?')[0];
   if(!href.startsWith(base.href))throw new Error('Uma imagem está fora da pasta do Sistema Principal. Mantenha logo.png junto de index.html.');
   const path=href.slice(base.href.length).split('/').map(decodeURIComponent).filter(Boolean);
   if(!path.length||path.some(part=>part==='.'||part==='..'||part.includes('\\')||part.includes('/')))throw new Error('Caminho de imagem local inválido.');
   let objectUrl=cache.get(href);
   if(!objectUrl){
    let folder=directory;for(const part of path.slice(0,-1))folder=await folder.getDirectoryHandle(part);
    const file=await (await folder.getFileHandle(path[path.length-1])).getFile();
    objectUrl=view.URL.createObjectURL(file);cache.set(href,objectUrl);
   }
   if(item.kind==='img'){restore.push(()=>item.node.setAttribute('src',item.attr));item.node.setAttribute('src',objectUrl);}
   else{restore.push(()=>{item.node.style.backgroundImage=item.old;});item.node.style.backgroundImage=item.background.replace(item.match,objectUrl);}
  }
  await Promise.all(images.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{let done=false;const finish=()=>{if(done)return;done=true;img.removeEventListener('load',finish);img.removeEventListener('error',finish);resolve();};img.addEventListener('load',finish);img.addEventListener('error',finish);setTimeout(finish,5000);} )));
  return ()=>{restore.reverse().forEach(fn=>fn());for(const url of cache.values())view.URL.revokeObjectURL(url);};
 }catch(e){
  restore.reverse().forEach(fn=>fn());for(const url of cache.values())view.URL.revokeObjectURL(url);
  atletasMapaPastaImagensLocalPrincipal=null;
  throw new Error('Não foi possível ler uma imagem local. Confira se escolheu a pasta do Sistema Principal e se logo.png está nela. '+(e?.message||''));
 }
}
function atletasMapaAguardarImagensPrincipal(root){
 return Promise.all([...root.querySelectorAll('img')].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{let done=false;const finish=()=>{if(done)return;done=true;img.removeEventListener('load',finish);img.removeEventListener('error',finish);resolve();};img.addEventListener('load',finish);img.addEventListener('error',finish);setTimeout(finish,6000);}))); 
}
async function atletasMapaGerarPDFPrincipal(snapshot){
 const html2pdfFn=typeof window.html2pdf==='function'?window.html2pdf:null;
 const Pdf=window.jspdf?.jsPDF||window.jsPDF;
 if(!html2pdfFn)throw new Error('A biblioteca local de PDF não carregou. Confira se a pasta vendor foi copiada junto com o Sistema Principal.');
 if(typeof Pdf!=='function')throw new Error('A biblioteca local jsPDF não carregou. Confira vendor/jspdf.umd.min.js.');
 const holder=document.createElement('div');holder.className='atleta-mapa-export-holder';holder.innerHTML=atletasMapaPaginaPrincipal(snapshot,'pdf');document.body.appendChild(holder);
 let restoreImages=()=>{},canvas=null;
 try{
  const page=holder.firstElementChild;
  restoreImages=await atletasMapaPrepararImagensLocaisPrincipal(page,page,window);
  await atletasMapaAguardarImagensPrincipal(page);
  const worker=html2pdfFn().set({margin:0,pagebreak:{mode:[]},image:{type:'jpeg',quality:.97},html2canvas:{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#ffffff',scrollX:0,scrollY:0},jsPDF:{unit:'mm',format:'a4',orientation:'portrait',compress:true}}).from(page);
  canvas=await worker.toCanvas().get('canvas');
  if(!canvas||!canvas.width||!canvas.height)throw new Error('Não foi possível renderizar o mapa A4. Use a opção Imprimir.');
  const pdf=new Pdf({unit:'mm',format:'a4',orientation:'portrait',compress:true});
  const pageWidth=pdf.internal.pageSize.getWidth(),pageHeight=pdf.internal.pageSize.getHeight();
  const scale=Math.min(pageWidth/canvas.width,pageHeight/canvas.height),width=canvas.width*scale,height=canvas.height*scale;
  const x=(pageWidth-width)/2,y=(pageHeight-height)/2,img=canvas.toDataURL('image/jpeg',.97);
  if(!img||img==='data:,')throw new Error('O mapa excedeu a capacidade de imagem deste dispositivo.');
  pdf.addImage(img,'JPEG',x,y,width,height,'MAPA_A4','FAST');
  const blob=pdf.output('blob');
  if(!(blob instanceof Blob)||!blob.size)throw new Error('O PDF gerado ficou vazio. Use a opção Imprimir.');
  return blob;
 }finally{
  restoreImages();if(canvas){canvas.width=0;canvas.height=0;}holder.remove();
 }
}

async function atletasMapaExportarPDFPrincipal(modo,modal){
 if(atletasMapaExportandoPrincipal||!atletasMapaCategoriaSnapshotPrincipal)return;
 atletasMapaExportandoPrincipal=true;
 const snapshot=atletasMapaCategoriaSnapshotPrincipal,status=modal.querySelector('.atleta-mapa-export-status'),buttons=[...modal.querySelectorAll('button')];
 buttons.forEach(b=>b.disabled=true);status.textContent='Preparando o mapa A4…';
 try{
  const blob=await atletasMapaGerarPDFPrincipal(snapshot),nome=atletasMapaNomeArquivoPDFPrincipal(snapshot);
  if(modo==='export'){
   const file=new File([blob],nome,{type:'application/pdf'});let canShare=false;
   try{canShare=typeof navigator.share==='function'&&(!navigator.canShare||navigator.canShare({files:[file]}));}catch(_e){}
   if(canShare){await navigator.share({files:[file],title:'Mapa da categoria',text:snapshot.filterLabel});modal.remove();return;}
  }
  atletasMapaBaixarBlobPrincipal(blob,nome);status.textContent=modo==='export'?'PDF exportado para os downloads.':'PDF salvo nos downloads.';
  setTimeout(()=>{if(modal.isConnected)modal.remove();},900);
 }catch(e){
  if(e?.name==='AbortError'){modal.remove();return;}
  console.error('Erro ao gerar PDF do mapa:',e);status.textContent=e?.message||'Não foi possível gerar o PDF. Tente Imprimir.';
  buttons.forEach(b=>b.disabled=false);
 }finally{atletasMapaExportandoPrincipal=false;}
}
