function atletasMapaImprimirPrincipal(){
 const snapshot=atletasMapaCategoriaSnapshotPrincipal;if(!snapshot)return;
 const w=window.open('','_blank','width=900,height=1000');if(!w){alert('Não foi possível abrir a impressão. Permita pop-ups e tente novamente.');return;}
 const logoUrl=new URL('logo.png',document.baseURI).href,logoEsc=atletasEscaparHtml(logoUrl);
 const html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+atletasEscaparHtml(atletasMapaNomeArquivoPDFPrincipal(snapshot).replace(/\.pdf$/i,''))+'</title><style>'+atletasMapaEstiloImpressaoPrincipal()+'</style></head><body>'+atletasMapaPaginaPrincipal(snapshot,'print',logoEsc)+'</body></html>';
 try{
  w.document.open();w.document.write(html);w.document.close();
  atletasMapaAguardarImagensPrincipal(w.document.body).then(()=>{w.focus();setTimeout(()=>w.print(),300);});
 }catch(e){console.error('Erro ao preparar impressão do mapa:',e);w.close();alert('Não foi possível preparar a impressão. Tente Salvar PDF.');}
}
